export enum UserRole {
  ADMIN = 'ADMIN',
  TEACHER = 'TEACHER',
  PARENT = 'PARENT'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  pin: string;
}

export interface Teacher extends User {
  subject?: string;
  email?: string;
}

export interface Student {
  id: string;
  name: string;
  grade: string;
  parentPin: string;
  parentName: string;
}

export interface MenuItem {
