import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { verifyAdminPin, searchTeachers, searchStudents } from '../services/dataService';
import { UserRole, Teacher, Student } from '../types';
import { User, ShieldCheck, GraduationCap } from 'lucide-react';

interface LoginProps {
  onLogin: (role: UserRole, user: any) => void;
}

export const LoginPage: React.FC<LoginProps> = ({ onLogin }) => {
  const [activeTab, setActiveTab] = useState<'ADMIN' | 'TEACHER' | 'PARENT'>('ADMIN');
  const [pin, setPin] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [selectedUser, setSelectedUser] = useState<any>(null);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (verifyAdminPin(pin)) {
      onLogin(UserRole.ADMIN, { name: 'Administrator', id: 'admin' });
      navigate('/admin/dashboard');
    } else {
      setError('Invalid PIN. Try 8888 for demo.');
    }
  };

  const handleSearch = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const term = e.target.value;
    setSearchTerm(term);
    setSelectedUser(null);
    setPin('');
    setError('');

    if (term.length > 1) {
      if (activeTab === 'TEACHER') {
        const results = await searchTeachers(term);
        setSearchResults(results);
      } else if (activeTab === 'PARENT') {
        const results = await searchStudents(term);
        setSearchResults(results);
      }
    } else {
      setSearchResults([]);
    }
  };

  const handleUserSelect = (user: any) => {
    setSelectedUser(user);
    setSearchResults([]);
    setSearchTerm(activeTab === 'PARENT' ? user.name : user.name);
  };

  const handleUserLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) {
      setError('Please select a user first');
      return;
    }

    if (activeTab === 'TEACHER') {
      if (selectedUser.pin === pin) {
        onLogin(UserRole.TEACHER, selectedUser);
        navigate('/teacher/dashboard');
      } else {
        setError('Incorrect PIN');
      }
    } else if (activeTab === 'PARENT') {
      if (selectedUser.parentPin === pin) {
        onLogin(UserRole.PARENT, { ...selectedUser, name: selectedUser.parentName });
        navigate('/parent/dashboard');
      } else {
        setError('Incorrect PIN');
      }
    }
  };

  return (
    <div className="min-h-screen bg-coha-900 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-8 text-center bg-gray-50 border-b border-gray-200">
          <img src="https://i.ibb.co/LzYXwYfX/logo.png" alt="COHA Logo" className="h-20 w-auto mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-coha-900 uppercase tracking-widest">Portal Login</h2>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200">
          <button
            onClick={() => { setActiveTab('ADMIN'); setSelectedUser(null); setSearchTerm(''); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex justify-center items-center gap-2 ${activeTab === 'ADMIN' ? 'bg-white text-coha-900 border-b-4 border-coha-900' : 'bg-gray-100 text-gray-500'}`}
          >
            <ShieldCheck size={18} /> Admin
          </button>
          <button
            onClick={() => { setActiveTab('TEACHER'); setSelectedUser(null); setSearchTerm(''); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex justify-center items-center gap-2 ${activeTab === 'TEACHER' ? 'bg-white text-coha-900 border-b-4 border-coha-900' : 'bg-gray-100 text-gray-500'}`}
          >
            <User size={18} /> Teacher
          </button>
          <button
            onClick={() => { setActiveTab('PARENT'); setSelectedUser(null); setSearchTerm(''); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex justify-center items-center gap-2 ${activeTab === 'PARENT' ? 'bg-white text-coha-900 border-b-4 border-coha-900' : 'bg-gray-100 text-gray-500'}`}
          >
            <GraduationCap size={18} /> Parent
          </button>
        </div>

        {/* Body */}
        <div className="p-8">
          {activeTab === 'ADMIN' && (
            <form onSubmit={handleAdminLogin}>
              <p className="mb-6 text-gray-600 text-sm">Enter your administrative PIN to access the dashboard.</p>
              <Input
                type="password"
                label="Security PIN"
                placeholder="Enter PIN"
                value={pin}
                onChange={(e) => setPin(e.target.value)}
                maxLength={4}
                autoFocus
              />
              {error && <p className="text-red-600 mb-4 font-medium">{error}</p>}
              <Button type="submit" fullWidth>Access Dashboard</Button>
            </form>
          )}

          {(activeTab === 'TEACHER' || activeTab === 'PARENT') && (
            <form onSubmit={handleUserLogin}>
              {!selectedUser ? (
                <div className="relative">
                   <p className="mb-6 text-gray-600 text-sm">
                    {activeTab === 'TEACHER' ? 'Search for your name to begin.' : 'Search for the student name.'}
                  </p>
                  <Input
                    label={activeTab === 'TEACHER' ? "Search Name" : "Student Name"}
                    placeholder="Start typing..."
                    value={searchTerm}
                    onChange={handleSearch}
                  />
                  {searchResults.length > 0 && (
                    <div className="absolute top-[85px] left-0 w-full bg-white border-2 border-coha-500 z-10 max-h-48 overflow-y-auto shadow-lg">
                      {searchResults.map((item) => (
                        <div
                          key={item.id}
                          onClick={() => handleUserSelect(item)}
                          className="p-3 hover:bg-coha-50 cursor-pointer border-b border-gray-100 last:border-0"
                        >
                          <p className="font-bold text-coha-900">{item.name}</p>
                          {activeTab === 'PARENT' && <p className="text-xs text-gray-500">Grade: {item.grade}</p>}
                          {activeTab === 'TEACHER' && <p className="text-xs text-gray-500">{item.subject}</p>}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <div className="animate-fade-in">
                  <div className="bg-coha-50 p-4 mb-4 border-l-4 border-coha-500 flex justify-between items-center">
                    <div>
                      <p className="text-xs text-gray-500 uppercase">Selected</p>
                      <p className="font-bold text-coha-900">{selectedUser.name}</p>
                    </div>
                    <button type="button" onClick={() => { setSelectedUser(null); setSearchTerm(''); }} className="text-sm text-red-500 underline">Change</button>
                  </div>
                  <Input
                    type="password"
                    label="Enter PIN"
                    placeholder="****"
                    value={pin}
                    onChange={(e) => setPin(e.target.value)}
                    maxLength={4}
                    autoFocus
                  />
                  {error && <p className="text-red-600 mb-4 font-medium">{error}</p>}
                  <Button type="submit" fullWidth>Login</Button>
                </div>
              )}
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { addTeacher, getTeachers } from '../../services/dataService';
import { Teacher } from '../../types';
import { Plus, Search } from 'lucide-react';

export const TeachersPage: React.FC = () => {
  const [teachers, setTeachers] = useState<Teacher[]>([]);
  const [showForm, setShowForm] = useState(false);

  // Form State
  const [name, setName] = useState('');
  const [subject, setSubject] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchTeachers = async () => {
    const data = await getTeachers();
    setTeachers(data);
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const success = await addTeacher(name, subject);
    if (success) {
      setName('');
      setSubject('');
      setShowForm(false);
      fetchTeachers();
    }
    setLoading(false);
  };

  return (
    <div>
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-coha-900">Teachers</h2>
          <p className="text-gray-600">Manage faculty members.</p>
        </div>
        <Button onClick={() => setShowForm(!showForm)}>
          <Plus size={20} /> Add Teacher
        </Button>
      </div>

      {showForm && (
        <div className="bg-white p-6 mb-8 border-t-4 border-coha-500 shadow-lg animate-fade-in">
          <h3 className="text-lg font-bold mb-4">Add New Teacher</h3>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input 
              label="Full Name" 
              placeholder="e.g. Mrs. Sarah Smith" 
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
            <Input 
              label="Subject" 
              placeholder="e.g. Mathematics" 
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              required
            />
            <div className="md:col-span-2 flex justify-end gap-2 mt-2">
              <Button type="button" variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button type="submit" disabled={loading}>{loading ? 'Saving...' : 'Save Teacher'}</Button>
            </div>
          </form>
        </div>
      )}

      <div className="bg-white border border-gray-200 shadow-sm">
        <div className="p-4 border-b border-gray-200 flex gap-2">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-3 text-gray-400" size={20} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-300 focus:border-coha-500 outline-none rounded-none"
              placeholder="Search teachers..." 
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">Subject</th>
                <th className="px-6 py-4">Default PIN</th>
                <th className="px-6 py-4">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {teachers.map((teacher) => (
                <tr key={teacher.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 font-bold text-coha-900">{teacher.name}</td>
                  <td className="px-6 py-4">{teacher.subject}</td>
                  <td className="px-6 py-4 font-mono text-gray-500">1234</td>
                  <td className="px-6 py-4">
                    <button className="text-coha-500 hover:text-coha-700 font-bold text-sm">Edit</button>
                  </td>
                </tr>
              ))}
              {teachers.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-6 py-8 text-center text-gray-500">No teachers found. Add one to get started.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
