export const StudentsPage: React.FC = () => {
  const [students, setStudents] = useState<Student[]>([]);
  const [showForm, setShowForm] = useState(false);

  // Form State
  const [name, setName] = useState('');
  const [grade, setGrade] = useState('');
  const [parentName, setParentName] = useState('');
  const [parentPin, setParentPin] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchStudents = async () => {
    const data = await getStudents();
    setStudents(data);
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const success = await addStudent(name, grade, parentName, parentPin);
    if (success) {
      setName('');
      setGrade('');
      setParentName('');
      setParentPin('');
      setShowForm(false);
      fetchStudents();
    }
    setLoading(false);
  };

  return (
    <div>
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-coha-900">Students</h2>
          <p className="text-gray-600">Manage student enrollment.</p>
        </div>
        <Button onClick={() => setShowForm(!showForm)}>
          <Plus size={20} /> Add Student
        </Button>
      </div>

      {showForm && (
        <div className="bg-white p-6 mb-8 border-t-4 border-coha-500 shadow-lg animate-fade-in">
          <h3 className="text-lg font-bold mb-4">Enroll New Student</h3>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input 
              label="Student Name" 
              placeholder="e.g. John Doe" 
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
            <Input 
              label="Grade/Class" 
              placeholder="e.g. Grade 5A" 
              value={grade}
              onChange={(e) => setGrade(e.target.value)}
              required
            />
             <Input 
              label="Parent Name" 
              placeholder="e.g. Mr. James Doe" 
              value={parentName}
              onChange={(e) => setParentName(e.target.value)}
              required
            />
             <Input 
              label="Assign Parent PIN" 
              placeholder="e.g. 5678" 
              maxLength={4}
              value={parentPin}
              onChange={(e) => setParentPin(e.target.value)}
              required
            />
            <div className="md:col-span-2 flex justify-end gap-2 mt-2">
              <Button type="button" variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button type="submit" disabled={loading}>{loading ? 'Saving...' : 'Enroll Student'}</Button>
            </div>
          </form>
        </div>
      )}

      <div className="bg-white border border-gray-200 shadow-sm">
        <div className="p-4 border-b border-gray-200 flex gap-2">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-3 text-gray-400" size={20} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-300 focus:border-coha-500 outline-none rounded-none"
              placeholder="Search students..." 
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold">
              <tr>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4">Grade</th>
                <th className="px-6 py-4">Parent</th>
                <th className="px-6 py-4">Parent PIN</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {students.map((student) => (
                <tr key={student.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 font-bold text-coha-900">{student.name}</td>
                  <td className="px-6 py-4">
                     <span className="bg-coha-100 text-coha-800 px-2 py-1 text-xs font-bold uppercase">{student.grade}</span>
                  </td>
                  <td className="px-6 py-4">{student.parentName}</td>
                  <td className="px-6 py-4 font-mono text-gray-500">****</td>
                </tr>
              ))}
               {students.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-6 py-8 text-center text-gray-500">No students found.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Sidebar } from './components/Sidebar';
import { Header } from './components/Header';
import { LandingPage } from './pages/LandingPage';
import { LoginPage } from './pages/LoginPage';
import { AdminDashboard } from './pages/admin/Dashboard';
import { TeachersPage } from './pages/admin/Teachers';
import { StudentsPage } from './pages/admin/Students';
import { UserRole } from './types';

// Layout Component to wrap protected routes
const AppLayout: React.FC<{ 
  children: React.ReactNode; 
  role: UserRole; 
  user: any; 
  onLogout: () => void 
}> = ({ children, role, user, onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);

  return (
    <div className="min-h-screen bg-gray-50 flex font-sans">
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)} 
        role={role}
        onLogout={onLogout}
      />
      <div className="flex-1 flex flex-col min-w-0">
        <Header 
          onMenuClick={() => setSidebarOpen(!sidebarOpen)} 
          role={role}
          userName={user?.name}
        />
        <main className="flex-1 p-4 lg:p-8 overflow-y-auto">
          {children}
        </main>
      </div>
    </div>
  );
};

const ProtectedRoute: React.FC<{
  isAuthenticated: boolean;
  userRole: UserRole | null;
  allowedRoles: UserRole[];
  children: React.ReactNode;
}> = ({ isAuthenticated, userRole, allowedRoles, children }) => {
  if (!isAuthenticated) return <Navigate to="/login" replace />;
  if (userRole && !allowedRoles.includes(userRole)) return <Navigate to="/" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [role, setRole] = useState<UserRole | null>(null);

  const handleLogin = (newRole: UserRole, newUser: any) => {
    setUser(newUser);
    setRole(newRole);
  };

  const handleLogout = () => {
    setUser(null);
    setRole(null);
  };

  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />

        {/* Admin Routes */}
        <Route path="/admin/*" element={
          <ProtectedRoute isAuthenticated={!!user} userRole={role} allowedRoles={[UserRole.ADMIN]}>
            <AppLayout role={UserRole.ADMIN} user={user} onLogout={handleLogout}>
              <Routes>
                <Route path="dashboard" element={<AdminDashboard />} />
                <Route path="teachers" element={<TeachersPage />} />
                <Route path="students" element={<StudentsPage />} />
                <Route path="*" element={<Navigate to="dashboard" />} />
              </Routes>
            </AppLayout>
          </ProtectedRoute>
        } />

        {/* Teacher Routes - Placeholders */}
        <Route path="/teacher/*" element={
          <ProtectedRoute isAuthenticated={!!user} userRole={role} allowedRoles={[UserRole.TEACHER]}>
            <AppLayout role={UserRole.TEACHER} user={user} onLogout={handleLogout}>
              <div className="p-8 text-center text-gray-500">Teacher Dashboard Content Here</div>
            </AppLayout>
          </ProtectedRoute>
        } />

         {/* Parent Routes - Placeholders */}
         <Route path="/parent/*" element={
          <ProtectedRoute isAuthenticated={!!user} userRole={role} allowedRoles={[UserRole.PARENT]}>
             <AppLayout role={UserRole.PARENT} user={user} onLogout={handleLogout}>
              <div className="p-8 text-center text-gray-500">Parent Dashboard Content Here</div>
            </AppLayout>
          </ProtectedRoute>
        } />

      </Routes>
    </HashRouter>
  );
};

export default App;

