import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { verifyAdminPin, searchTeachers, searchStudents } from '../services/dataService';
import { UserRole, Teacher, Student } from '../types';
import { User, ShieldCheck, GraduationCap } from 'lucide-react';

interface LoginProps {
  onLogin: (role: UserRole, user: any) => void;
}

export const LoginPage: React.FC<LoginProps> = ({ onLogin }) => {
  const [activeTab, setActiveTab] = useState<'ADMIN' | 'TEACHER' | 'PARENT'>('ADMIN');
  const [pin, setPin] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [selectedUser, setSelectedUser] = useState<any>(null);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (verifyAdminPin(pin)) {
      onLogin(UserRole.ADMIN, { name: 'Administrator', id: 'admin' });
      navigate('/admin/dashboard');
    } else {
      setError('Invalid PIN. Try 8888 for demo.');
    }
  };

  const handleSearch = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const term = e.target.value;
    setSearchTerm(term);
    setSelectedUser(null);
    setPin('');
    setError('');

    if (term.length > 1) {
      if (activeTab === 'TEACHER') {
        const results = await searchTeachers(term);
        setSearchResults(results);
      } else if (activeTab === 'PARENT') {
        const results = await searchStudents(term);
        setSearchResults(results);
      }
    } else {
      setSearchResults([]);
    }
  };

  const handleUserSelect = (user: any) => {
    setSelectedUser(user);
    setSearchResults([]);
    setSearchTerm(activeTab === 'PARENT' ? user.name : user.name);
  };

  const handleUserLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) {
      setError('Please select a user first');
      return;
    }

    if (activeTab === 'TEACHER') {
      if (selectedUser.pin === pin) {
        onLogin(UserRole.TEACHER, selectedUser);
        navigate('/teacher/dashboard');
      } else {
        setError('Incorrect PIN');
      }
    } else if (activeTab === 'PARENT') {
      if (selectedUser.parentPin === pin) {
        onLogin(UserRole.PARENT, { ...selectedUser, name: selectedUser.parentName });
        navigate('/parent/dashboard');
      } else {
        setError('Incorrect PIN');
      }
    }
  };

  return (
    <div className="min-h-screen bg-coha-900 flex items-center justify-center p-4">
      {/* Added h-[600px] and flex flex-col to keep size fixed */}
      <div className="bg-white w-full max-w-md shadow-2xl overflow-hidden h-[600px] flex flex-col">
        {/* Header */}
        <div className="p-8 text-center bg-gray-50 border-b border-gray-200 shrink-0">
          <img src="https://i.ibb.co/LzYXwYfX/logo.png" alt="COHA Logo" className="h-20 w-auto mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-coha-900 uppercase tracking-widest">Portal Login</h2>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 shrink-0">
          <button
            onClick={() => { setActiveTab('ADMIN'); setSelectedUser(null); setSearchTerm(''); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex justify-center items-center gap-2 transition-colors ${activeTab === 'ADMIN' ? 'bg-white text-coha-900 border-b-4 border-coha-900' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}
          >
            <ShieldCheck size={18} /> Admin
          </button>
          <button
            onClick={() => { setActiveTab('TEACHER'); setSelectedUser(null); setSearchTerm(''); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex justify-center items-center gap-2 transition-colors ${activeTab === 'TEACHER' ? 'bg-white text-coha-900 border-b-4 border-coha-900' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}
          >
            <User size={18} /> Teacher
          </button>
          <button
            onClick={() => { setActiveTab('PARENT'); setSelectedUser(null); setSearchTerm(''); setError(''); }}
            className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex justify-center items-center gap-2 transition-colors ${activeTab === 'PARENT' ? 'bg-white text-coha-900 border-b-4 border-coha-900' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}
          >
            <GraduationCap size={18} /> Parent
          </button>
        </div>

        {/* Body */}
        <div className="p-8 flex-1 overflow-y-auto relative">
          {activeTab === 'ADMIN' && (
            <form onSubmit={handleAdminLogin} className="animate-fade-in">
              <p className="mb-6 text-gray-600 text-sm">Enter your administrative PIN to access the dashboard.</p>
              <Input
                type="password"
                label="Security PIN"
                placeholder="Enter PIN"
                value={pin}
                onChange={(e) => setPin(e.target.value)}
                maxLength={4}
                autoFocus
              />
              {error && <p className="text-red-600 mb-4 font-medium">{error}</p>}
              <Button type="submit" fullWidth>Access Dashboard</Button>
            </form>
          )}

          {(activeTab === 'TEACHER' || activeTab === 'PARENT') && (
            <form onSubmit={handleUserLogin} className="animate-fade-in h-full">
              {!selectedUser ? (
                <div className="relative">
                   <p className="mb-6 text-gray-600 text-sm">
                    {activeTab === 'TEACHER' ? 'Search for your name to begin.' : 'Search for the student name.'}
                  </p>
                  <Input
                    label={activeTab === 'TEACHER' ? "Search Name" : "Student Name"}
                    placeholder="Start typing..."
                    value={searchTerm}
                    onChange={handleSearch}
                  />
                  {searchResults.length > 0 && (
                    <div className="absolute top-[85px] left-0 w-full bg-white border-2 border-coha-500 z-10 max-h-48 overflow-y-auto shadow-lg">
                      {searchResults.map((item) => (
                        <div
                          key={item.id}
                          onClick={() => handleUserSelect(item)}
                          className="p-3 hover:bg-coha-50 cursor-pointer border-b border-gray-100 last:border-0"
                        >
                          <p className="font-bold text-coha-900">{item.name}</p>
                          {activeTab === 'PARENT' && <p className="text-xs text-gray-500">Grade: {item.grade}</p>}
                          {activeTab === 'TEACHER' && <p className="text-xs text-gray-500">{item.subject}</p>}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <div className="animate-fade-in">
                  <div className="bg-coha-50 p-4 mb-4 border-l-4 border-coha-500 flex justify-between items-center">
                    <div>
                      <p className="text-xs text-gray-500 uppercase">Selected</p>
                      <p className="font-bold text-coha-900">{selectedUser.name}</p>
                    </div>
                    <button type="button" onClick={() => { setSelectedUser(null); setSearchTerm(''); }} className="text-sm text-red-500 underline">Change</button>
                  </div>
                  <Input
                    type="password"
                    label="Enter PIN"
                    placeholder="****"
                    value={pin}
                    onChange={(e) => setPin(e.target.value)}
                    maxLength={4}
                    autoFocus
                  />
                  {error && <p className="text-red-600 mb-4 font-medium">{error}</p>}
                  <Button type="submit" fullWidth>Login</Button>
                </div>
              )}
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { CheckCircle } from 'lucide-react';

interface ToastProps {
  message: string;
  isVisible: boolean;
  onClose: () => void;
}

export const Toast: React.FC<ToastProps> = ({ message, isVisible, onClose }) => {
  const [show, setShow] = useState(false);

  useEffect(() => {
    if (isVisible) {
      setShow(true);
      // Show for 1 second as requested
      const timer = setTimeout(() => {
        setShow(false);
        // Wait for slide out animation to finish before calling onClose cleanup
        setTimeout(onClose, 300); 
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [isVisible, onClose]);

  return (
    <div
      className={`fixed top-4 right-4 z-50 flex items-center gap-3 bg-coha-900 text-white px-6 py-4 shadow-2xl border-l-4 border-coha-400 transform transition-transform duration-300 ease-in-out ${
        show ? 'translate-x-0' : 'translate-x-[200%]'
      }`}
    >
      <CheckCircle className="text-coha-400" size={24} />
      <span className="font-semibold tracking-wide">{message}</span>
    </div>
  );
};

import { db, auth } from '../firebase';
import { collection, addDoc, getDocs, query, where, doc, updateDoc, deleteDoc } from 'firebase/firestore';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { Teacher, Student, UserRole } from '../types';

// Collections
const TEACHERS_COLLECTION = 'teachers';
const STUDENTS_COLLECTION = 'students';

// Admin Auth Configuration
const ADMIN_EMAIL = "admin@coha.com";
// Firebase requires min 6 chars, so we map '1111' to '111111' internally
const ADMIN_AUTH_PASSWORD = "111111"; 

// Seed Admin User
export const seedAdminUser = async () => {
  try {
    // We attempt to create the user. If they exist, it throws an error which we ignore.
    await createUserWithEmailAndPassword(auth, ADMIN_EMAIL, ADMIN_AUTH_PASSWORD);
    console.log("Admin user seeded successfully.");
  } catch (error: any) {
    if (error.code === 'auth/email-already-in-use') {
      // Admin already exists, this is expected after first run
      console.log("Admin user already exists.");
    } else {
      console.error("Error seeding admin user:", error);
    }
  }
};

// Teachers
export const addTeacher = async (name: string, subject: string) => {
  try {
    // Add to Firestore for the "Search" functionality
    await addDoc(collection(db, TEACHERS_COLLECTION), {
      name,
      subject,
      role: UserRole.TEACHER,
      pin: '1234', // Default PIN as requested
      createdAt: new Date()
    });

    // Note: In a real production app, we would also create a Firebase Auth user here.
    // However, the client SDK does not allow creating a secondary user without logging out the admin.
    // Since the requirement relies on a custom "Search Name -> Enter PIN" flow, 
    // the Firestore document acts as the source of truth for this specific login method.

    return true;
  } catch (error) {
    console.error("Error adding teacher: ", error);
    return false;
  }
};

export const getTeachers = async (): Promise<Teacher[]> => {
  const q = query(collection(db, TEACHERS_COLLECTION));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Teacher));
};

export const searchTeachers = async (searchTerm: string): Promise<Teacher[]> => {
  if (!searchTerm) return [];
  const all = await getTeachers();
  return all.filter(t => t.name.toLowerCase().includes(searchTerm.toLowerCase()));
};

// Students
export const addStudent = async (name: string, grade: string, parentName: string, parentPin: string) => {
  try {
    await addDoc(collection(db, STUDENTS_COLLECTION), {
      name,
      grade,
      parentName,
      parentPin,
      role: UserRole.PARENT,
      createdAt: new Date()
    });
    return true;
  } catch (error) {
    console.error("Error adding student: ", error);
    return false;
  }
};

export const getStudents = async (): Promise<Student[]> => {
  const q = query(collection(db, STUDENTS_COLLECTION));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Student));
};

export const searchStudents = async (searchTerm: string): Promise<Student[]> => {
  if (!searchTerm) return [];
  const all = await getStudents();
  return all.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()));
};

// Admin Auth
export const verifyAdminPin = async (pin: string): Promise<boolean> => {
  // Check if PIN matches the specific requirement '1111'
  if (pin !== '1111') return false;

  try {
    // Authenticate with Firebase using the mapped password
    await signInWithEmailAndPassword(auth, ADMIN_EMAIL, ADMIN_AUTH_PASSWORD);
    return true;
  } catch (error) {
    console.error("Admin login failed:", error);
    return false;
  }
};

