// Teachers
export const addTeacher = async (name: string, subject: string) => {
  try {
    await addDoc(collection(db, TEACHERS_COLLECTION), {
      name,
      subject,
      role: UserRole.TEACHER,
      pin: '1234',
      createdAt: new Date()
    });
    return true;
  } catch (error) {
    console.error("Error adding teacher: ", error);
    return false;
  }
};

export const getTeachers = async (): Promise<Teacher[]> => {
  const q = query(collection(db, TEACHERS_COLLECTION));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Teacher));
};

export const searchTeachers = async (searchTerm: string): Promise<Teacher[]> => {
  if (!searchTerm) return [];
  const all = await getTeachers();
  return all.filter(t => t.name.toLowerCase().includes(searchTerm.toLowerCase()));
};

// Students
export const addStudent = async (name: string, grade: string, parentName: string, parentPin: string) => {
  try {
    await addDoc(collection(db, STUDENTS_COLLECTION), {
      name,
      grade,
      parentName,
      parentPin,
      role: UserRole.PARENT,
      createdAt: new Date()
    });
    return true;
  } catch (error) {
    console.error("Error adding student: ", error);
    return false;
  }
};

export const getStudents = async (): Promise<Student[]> => {
  const q = query(collection(db, STUDENTS_COLLECTION));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Student));
};

export const searchStudents = async (searchTerm: string): Promise<Student[]> => {
  if (!searchTerm) return [];
  const all = await getStudents();
  return all.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()));
};

// Admin Auth
export const verifyAdminPin = async (pin: string): Promise<boolean> => {
  const settings = await getSystemSettings();
  const validPin = settings ? settings.adminPin : '1111';

  if (pin !== validPin) return false;

  try {
    await signInWithEmailAndPassword(auth, ADMIN_EMAIL, ADMIN_AUTH_PASSWORD);
    return true;
  } catch (error) {
    console.error("Admin login failed:", error);
    return false;
  }
};

export const getAdminProfile = async () => {
  const settings = await getSystemSettings();
  return { 
    name: settings?.adminName || 'Victoria Joel', 
    id: 'admin' 
  };
};

// Applications
export const submitApplication = async (applicationData: Partial<Application>) => {
  try {
    await addDoc(collection(db, APPLICATIONS_COLLECTION), {
      ...applicationData,
      status: 'PENDING',
      submissionDate: Timestamp.now()
    });
    return true;
  } catch (error) {
    console.error("Error submitting application:", error);
    return false;
  }
};

export const getApplications = async (): Promise<Application[]> => {
  const q = query(collection(db, APPLICATIONS_COLLECTION), orderBy('submissionDate', 'desc'));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Application));
};

export const getApplicationById = async (id: string): Promise<Application | null> => {
  const docRef = doc(db, APPLICATIONS_COLLECTION, id);
  const docSnap = await getDoc(docRef);
  if (docSnap.exists()) {
    return { id: docSnap.id, ...docSnap.data() } as Application;
  }
  return null;
};

export const updateApplication = async (id: string, data: Partial<Application>) => {
  try {
    const docRef = doc(db, APPLICATIONS_COLLECTION, id);
    await updateDoc(docRef, data);
    return true;
  } catch (error) {
    console.error("Error updating application:", error);
    return false;
  }
};

// System Settings
export const getSystemSettings = async (): Promise<SystemSettings | null> => {
  const docRef = doc(db, SETTINGS_COLLECTION, 'general');
  const docSnap = await getDoc(docRef);
  if (docSnap.exists()) {
    return docSnap.data() as SystemSettings;
  }
  return null;
};

export const saveSystemSettings = async (settings: Partial<SystemSettings>) => {
  try {
    await setDoc(doc(db, SETTINGS_COLLECTION, 'general'), settings, { merge: true });
    return true;
  } catch (error) {
    console.error("Error saving settings:", error);
    return false;
  }
};

import React, { useEffect, useState } from 'react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { getSystemSettings, saveSystemSettings } from '../../services/dataService';
import { SystemSettings, FeeItem, SupplyItem } from '../../types';
import { Save, User, DollarSign, Package, Calendar, Plus, Trash2, CheckSquare, Square } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

export const SettingsPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'PROFILE' | 'FEES' | 'UNIFORMS' | 'CONFIG'>('PROFILE');
  const [settings, setSettings] = useState<SystemSettings>({
    adminName: '',
    adminPin: '',
    fees: [],
    uniforms: [],
    stationery: [],
    grades: [],
    termStartDate: '',
    termStartTime: ''
  });
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');

  // Local state for new entries
  const [newFee, setNewFee] = useState<FeeItem>({ id: '', category: '', amount: '', frequency: '' });
  const [newUniform, setNewUniform] = useState('');
  const [newStationery, setNewStationery] = useState('');
  const [newGrade, setNewGrade] = useState('');

  useEffect(() => {
    const loadSettings = async () => {
      const data = await getSystemSettings();
      if (data) {
        setSettings({
            ...data,
            fees: data.fees || [],
            uniforms: data.uniforms || [],
            stationery: data.stationery || [],
            grades: data.grades || []
        });
      }
    };
    loadSettings();
  }, []);

  const handleSave = async (e?: React.FormEvent) => {
    if(e) e.preventDefault();
    setLoading(true);
    setSuccessMsg('');
    const success = await saveSystemSettings(settings);
    if (success) {
        setSuccessMsg('Settings saved successfully.');
        setTimeout(() => setSuccessMsg(''), 3000);
    }
    setLoading(false);
  };

  // Fee Management
  const addFee = () => {
    if (newFee.category && newFee.amount) {
      setSettings({
        ...settings,
        fees: [...settings.fees, { ...newFee, id: uuidv4() }]
      });
      setNewFee({ id: '', category: '', amount: '', frequency: '' });
    }
  };

  const removeFee = (id: string) => {
    setSettings({ ...settings, fees: settings.fees.filter(f => f.id !== id) });
  };

  const updateFee = (id: string, field: keyof FeeItem, value: string) => {
    setSettings({
      ...settings,
      fees: settings.fees.map(f => f.id === id ? { ...f, [field]: value } : f)
    });
  };

  // Supplies Management (Uniforms/Stationery)
  const addSupply = (type: 'uniforms' | 'stationery') => {
    const name = type === 'uniforms' ? newUniform : newStationery;
    if (name) {
      const newItem: SupplyItem = { id: uuidv4(), name, isRequired: true };
      setSettings({
        ...settings,
        [type]: [...settings[type], newItem]
      });
      if (type === 'uniforms') setNewUniform('');
      else setNewStationery('');
    }
  };

  const removeSupply = (type: 'uniforms' | 'stationery', id: string) => {
    setSettings({ ...settings, [type]: settings[type].filter(i => i.id !== id) });
  };

  const toggleSupplyRequired = (type: 'uniforms' | 'stationery', id: string) => {
    setSettings({
      ...settings,
      [type]: settings[type].map(i => i.id === id ? { ...i, isRequired: !i.isRequired } : i)
    });
  };

  // Grade Management
  const addGrade = () => {
    if (newGrade && !settings.grades.includes(newGrade)) {
        setSettings({ ...settings, grades: [...settings.grades, newGrade] });
        setNewGrade('');
    }
  };

  const removeGrade = (grade: string) => {
    setSettings({ ...settings, grades: settings.grades.filter(g => g !== grade) });
  };

  return (
    <div className="max-w-6xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
           <h2 className="text-2xl font-bold text-coha-900">System Settings</h2>
           <p className="text-gray-600">Configure school parameters and fees.</p>
        </div>
        <Button onClick={() => handleSave()} disabled={loading}>
            <Save size={20} /> {loading ? 'Saving...' : 'Save All Changes'}
        </Button>
      </div>

      {successMsg && (
        <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 mb-6 flex items-center gap-2">
            <CheckSquare size={20} /> {successMsg}
        </div>
      )}

      {/* Tabs */}
      <div className="bg-white border-b border-gray-200 flex flex-wrap mb-6">
        <button 
            onClick={() => setActiveTab('PROFILE')}
            className={`flex items-center gap-2 px-6 py-4 text-sm font-bold uppercase tracking-wider border-b-4 transition-colors ${activeTab === 'PROFILE' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500 hover:text-coha-900'}`}
        >
            <User size={18} /> Admin Profile
        </button>
        <button 
            onClick={() => setActiveTab('FEES')}
            className={`flex items-center gap-2 px-6 py-4 text-sm font-bold uppercase tracking-wider border-b-4 transition-colors ${activeTab === 'FEES' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500 hover:text-coha-900'}`}
        >
            <DollarSign size={18} /> Fees Structure
        </button>
        <button 
            onClick={() => setActiveTab('UNIFORMS')}
            className={`flex items-center gap-2 px-6 py-4 text-sm font-bold uppercase tracking-wider border-b-4 transition-colors ${activeTab === 'UNIFORMS' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500 hover:text-coha-900'}`}
        >
            <Package size={18} /> Uniforms & Stationery
        </button>
        <button 
            onClick={() => setActiveTab('CONFIG')}
            className={`flex items-center gap-2 px-6 py-4 text-sm font-bold uppercase tracking-wider border-b-4 transition-colors ${activeTab === 'CONFIG' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500 hover:text-coha-900'}`}
        >
            <Calendar size={18} /> School Config
        </button>
      </div>

      <div className="bg-white p-6 shadow-sm border border-gray-200">

        {/* PROFILE TAB */}
        {activeTab === 'PROFILE' && (
          <div className="animate-fade-in max-w-2xl">
             <h3 className="text-lg font-bold text-gray-800 mb-4 pb-2 border-b">Administrator Details</h3>
             <div className="grid gap-6">
                <Input 
                    label="Administrator Name" 
                    value={settings.adminName} 
                    onChange={(e) => setSettings({...settings, adminName: e.target.value})} 
                />
                <Input 
                    label="Login PIN (4 Digits)" 
                    maxLength={4}
                    value={settings.adminPin} 
                    onChange={(e) => setSettings({...settings, adminPin: e.target.value})} 
                />
             </div>
          </div>
        )}

        {/* FEES TAB */}
        {activeTab === 'FEES' && (
          <div className="animate-fade-in">
             <h3 className="text-lg font-bold text-gray-800 mb-4 pb-2 border-b">2026 Fee Structure</h3>

             {/* Fee Table */}
             <div className="overflow-x-auto mb-6">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-600">
                        <tr>
                            <th className="p-3 border-b">Category / Description</th>
                            <th className="p-3 border-b">Amount</th>
                            <th className="p-3 border-b">Frequency / Notes</th>
                            <th className="p-3 border-b w-16"></th>
                        </tr>
                    </thead>
                    <tbody>
                        {settings.fees.map((fee) => (
                            <tr key={fee.id} className="border-b last:border-0 hover:bg-gray-50">
                                <td className="p-2">
                                    <input 
                                        className="w-full p-2 bg-transparent border border-transparent focus:border-coha-500 hover:border-gray-200"
                                        value={fee.category}
                                        onChange={(e) => updateFee(fee.id, 'category', e.target.value)}
                                    />
                                </td>
                                <td className="p-2">
                                    <input 
                                        className="w-full p-2 bg-transparent border border-transparent focus:border-coha-500 hover:border-gray-200 font-mono"
                                        value={fee.amount}
                                        onChange={(e) => updateFee(fee.id, 'amount', e.target.value)}
                                    />
                                </td>
                                <td className="p-2">
                                    <input 
                                        className="w-full p-2 bg-transparent border border-transparent focus:border-coha-500 hover:border-gray-200 text-sm text-gray-600"
                                        value={fee.frequency}
                                        onChange={(e) => updateFee(fee.id, 'frequency', e.target.value)}
                                    />
                                </td>
                                <td className="p-2 text-center">
                                    <button onClick={() => removeFee(fee.id)} className="text-red-500 hover:text-red-700">
                                        <Trash2 size={18} />
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>

             {/* Add Fee Form */}
             <div className="bg-gray-50 p-4 border border-dashed border-gray-300 flex flex-col md:flex-row gap-4 items-end">
                <div className="flex-1 w-full">
                    <Input 
                        label="New Category" 
                        placeholder="e.g. Bus Fare" 
                        value={newFee.category} 
                        onChange={(e) => setNewFee({...newFee, category: e.target.value})}
                        className="mb-0"
                    />
                </div>
                <div className="w-full md:w-32">
                    <Input 
                        label="Amount" 
                        placeholder="N$ 0.00" 
                        value={newFee.amount} 
                        onChange={(e) => setNewFee({...newFee, amount: e.target.value})}
                        className="mb-0"
                    />
                </div>
                <div className="w-full md:w-48">
                    <Input 
                        label="Frequency" 
                        placeholder="Monthly" 
                        value={newFee.frequency} 
                        onChange={(e) => setNewFee({...newFee, frequency: e.target.value})}
                        className="mb-0"
                    />
                </div>
                <Button onClick={addFee} className="h-[50px] mb-[2px]">
                    <Plus size={20} /> Add
                </Button>
             </div>
          </div>
        )}

        {/* UNIFORMS & STATIONERY TAB */}
        {activeTab === 'UNIFORMS' && (
          <div className="animate-fade-in grid grid-cols-1 md:grid-cols-2 gap-8">

             {/* Uniforms Column */}
             <div>
                <h3 className="text-lg font-bold text-gray-800 mb-4 pb-2 border-b flex items-center gap-2">
                    <Package size={20} className="text-coha-500"/> Uniform List
                </h3>
                <ul className="space-y-2 mb-4">
                    {settings.uniforms.map((item) => (
                        <li key={item.id} className="flex items-center justify-between p-3 bg-gray-50 border border-gray-100">
                            <div className="flex items-center gap-3">
                                <button onClick={() => toggleSupplyRequired('uniforms', item.id)} className="text-coha-500">
                                    {item.isRequired ? <CheckSquare size={20} /> : <Square size={20} />}
                                </button>
                                <span className={item.isRequired ? 'font-bold text-gray-800' : 'text-gray-600'}>
                                    {item.name} {item.isRequired ? '' : '(Optional)'}
                                </span>
                            </div>
                            <button onClick={() => removeSupply('uniforms', item.id)} className="text-red-400 hover:text-red-600">
                                <Trash2 size={16} />
                            </button>
                        </li>
                    ))}
                </ul>
                <div className="flex gap-2">
                    <Input 
                        placeholder="Add new uniform item..." 
                        value={newUniform} 
                        onChange={(e) => setNewUniform(e.target.value)}
                        className="mb-0"
                    />
                    <Button onClick={() => addSupply('uniforms')} className="px-4">Add</Button>
                </div>
             </div>

             {/* Stationery Column */}
             <div>
                <h3 className="text-lg font-bold text-gray-800 mb-4 pb-2 border-b flex items-center gap-2">
                    <Package size={20} className="text-coha-500"/> Stationery List
                </h3>
                <ul className="space-y-2 mb-4">
                    {settings.stationery.map((item) => (
                        <li key={item.id} className="flex items-center justify-between p-3 bg-gray-50 border border-gray-100">
                            <div className="flex items-center gap-3">
                                <button onClick={() => toggleSupplyRequired('stationery', item.id)} className="text-coha-500">
                                    {item.isRequired ? <CheckSquare size={20} /> : <Square size={20} />}
                                </button>
                                <span className={item.isRequired ? 'font-bold text-gray-800' : 'text-gray-600'}>
                                    {item.name} {item.isRequired ? '' : '(Optional)'}
                                </span>
                            </div>
                            <button onClick={() => removeSupply('stationery', item.id)} className="text-red-400 hover:text-red-600">
                                <Trash2 size={16} />
                            </button>
                        </li>
                    ))}
                </ul>
                <div className="flex gap-2">
                    <Input 
                        placeholder="Add new stationery item..." 
                        value={newStationery} 
                        onChange={(e) => setNewStationery(e.target.value)}
                        className="mb-0"
                    />
                    <Button onClick={() => addSupply('stationery')} className="px-4">Add</Button>
                </div>
             </div>

          </div>
        )}

        {/* SCHOOL CONFIG TAB */}
        {activeTab === 'CONFIG' && (
            <div className="animate-fade-in grid grid-cols-1 md:grid-cols-2 gap-8">
