    const data = await getStudents();
    setStudents(data);
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const success = await addStudent(name, grade, parentName, parentPin);
    if (success) {
      setName('');
      setGrade('');
      setParentName('');
      setParentPin('');
      setShowForm(false);
      fetchStudents();
