              label="Grade/Class" 
              placeholder="e.g. Grade 5A" 
              value={grade}
              onChange={(e) => setGrade(e.target.value)}
              required
            />
             <Input 
              label="Parent Name" 
              placeholder="e.g. Mr. James Doe" 
              value={parentName}
              onChange={(e) => setParentName(e.target.value)}
