    const studentData = {
        ...app, // Spread all application data (medical, history etc)
        name: `${app.firstName} ${app.surname}`, // Display Name for search
        parentName: app.fatherName || app.motherName, // Display Name for parent column
        parentPin: pin,
        role: UserRole.PARENT,
