export const printStudentProfile = async (student: Student) => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.getWidth();

  // --- Header ---
  const logoUrl = "https://i.ibb.co/LzYXwYfX/logo.png";
  const logoData = await fetchImage(logoUrl);
  if (logoData) {
      doc.addImage(logoData, 'PNG', 14, 10, 25, 25);
  }

  doc.setFontSize(16);
  doc.setTextColor(0, 29, 100); // COHA Blue
  doc.setFont("helvetica", "bold");
  doc.text("CIRCLE OF HOPE ACADEMY", 45, 20);

  doc.setFontSize(9);
  doc.setTextColor(0, 152, 241); // Light Blue
  doc.text("ACCESSIBLE EDUCATION FOR ALL", 45, 25);

  doc.setFontSize(8);
  doc.setTextColor(80, 80, 80);
  doc.setFont("helvetica", "normal");
  doc.text("P.O. Box 3675 Ondangwa", pageWidth - 14, 18, { align: "right" });
  doc.text("Cell: +264 81 666 4074", pageWidth - 14, 22, { align: "right" });
  doc.text("circleofhopeacademy@yahoo.com", pageWidth - 14, 26, { align: "right" });

  // Divider
  doc.setDrawColor(0, 29, 100);
  doc.setLineWidth(0.5);
  doc.line(14, 38, pageWidth - 14, 38);

  // --- Student Summary ---
  doc.setFillColor(245, 247, 250);
  doc.rect(14, 42, pageWidth - 28, 20, 'F');

  doc.setFontSize(14);
  doc.setTextColor(0, 0, 0);
  doc.setFont("helvetica", "bold");
  doc.text(student.name.toUpperCase(), 18, 51);

  doc.setFontSize(9);
  doc.setTextColor(100, 100, 100);
  doc.setFont("helvetica", "normal");
  doc.text(`Grade: ${student.grade || '-'}   |   Student ID: ${student.id.substring(0, 8)}   |   Enrolled: ${student.enrolledAt?.toDate ? student.enrolledAt.toDate().toLocaleDateString() : 'N/A'}`, 18, 57);

  let currentY = 66;

  // --- Common Table Styles ---
  const tableStyles: any = {
      theme: 'grid',
      headStyles: { fillColor: [0, 29, 100], fontSize: 8, fontStyle: 'bold', textColor: 255 },
      bodyStyles: { fontSize: 8, textColor: 50, cellPadding: 1.5 },
      columnStyles: { 0: { fontStyle: 'bold', width: 45, fillColor: [250, 250, 250] } },
      margin: { left: 14, right: 14 }
  };

  // --- Left Column Tables (Learner & Emergency) ---
  // We use the startY of the previous table to place the next one.
  // Since we want columns, we need to manipulate margins/widths or use startY carefully.
  // To ensure it fits on one page, we will stack them cleanly as full width tables but compact.

  // Table 1: Learner Info
  autoTable(doc, {
      startY: currentY,
      head: [[{ content: 'LEARNER INFORMATION', colSpan: 4, styles: { halign: 'left' } }]],
      body: [
          ['Full Name', student.name || '-', 'Date of Birth', student.dob || '-'],
          ['Gender', student.gender || '-', 'Citizenship', student.citizenship || '-'],
          ['Address', { content: student.address || '-', colSpan: 3 }],
          ['Special Needs', student.isSpecialNeeds ? `Yes (${student.specialNeedsType || '-'})` : 'No', 'Parent PIN', student.parentPin || '****']
      ],
      ...tableStyles,
      columnStyles: { 
          0: { fontStyle: 'bold', width: 30, fillColor: [248, 248, 248] },
          1: { width: 60 },
          2: { fontStyle: 'bold', width: 30, fillColor: [248, 248, 248] }
      }
  });

  currentY = (doc as any).lastAutoTable.finalY + 5;

  // Table 2: Parents
  autoTable(doc, {
      startY: currentY,
      head: [[{ content: 'PARENT / GUARDIAN DETAILS', colSpan: 4, styles: { halign: 'left' } }]],
      body: [
          ['Father Name', student.fatherName || '-', 'Father Phone', student.fatherPhone || '-'],
          ['Father Email', { content: student.fatherEmail || '-', colSpan: 3 }],
          ['Mother Name', student.motherName || '-', 'Mother Phone', student.motherPhone || '-']
      ],
      ...tableStyles,
      columnStyles: { 
          0: { fontStyle: 'bold', width: 30, fillColor: [248, 248, 248] },
          1: { width: 60 },
          2: { fontStyle: 'bold', width: 30, fillColor: [248, 248, 248] }
      }
  });

  currentY = (doc as any).lastAutoTable.finalY + 5;

  // Table 3: Emergency & Medical
  autoTable(doc, {
      startY: currentY,
      head: [[{ content: 'EMERGENCY & MEDICAL', colSpan: 4, styles: { halign: 'left' } }]],
      body: [
          ['Emergency Contact', student.emergencyName || '-', 'Relation', student.emergencyRelationship || '-'],
          ['Emergency Number', student.emergencyCell || '-', 'Work Contact', student.emergencyWork || '-'],
          ['Medical Conditions', { content: student.medicalConditions || 'None', colSpan: 3 }],
          ['Doctor', student.doctorName || '-', 'Medical Aid', student.hasMedicalAid ? (student.medicalAidName || '-') : 'None'],
          ['Medical Consent', { content: student.medicalConsent ? 'Consent GIVEN for emergency treatment' : 'Consent NOT GIVEN', colSpan: 3, styles: { textColor: student.medicalConsent ? [0, 100, 0] : [200, 0, 0], fontStyle: 'bold' } }]
      ],
      ...tableStyles,
      columnStyles: { 
          0: { fontStyle: 'bold', width: 30, fillColor: [248, 248, 248] },
          1: { width: 60 },
          2: { fontStyle: 'bold', width: 30, fillColor: [248, 248, 248] }
      }
  });

  currentY = (doc as any).lastAutoTable.finalY + 5;

   // Table 4: History
   autoTable(doc, {
    startY: currentY,
    head: [[{ content: 'ACADEMIC HISTORY', colSpan: 2, styles: { halign: 'left' } }]],
    body: [
        ['Previous School', student.previousSchool || 'None'],
        ['Highest Grade', student.highestGrade || 'N/A'],
        ['English Proficiency', student.langEnglish || '-'],
        ['Other Languages', student.langOther1Name ? `${student.langOther1Name} (${student.langOther1Rating || '-'})` : '-']
    ],
    ...tableStyles,
    columnStyles: { 
        0: { fontStyle: 'bold', width: 40, fillColor: [248, 248, 248] }
    }
  });

  // Footer
  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  doc.text(`Generated on ${new Date().toLocaleDateString()}`, 14, 285);
  doc.text("Page 1 of 1", pageWidth - 14, 285, { align: "right" });

  doc.save(`${student.surname || 'Student'}_${student.firstName || 'Profile'}_Profile.pdf`);
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { submitApplication, getSystemSettings } from '../services/dataService';
import { ArrowLeft, CheckCircle, ArrowRight, ChevronDown, Check, AlertCircle } from 'lucide-react';
import { Button } from '../components/ui/Button';

const STEPS = [
  "Learner",
  "Parents", 
  "History",
  "Medical",
  "Consent"
];

// Custom Animated Dropdown Component
const CustomSelect: React.FC<{
  label: string;
  value: string;
  onChange: (value: string) => void;
  options: { label: string; value: string }[];
  required?: boolean;
}> = ({ label, value, onChange, options, required }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Close when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div className="w-full mb-6 relative" ref={containerRef}>
      <label className="block text-gray-800 text-sm font-medium mb-2">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <div 
        className={`w-full border-b-2 bg-gray-50 cursor-pointer transition-colors ${isOpen ? 'border-coha-500 bg-gray-100' : 'border-gray-300'}`}
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="p-3 flex justify-between items-center">
          <span className={`${!value ? 'text-gray-500' : 'text-gray-900'}`}>
            {value ? options.find(o => o.value === value)?.label || value : "Choose"}
          </span>
          <ChevronDown size={18} className={`transition-transform duration-300 ${isOpen ? 'rotate-180 text-coha-500' : 'text-gray-500'}`} />
        </div>
      </div>

      {/* Scroll Book Animation */}
      <div 
        className={`absolute z-20 w-full bg-white shadow-xl border border-gray-100 mt-1 rounded-b-lg overflow-hidden transition-all duration-500 ease-in-out ${isOpen ? 'max-h-60 opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="overflow-y-auto max-h-60">
          {options.map((option) => (
            <div 
              key={option.value}
              onClick={() => {
                onChange(option.value);
                setIsOpen(false);
              }}
              className={`p-3 text-sm cursor-pointer hover:bg-coha-50 transition-colors border-b border-gray-50 last:border-0 ${value === option.value ? 'bg-coha-50 text-coha-900 font-bold' : 'text-gray-700'}`}
            >
              {option.label}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

// Simple Input for Google Forms Style
const FormInput: React.FC<React.InputHTMLAttributes<HTMLInputElement> & { label: string }> = ({ label, className = '', required, ...props }) => (
  <div className="w-full mb-6">
    <label className="block text-gray-800 text-sm font-medium mb-2">
      {label} {required && <span className="text-red-500">*</span>}
    </label>
    <input
      className={`w-full p-3 border-b-2 border-gray-300 focus:border-coha-500 outline-none transition-colors bg-gray-50 focus:bg-white text-gray-900 ${className}`}
      {...props}
    />
  </div>
);

export const ApplyPage: React.FC = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [gradesList, setGradesList] = useState<string[]>([]);

  // Validation State
  const [shakeError, setShakeError] = useState(false);
  const [errorField, setErrorField] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    surname: '', firstName: '', dob: '', citizenship: '', gender: 'Male', 
    address: '', region: '', grade: '', isSpecialNeeds: false, specialNeedsType: '',
    fatherName: '', fatherPhone: '', fatherEmail: '',
    motherName: '', motherPhone: '',
    emergencyName: '', emergencyRelationship: '', emergencyWork: '', emergencyCell: '', emergencyEmail: '',
    hasPreviousSchool: true, previousSchool: '', highestGrade: '',
    langEnglish: 'Good', 
    langOther1Name: '', langOther1Rating: 'Fair',
    langOther2Name: '', langOther2Rating: 'Fair',
    medicalConditions: '',
    doctorName: '', doctorContact: '',
    audiologistName: '', audiologistContact: '',
    therapistName: '', therapistContact: '',
    hasMedicalAid: false,
    medicalAidName: '', medicalAidMemberName: '', medicalAidMemberID: '', medicalAidOption: '',
    medicalConsent: false,
    agreed: false
  });

  useEffect(() => {
    const fetchGrades = async () => {
        const settings = await getSystemSettings();
        if (settings && settings.grades) {
            setGradesList(settings.grades);
        } else {
            setGradesList(['Grade 1', 'Grade 2', 'Grade 3']);
        }
    };
    fetchGrades();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
      const checked = (e.target as HTMLInputElement).checked;
      setFormData(prev => ({ ...prev, [name]: checked }));
      if (name === 'agreed' || name === 'medicalConsent') setErrorField(null); // Clear error on interaction
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleCustomSelect = (name: string, value: string) => {
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNext = () => {
    if (currentStep < STEPS.length - 1) {
      setCurrentStep(prev => prev + 1);
      scrollToTop();
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep(prev => prev - 1);
      scrollToTop();
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validation Check for Consent & Agreement
    if (!formData.medicalConsent || !formData.agreed) {
      setShakeError(true);
      setErrorField('consent');
      setTimeout(() => setShakeError(false), 600); // Remove animation class after plays

      // Highlight the error section (Pulse effect via css class below)
      return;
    }

    setLoading(true);
    const success = await submitApplication(formData as any);
    if (success) {
      setSubmitted(true);
      scrollToTop();
    }
    setLoading(false);
  };

  if (submitted) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4 animate-fade-in">
        <div className="bg-white p-8 rounded-lg max-w-sm w-full text-center shadow-2xl">
          <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
            <CheckCircle className="text-green-600" size={32} />
          </div>
          <h2 className="text-xl font-bold text-gray-900 mb-2">Application Sent!</h2>
          <p className="text-sm text-gray-600 mb-6">
            We have received your details. Our admissions team will be in touch shortly.
          </p>
          <Button fullWidth onClick={() => navigate('/')}>Done</Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 pb-20">
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          20% { transform: translateX(-10px); }
          40% { transform: translateX(10px); }
          60% { transform: translateX(-10px); }
          80% { transform: translateX(10px); }
        }
        .animate-shake {
          animation: shake 0.5s ease-in-out;
        }
        .error-pulse {
          animation: pulse-red 1s infinite;
        }
        @keyframes pulse-red {
          0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4); }
          70% { box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
          100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
        }
      `}</style>

      {/* Header */}
      <div className="sticky top-0 bg-white z-40 border-b border-gray-100 shadow-sm">
        <div className="px-5 py-3 flex items-center gap-4">
          <button onClick={() => navigate('/')} className="text-gray-500 hover:text-coha-900">
            <ArrowLeft size={20} />
          </button>
          <h1 className="text-sm font-bold text-gray-600">Online Application</h1>
        </div>

        {/* Stepper */}
