                   <input 
                      type="checkbox" 
                      name="agreed" 
                      checked={formData.agreed} 
                      onChange={handleChange}
                      className="mt-1 w-6 h-6 accent-coha-900"
                    />
                   <span className="text-sm font-bold text-gray-900">
                     I declare that the information is true and I accept the terms outlined above.
                   </span>
                </label>
             </div>

              {shakeError && (
                 <div className="flex items-center gap-2 text-red-600 mb-4 animate-shake justify-center bg-red-50 p-2 rounded">
                    <AlertCircle size={18} />
                    <span className="text-sm font-bold">Please accept both consents to proceed.</span>
                 </div>
              )}
          </div>
        )}

        {/* Buttons */}
        <div className="mt-8 flex gap-4 pt-6 border-t border-gray-100">
           <Button 
              type="button" 
              variant="outline"
              onClick={handleBack} 
              className={`flex-1 ${currentStep === 0 ? 'invisible' : ''}`}
            >
              Back
            </Button>

            {currentStep < STEPS.length - 1 ? (
              <Button type="button" onClick={handleNext} className="flex-1 bg-coha-500 hover:bg-coha-600 border-none rounded-lg">
                Next <ArrowRight size={18} />
              </Button>
            ) : (
              <Button 
                type="submit" 
                disabled={loading}
                className={`flex-1 rounded-lg border-none text-white ${shakeError ? 'animate-shake bg-red-600' : 'bg-coha-900'}`}
              >
                {loading ? 'Sending...' : 'Submit Application'}
              </Button>
            )}
        </div>

      </form>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { submitApplication, getSystemSettings } from '../services/dataService';
import { ArrowLeft, CheckCircle, ArrowRight, ChevronDown, Check, AlertCircle } from 'lucide-react';
import { Button } from '../components/ui/Button';

const STEPS = [
  "Learner",
  "Parents", 
  "History",
  "Medical",
  "Consent"
];

// Custom Animated Dropdown Component
const CustomSelect: React.FC<{
  label: string;
  value: string;
  onChange: (value: string) => void;
  options: { label: string; value: string }[];
  required?: boolean;
}> = ({ label, value, onChange, options, required }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Close when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div className="w-full mb-6 relative" ref={containerRef}>
      <label className="block text-gray-800 text-sm font-medium mb-2">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <div 
        className={`w-full border-b-2 bg-gray-50 cursor-pointer transition-colors ${isOpen ? 'border-coha-500 bg-gray-100' : 'border-gray-300'}`}
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="p-3 flex justify-between items-center">
          <span className={`${!value ? 'text-gray-500' : 'text-gray-900'}`}>
            {value ? options.find(o => o.value === value)?.label || value : "Choose"}
          </span>
          <ChevronDown size={18} className={`transition-transform duration-300 ${isOpen ? 'rotate-180 text-coha-500' : 'text-gray-500'}`} />
        </div>
      </div>

      {/* Scroll Book Animation */}
      <div 
        className={`absolute z-20 w-full bg-white shadow-xl border border-gray-100 mt-1 rounded-b-lg overflow-hidden transition-all duration-500 ease-in-out ${isOpen ? 'max-h-60 opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="overflow-y-auto max-h-60">
          {options.map((option) => (
            <div 
              key={option.value}
              onClick={() => {
                onChange(option.value);
                setIsOpen(false);
              }}
              className={`p-3 text-sm cursor-pointer hover:bg-coha-50 transition-colors border-b border-gray-50 last:border-0 ${value === option.value ? 'bg-coha-50 text-coha-900 font-bold' : 'text-gray-700'}`}
            >
              {option.label}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

// Simple Input for Google Forms Style
const FormInput: React.FC<React.InputHTMLAttributes<HTMLInputElement> & { label: string }> = ({ label, className = '', required, ...props }) => (
  <div className="w-full mb-6">
    <label className="block text-gray-800 text-sm font-medium mb-2">
      {label} {required && <span className="text-red-500">*</span>}
    </label>
    <input
      className={`w-full p-3 border-b-2 border-gray-300 focus:border-coha-500 outline-none transition-colors bg-gray-50 focus:bg-white text-gray-900 ${className}`}
      {...props}
    />
  </div>
);

export const ApplyPage: React.FC = () => {
