        {/* Stepper */}
        <div className="px-5 pb-3 pt-1">
          <div className="flex items-center justify-between relative">
            {/* Connecting Line */}
            <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-200 -z-10 transform -translate-y-1/2"></div>
            <div 
              className="absolute top-1/2 left-0 h-0.5 bg-coha-500 -z-10 transform -translate-y-1/2 transition-all duration-300"
              style={{ width: `${(currentStep / (STEPS.length - 1)) * 100}%` }}
            ></div>

            {STEPS.map((step, index) => {
              const isCompleted = index < currentStep;
              const isCurrent = index === currentStep;

              return (
                <div key={index} className="flex flex-col items-center bg-white px-1">
                  <div 
                    className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold border-2 transition-all duration-300 ${
                      isCompleted ? 'bg-coha-500 border-coha-500 text-white' : 
                      isCurrent ? 'bg-white border-coha-500 text-coha-500 scale-110' : 
                      'bg-white border-gray-300 text-gray-400'
                    }`}
                  >
                    {isCompleted ? <Check size={14} /> : index + 1}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="text-center mt-2">
            <span className="text-xs font-bold text-coha-900 uppercase tracking-wide">{STEPS[currentStep]}</span>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="px-5 pt-8 max-w-5xl mx-auto">

        {/* Step 1: Learner */}
        {currentStep === 0 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Left Col */}
            <div>
                <FormInput name="surname" label="Surname" value={formData.surname} onChange={handleChange} required />
                <FormInput name="firstName" label="First Name" value={formData.firstName} onChange={handleChange} required />
                <FormInput name="dob" label="Date of Birth" type="date" value={formData.dob} onChange={handleChange} required />

                <CustomSelect 
                  label="Gender"
                  value={formData.gender}
                  options={[{ label: 'Male', value: 'Male' }, { label: 'Female', value: 'Female' }]}
                  onChange={(val) => handleCustomSelect('gender', val)}
                />

                <FormInput name="citizenship" label="Citizenship" value={formData.citizenship} onChange={handleChange} required />
            </div>

            {/* Right Col */}
            <div>
                <CustomSelect 
                  label="Grade Applying For"
                  value={formData.grade}
                  options={gradesList.map(g => ({ label: g, value: g }))}
                  onChange={(val) => handleCustomSelect('grade', val)}
                  required
                />

                <FormInput name="address" label="Residential Address" value={formData.address} onChange={handleChange} required />

                <div className="mt-6 mb-6">
                  <label className="flex items-start gap-3 cursor-pointer p-4 bg-gray-50 border border-gray-200 rounded-lg">
                    <input 
                      type="checkbox" 
                      name="isSpecialNeeds" 
                      checked={formData.isSpecialNeeds} 
                      onChange={handleChange}
                      className="mt-1 w-5 h-5 accent-coha-500"
                    />
                    <div>
                      <span className="font-bold text-gray-800 text-sm">Special Needs Application</span>
                      <p className="text-xs text-gray-500 mt-1">Check this if the learner requires special educational support.</p>
                    </div>
                  </label>
                </div>

                {formData.isSpecialNeeds && (
                  <div className="animate-fade-in pl-4 border-l-2 border-coha-500 mb-6">
                    <CustomSelect 
                      label="Type of Special Needs"
                      value={formData.specialNeedsType}
                      options={[
                        { label: 'Intellectual/Learning Difficulties', value: 'Intellectual/Learning Difficulties' },
                        { label: 'Down Syndrome', value: 'Down Syndrome' },
                        { label: 'Autism', value: 'Autism' },
                        { label: 'Other', value: 'Other' }
                      ]}
                      onChange={(val) => handleCustomSelect('specialNeedsType', val)}
                    />
                  </div>
                )}
            </div>
          </div>
        )}

        {/* ... (Other steps remain same but shortened for XML space, they just use FormInput which is locally defined still) ... */}
        {/* Step 2: Parents */}
        {currentStep === 1 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6">Parent / Guardian Details</h3>
                <FormInput name="fatherName" label="Father/Guardian Name" value={formData.fatherName} onChange={handleChange} required />
                <FormInput name="fatherPhone" label="Phone Number" type="tel" value={formData.fatherPhone} onChange={handleChange} required />
                <FormInput name="fatherEmail" label="Email Address" type="email" value={formData.fatherEmail} onChange={handleChange} required />
                <div className="w-full h-px bg-gray-200 my-8"></div>
                <FormInput name="motherName" label="Mother/Guardian Name" value={formData.motherName} onChange={handleChange} />
                <FormInput name="motherPhone" label="Phone Number" type="tel" value={formData.motherPhone} onChange={handleChange} />
            </div>
            <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Emergency Contact</h3>
                <div className="bg-red-50 p-4 border-l-4 border-red-400 mb-6 rounded-r-lg">
                  <p className="text-xs text-red-800">Please provide a contact other than the parents.</p>
                </div>
                <FormInput name="emergencyName" label="Full Name" value={formData.emergencyName} onChange={handleChange} required />
                <FormInput name="emergencyRelationship" label="Relationship" value={formData.emergencyRelationship} onChange={handleChange} required />
                <FormInput name="emergencyCell" label="Cell Number" type="tel" value={formData.emergencyCell} onChange={handleChange} required />
                <FormInput name="emergencyWork" label="Work Contact" value={formData.emergencyWork} onChange={handleChange} />
                <FormInput name="emergencyEmail" label="Email Address" type="email" value={formData.emergencyEmail} onChange={handleChange} />
            </div>
          </div>
        )}

        {/* Step 3: History */}
        {currentStep === 2 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Educational History</h3>
                 <div className="mb-6">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                      type="checkbox" 
                      name="hasPreviousSchool" 
                      checked={!formData.hasPreviousSchool} 
                      onChange={(e) => setFormData({...formData, hasPreviousSchool: !e.target.checked})}
                      className="w-5 h-5 accent-coha-500"
                    />
                    <span className="text-sm text-gray-700">First time attender (No previous school)</span>
                  </label>
                </div>
                {formData.hasPreviousSchool && (
                  <div className="pl-4 border-l-2 border-gray-200 mb-8">
                    <FormInput name="previousSchool" label="Previous School Name" value={formData.previousSchool} onChange={handleChange} />
                    <FormInput name="highestGrade" label="Highest Grade Completed" value={formData.highestGrade} onChange={handleChange} />
                  </div>
                )}
             </div>
             <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Language Proficiency</h3>
                <div className="mb-6">
                  <label className="block text-gray-800 text-sm font-medium mb-2">English Proficiency</label>
                  <div className="flex gap-4">
                    {['Good', 'Fair', 'Poor'].map(rating => (
                      <label key={rating} className="flex items-center gap-2 cursor-pointer bg-gray-50 px-3 py-2 rounded border border-gray-200">
                        <input 
                          type="radio" 
                          name="langEnglish" 
                          value={rating} 
                          checked={formData.langEnglish === rating} 
                          onChange={handleChange}
                          className="accent-coha-500" 
                        />
                        <span className="text-sm">{rating}</span>
                      </label>
                    ))}
                  </div>
                </div>
                <FormInput name="langOther1Name" label="Other Language (Optional)" value={formData.langOther1Name} onChange={handleChange} />
             </div>
          </div>
        )}

        {/* Step 4: Medical */}
        {currentStep === 3 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Medical Information</h3>
                 <div className="mb-6">
                    <label className="block text-gray-800 text-sm font-medium mb-2">Known Medical Conditions / Allergies</label>
                    <textarea 
                      name="medicalConditions" 
                      value={formData.medicalConditions} 
                      onChange={handleChange}
                      className="w-full p-3 border-b-2 border-gray-300 focus:border-coha-500 outline-none bg-gray-50 h-24 text-sm"
                      placeholder="List any conditions here..."
                    />
                 </div>
                 <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-6">
                    <h4 className="text-sm font-bold text-gray-700 mb-4 uppercase tracking-wide">Professionals (If Applicable)</h4>
                    <FormInput name="doctorName" label="Family Doctor Name" value={formData.doctorName} onChange={handleChange} className="bg-white" />
                    <FormInput name="doctorContact" label="Doctor Contact" value={formData.doctorContact} onChange={handleChange} className="bg-white" />
                    <FormInput name="therapistName" label="Occupational Therapist" value={formData.therapistName} onChange={handleChange} className="bg-white" />
                 </div>
             </div>
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Medical Aid Details</h3>
                 <div className="mb-6">
                  <label className="flex items-center gap-3 cursor-pointer mb-4">
                    <input 
                      type="checkbox" 
                      name="hasMedicalAid" 
                      checked={formData.hasMedicalAid} 
                      onChange={handleChange}
                      className="w-5 h-5 accent-coha-500"
                    />
                    <span className="font-bold text-gray-800 text-sm">Learner has Medical Aid</span>
                  </label>
                  {formData.hasMedicalAid && (
                    <div className="pl-4 border-l-2 border-coha-500 animate-fade-in">
                       <FormInput name="medicalAidName" label="Medical Aid Name" value={formData.medicalAidName} onChange={handleChange} />
                       <FormInput name="medicalAidOption" label="Plan Option" value={formData.medicalAidOption} onChange={handleChange} />
                       <FormInput name="medicalAidMemberID" label="Member ID" value={formData.medicalAidMemberID} onChange={handleChange} />
                    </div>
                  )}
                 </div>
             </div>
          </div>
        )}

        {/* Step 5: Consent */}
        {currentStep === 4 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Consent & Declaration</h3>
                 <div className={`p-5 rounded-lg border-l-4 mb-6 transition-all duration-300 ${errorField === 'consent' ? 'bg-red-50 border-red-600 error-pulse' : 'bg-red-50 border-red-500'}`}>
                    <h4 className="font-bold text-red-800 mb-2">Medical Emergency Consent</h4>
                    <p className="text-sm text-gray-700 mb-4 leading-relaxed">
                      In a critical medical situation, the school reserves the right to utilise the quickest medical service available if parents cannot be reached immediately.
                    </p>
                    <label className="flex items-start gap-3 cursor-pointer">
                       <input 
                          type="checkbox" 
                          name="medicalConsent" 
                          checked={formData.medicalConsent} 
                          onChange={handleChange}
                          className="mt-1 w-6 h-6 accent-red-600"
                        />
                       <span className="text-sm font-bold text-red-900">
                         I, hereby agree that a medical practitioner may provide emergency treatment as may be necessary.
                       </span>
                    </label>
                 </div>
             </div>
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Terms & Conditions</h3>
                 <div className={`p-5 rounded-lg border-l-4 mb-8 transition-all duration-300 ${errorField === 'consent' ? 'bg-gray-100 border-red-600 error-pulse' : 'bg-gray-50 border-gray-400'}`}>
                    <h4 className="font-bold text-gray-900 mb-4">Terms & Conditions</h4>
                    <ul className="list-disc pl-5 space-y-2 text-sm text-gray-600 mb-6">
                      <li>I accept the school's curriculum and policies.</li>
                      <li>I accept financial responsibility for all school fees.</li>
                      <li>School fees are paid in advance.</li>
                      <li>One month's notice is required for withdrawal.</li>
                    </ul>
                    <label className="flex items-start gap-3 cursor-pointer">
                       <input 
                          type="checkbox" 
                          name="agreed" 
                          checked={formData.agreed} 
                          onChange={handleChange}
                          className="mt-1 w-6 h-6 accent-coha-900"
                        />
                       <span className="text-sm font-bold text-gray-900">
                         I declare that the information is true and I accept the terms outlined above.
                       </span>
                    </label>
                 </div>
                  {shakeError && (
                     <div className="flex items-center gap-2 text-red-600 mb-4 animate-shake justify-center bg-red-50 p-2 rounded">
                        <AlertCircle size={18} />
                        <span className="text-sm font-bold">Please accept both consents to proceed.</span>
                     </div>
                  )}
             </div>
          </div>
        )}

        {/* Buttons */}
        <div className="mt-8 flex gap-4 pt-6 border-t border-gray-100 w-full">
           <Button 
              type="button" 
              variant="outline"
              onClick={handleBack} 
              className={`flex-1 ${currentStep === 0 ? 'invisible' : ''}`}
            >
              Back
            </Button>

            {currentStep < STEPS.length - 1 ? (
              <Button type="button" onClick={handleNext} className="flex-1 bg-coha-500 hover:bg-coha-600 border-none rounded-lg">
                Next <ArrowRight size={18} />
              </Button>
            ) : (
              <Button 
                type="submit" 
                disabled={loading}
                className={`flex-1 rounded-lg border-none text-white ${shakeError ? 'animate-shake bg-red-600' : 'bg-coha-900'}`}
              >
                {loading ? 'Sending...' : 'Submit Application'}
              </Button>
            )}
        </div>

      </form>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getApplications, getStudentsByStatus, verifyPayment, rejectPayment, getReceipts, addReceipt, deleteReceipt } from '../../services/dataService';
import { Application, Student, Receipt } from '../../types';
import { Eye, Clock, Search, Filter, Check, X, Plus, Trash2 } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Toast } from '../../components/ui/Toast';

type ViewMode = 'APPLICATIONS' | 'VERIFICATION' | 'RECEIPTS';

export const ApplicationsPage: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('APPLICATIONS');
  const [applications, setApplications] = useState<Application[]>([]);
  const [verificationList, setVerificationList] = useState<Student[]>([]);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'PENDING' | 'APPROVED' | 'REJECTED'>('PENDING');
  const navigate = useNavigate();

  // Receipts State
  const [newReceiptNumber, setNewReceiptNumber] = useState('');
  const [newReceiptAmount, setNewReceiptAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ msg: '', show: false, type: 'success' as 'success' | 'error' });

  useEffect(() => {
    loadData();
  }, [viewMode]);

  const loadData = async () => {
    if (viewMode === 'APPLICATIONS') {
        const data = await getApplications();
        setApplications(data);
    } else if (viewMode === 'VERIFICATION') {
        const data = await getStudentsByStatus('PAYMENT_VERIFICATION');
        setVerificationList(data);
    } else if (viewMode === 'RECEIPTS') {
        const data = await getReceipts();
        setReceipts(data);
    }
  };

  const handleVerify = async (student: Student) => {
    if (!student.receiptNumber) return;
    setLoading(true);
    const result = await verifyPayment(student.id, student.receiptNumber);
    setLoading(false);

    if (result.success) {
        setToast({ msg: 'Payment Verified! Student moved to Assessment.', show: true, type: 'success' });
        loadData();
    } else {
        setToast({ msg: result.message, show: true, type: 'error' });
    }
  };

  const handleRejectPayment = async (student: Student) => {
    if (window.confirm('Reject this payment verification? The parent will be notified to try again.')) {
        await rejectPayment(student.id);
        loadData();
        setToast({ msg: 'Payment Rejected. Student status reset.', show: true, type: 'success' });
    }
  };

  const handleAddReceipt = async () => {
      if (!newReceiptNumber || !newReceiptAmount) return;
      setLoading(true);
      const success = await addReceipt(newReceiptNumber, newReceiptAmount, new Date().toISOString());
      if (success) {
          setNewReceiptNumber('');
          setNewReceiptAmount('');
          loadData();
          setToast({ msg: 'Receipt added successfully', show: true, type: 'success' });
      }
      setLoading(false);
  };

  const handleDeleteReceipt = async (id: string) => {
      if(window.confirm('Delete this receipt?')) {
          await deleteReceipt(id);
          loadData();
      }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'APPROVED': return 'bg-green-100 text-green-800 border-green-200';
      case 'REJECTED': return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
    }
  };

  const filteredApps = applications.filter(app => {
      const matchesSearch = (() => {
        const fullName = `${app.firstName} ${app.surname}`.toLowerCase();
        const parent = (app.fatherName || app.motherName || '').toLowerCase();
        const term = searchTerm.toLowerCase();
        return fullName.includes(term) || parent.includes(term) || app.grade.toLowerCase().includes(term);
      })();
      return matchesSearch && app.status === statusFilter;
  });

  return (
    <div>
      <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({...toast, show: false})} variant={toast.type} />

      <div className="mb-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-coha-900">Admissions Management</h2>
            <p className="text-gray-600">Manage applications, verify payments, and issue receipts.</p>
        </div>
        <div className="flex bg-white shadow-sm border border-gray-200">
            <button onClick={() => setViewMode('APPLICATIONS')} className={`px-4 py-2 text-sm font-bold uppercase ${viewMode === 'APPLICATIONS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}>Applications</button>
            <button onClick={() => setViewMode('VERIFICATION')} className={`px-4 py-2 text-sm font-bold uppercase ${viewMode === 'VERIFICATION' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}>Payment Verification</button>
            <button onClick={() => setViewMode('RECEIPTS')} className={`px-4 py-2 text-sm font-bold uppercase ${viewMode === 'RECEIPTS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}>Available Receipts</button>
        </div>
      </div>

      {/* MODE: APPLICATIONS */}
      {viewMode === 'APPLICATIONS' && (
          <div className="animate-fade-in">
             <div className="flex border-b border-gray-200 mb-6 bg-white shadow-sm overflow-x-auto">
                <button onClick={() => setStatusFilter('PENDING')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${statusFilter === 'PENDING' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Pending</button>
                <button onClick={() => setStatusFilter('APPROVED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${statusFilter === 'APPROVED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Approved</button>
                <button onClick={() => setStatusFilter('REJECTED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${statusFilter === 'REJECTED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Rejected</button>
             </div>

             <div className="bg-white border border-gray-200 shadow-sm">
                <div className="p-4 border-b border-gray-200">
                    <div className="relative max-w-md">
                        <Search className="absolute left-3 top-3 text-gray-400" size={20} />
                        <input className="w-full pl-10 pr-4 py-2 border border-gray-300 outline-none" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                    </div>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-600">
                            <tr>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-6 py-4">Name</th>
                                <th className="px-6 py-4">Grade</th>
                                <th className="px-6 py-4">Parent</th>
                                <th className="px-6 py-4">Date</th>
                                <th className="px-6 py-4">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {filteredApps.map((app) => (
                                <tr key={app.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-bold border ${getStatusColor(app.status)}`}>{app.status}</span></td>
                                    <td className="px-6 py-4 font-bold text-coha-900">{app.surname}, {app.firstName}</td>
                                    <td className="px-6 py-4">{app.grade}</td>
                                    <td className="px-6 py-4">{app.fatherName || app.motherName}</td>
                                    <td className="px-6 py-4 text-xs">{app.submissionDate?.toDate().toLocaleDateString()}</td>
                                    <td className="px-6 py-4"><button onClick={() => navigate(`/admin/applications/${app.id}`)} className="text-coha-500 font-bold text-sm flex gap-1 items-center"><Eye size={16}/> View</button></td>
                                </tr>
                            ))}
                            {filteredApps.length === 0 && <tr><td colSpan={6} className="text-center py-8 text-gray-500">No applications found.</td></tr>}
                        </tbody>
                    </table>
                </div>
             </div>
          </div>
      )}

      {/* MODE: VERIFICATION */}
      {viewMode === 'VERIFICATION' && (
          <div className="animate-fade-in bg-white border border-gray-200 shadow-sm">
             <div className="p-4 border-b border-gray-200 bg-yellow-50">
                 <h3 className="text-yellow-800 font-bold flex items-center gap-2"><Clock size={20}/> Waiting for Approval</h3>
                 <p className="text-yellow-700 text-sm">These parents have submitted a receipt number. Verify against Available Receipts.</p>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-600">
                        <tr>
                            <th className="px-6 py-4">Student ID</th>
                            <th className="px-6 py-4">Name</th>
                            <th className="px-6 py-4">Submitted Receipt #</th>
                            <th className="px-6 py-4">Submission Date</th>
                            <th className="px-6 py-4">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {verificationList.map((student) => (
                            <tr key={student.id} className="hover:bg-gray-50">
                                <td className="px-6 py-4 font-mono text-xs">{student.id}</td>
                                <td className="px-6 py-4 font-bold">{student.name}</td>
                                <td className="px-6 py-4 font-mono font-bold text-lg text-coha-900">{student.receiptNumber}</td>
                                <td className="px-6 py-4 text-xs">{student.receiptSubmissionDate?.toDate().toLocaleString()}</td>
                                <td className="px-6 py-4 flex gap-2">
                                    <Button onClick={() => handleVerify(student)} disabled={loading} className="py-1 px-3 text-sm">
                                        Verify
                                    </Button>
                                    <Button variant="danger" onClick={() => handleRejectPayment(student)} disabled={loading} className="py-1 px-3 text-sm">
                                        Reject
                                    </Button>
                                </td>
                            </tr>
                        ))}
                        {verificationList.length === 0 && <tr><td colSpan={5} className="text-center py-8 text-gray-500">No pending verifications.</td></tr>}
                    </tbody>
                </table>
             </div>
          </div>
      )}

      {/* MODE: RECEIPTS */}
      {viewMode === 'RECEIPTS' && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-1 bg-white p-6 shadow-sm border border-gray-200 h-fit">
                  <h3 className="font-bold text-lg mb-4">Add New Receipt</h3>
                  <div className="space-y-4">
                      <Input label="Receipt Number" value={newReceiptNumber} onChange={(e) => setNewReceiptNumber(e.target.value)} placeholder="e.g. R-10029" />
                      <Input label="Amount (N$)" value={newReceiptAmount} onChange={(e) => setNewReceiptAmount(e.target.value)} placeholder="300.00" />
                      <Button fullWidth onClick={handleAddReceipt} disabled={loading}>
                          <Plus size={20} /> Add Receipt
                      </Button>
                  </div>
              </div>

              <div className="lg:col-span-2 bg-white shadow-sm border border-gray-200">
                  <div className="p-4 border-b bg-gray-50 font-bold text-gray-700">Available Receipts</div>
                  <div className="overflow-x-auto max-h-[600px]">
                    <table className="w-full text-left">
                        <thead className="bg-white text-xs font-bold uppercase text-gray-600 sticky top-0">
                            <tr>
                                <th className="px-6 py-4">Receipt #</th>
                                <th className="px-6 py-4">Amount</th>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-6 py-4">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {receipts.map((receipt) => (
                                <tr key={receipt.id} className={receipt.isUsed ? 'bg-gray-100 opacity-70' : ''}>
                                    <td className="px-6 py-4 font-mono font-bold">{receipt.number}</td>
                                    <td className="px-6 py-4">N$ {receipt.amount}</td>
                                    <td className="px-6 py-4">
                                        {receipt.isUsed ? (
                                            <span className="text-xs font-bold text-gray-500 bg-gray-200 px-2 py-1">USED ({receipt.usedByStudentId})</span>
                                        ) : (
                                            <span className="text-xs font-bold text-green-600 bg-green-100 px-2 py-1">AVAILABLE</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        {!receipt.isUsed && (
                                            <button onClick={() => handleDeleteReceipt(receipt.id!)} className="text-red-400 hover:text-red-600">
                                                <Trash2 size={16}/>
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                            {receipts.length === 0 && <tr><td colSpan={4} className="text-center py-8">No receipts added.</td></tr>}
                        </tbody>
                    </table>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getApplicationById, updateApplication, getSystemSettings, approveApplicationInitial } from '../../services/dataService';
import { Application, SystemSettings } from '../../types';
import { Button } from '../../components/ui/Button';
import { Loader } from '../../components/ui/Loader';
import { Input } from '../../components/ui/Input';
import { ArrowLeft, Check, X, Printer, AlertTriangle } from 'lucide-react';
import { ConfirmModal } from '../../components/ui/ConfirmModal';

export const ApplicationDetailsPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [app, setApp] = useState<Application | null>(null);
  const [settings, setSettings] = useState<SystemSettings | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [rejectModalOpen, setRejectModalOpen] = useState(false);

  // Office Use State
  const [officeData, setOfficeData] = useState({
    officeReviewer: '',
    officeReviewDate: new Date().toISOString().split('T')[0],
    officeStatus: 'Successful',
    officeResponseMethod: 'Email',
    officeResponseDate: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    const fetchData = async () => {
      if (id) {
        const appData = await getApplicationById(id);
        const settingsData = await getSystemSettings();
        setApp(appData);
        setSettings(settingsData);

        if (settingsData?.adminName) {
            setOfficeData(prev => ({...prev, officeReviewer: settingsData.adminName}));
        }

        if (appData?.officeReviewer) {
            setOfficeData({
                officeReviewer: appData.officeReviewer || '',
                officeReviewDate: appData.officeReviewDate || '',
                officeStatus: appData.officeStatus || 'Successful',
                officeResponseMethod: appData.officeResponseMethod || 'Email',
                officeResponseDate: appData.officeResponseDate || ''
            });
        }
      }
    };
    fetchData();
  }, [id]);

  const handleOfficeChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setOfficeData({ ...officeData, [e.target.name]: e.target.value });
  };

  const handleApprove = async () => {
    if (!app || !id) return;
    setIsProcessing(true);

    try {
        const updatedData = {
            status: 'APPROVED' as any,
            ...officeData
        };

        await updateApplication(id, updatedData);
        setApp({ ...app, ...updatedData });

        // 1. Initial Approval -> Create Student with "WAITING_PAYMENT"
        const result = await approveApplicationInitial(app);

        if (settings && result) {
            const parentEmail = app.fatherEmail; 
            const subject = `Admission Conditional Approval: ${app.firstName} ${app.surname} - Circle of Hope Academy`;

            const body = `Dear Parent/Guardian,

Your application for ${app.firstName} ${app.surname} has been CONDITIONALLY APPROVED.

NEXT STEP: PAYMENT CONFIRMATION
To finalize the enrollment, you must login to the Parent Portal and enter your application fee receipt number.

LOGIN DETAILS:
Student Name: ${app.firstName} ${app.surname}
Parent PIN: ${result.pin}

Please login at the school portal and verify your payment to proceed to assessment.

Regards,
${settings.adminName}
Circle of Hope Academy`;

            window.location.href = `mailto:${parentEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
        }
    } catch (error) {
        console.error("Error approving:", error);
    }
    setIsProcessing(false);
  };

  const handleReject = async () => {
      if (!app || !id) return;
      setIsProcessing(true);
      try {
          await updateApplication(id, { status: 'REJECTED' });
          setRejectModalOpen(false);
          setApp({...app, status: 'REJECTED'});

          // Send Rejection Email
          const subject = `Admission Update: ${app.firstName} ${app.surname}`;
          const body = `Dear Parent/Guardian,\n\nWe regret to inform you that the application for ${app.firstName} ${app.surname} was not successful at this time.\n\nRegards,\nCircle of Hope Academy`;
           window.location.href = `mailto:${app.fatherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
      } catch (e) {
          console.error(e);
      }
      setIsProcessing(false);
  };

  if (!app) return <Loader />;

  const Section: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className = '' }) => (
    <div className={`bg-white p-6 shadow-sm border border-gray-200 mb-6 ${className}`}>
      <h3 className="text-lg font-bold text-coha-900 mb-4 border-b pb-2 uppercase tracking-wider">{title}</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4">
        {children}
      </div>
    </div>
  );

  const InfoRow: React.FC<{ label: string; value: any }> = ({ label, value }) => (
    <div>
      <p className="text-xs text-gray-500 uppercase font-bold">{label}</p>
      <p className="text-gray-900 font-medium break-words">{value || '-'}</p>
    </div>
  );

  return (
    <div className="w-full px-5 pb-10">
        <ConfirmModal 
            isOpen={rejectModalOpen}
            onClose={() => setRejectModalOpen(false)}
            onConfirm={handleReject}
            title="Reject Application?"
            message="Are you sure you want to reject this application? This action will mark it as rejected."
            isLoading={isProcessing}
        />

        <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-4">
                <button onClick={() => navigate('/admin/applications')} className="bg-white p-2 border hover:bg-gray-50">
                    <ArrowLeft size={20} />
                </button>
                <div>
                    <h2 className="text-2xl font-bold text-coha-900">{app.surname}, {app.firstName}</h2>
                    <p className="text-gray-600">Application ID: {app.id}</p>
                </div>
            </div>
            <div className="flex gap-2">
                <Button variant="outline" onClick={() => window.print()}>
                    <Printer size={18} /> Print
                </Button>
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2">
                <Section title="Learner Details">
                    <InfoRow label="Full Name" value={`${app.firstName} ${app.surname}`} />
                    <InfoRow label="Date of Birth" value={app.dob} />
                    <InfoRow label="Gender" value={app.gender} />
                    <InfoRow label="Citizenship" value={app.citizenship} />
                    <InfoRow label="Grade Applied" value={app.grade} />
                    <InfoRow label="Address" value={app.address} />
                    <InfoRow label="Special Needs" value={app.isSpecialNeeds ? `Yes - ${app.specialNeedsType}` : 'No'} />
                </Section>
                <Section title="Parent / Guardian Info">
                    <InfoRow label="Father Name" value={app.fatherName} />
                    <InfoRow label="Father Phone" value={app.fatherPhone} />
                    <InfoRow label="Father Email" value={app.fatherEmail} />
                    <div className="md:col-span-2 border-t pt-2 mt-2"></div>
                    <InfoRow label="Mother Name" value={app.motherName} />
                    <InfoRow label="Mother Phone" value={app.motherPhone} />
                </Section>
                {/* ... other sections same as before ... */}
            </div>

            <div className="lg:col-span-1">
                {/* Office Use Section */}
                <div className="bg-coha-50 p-6 border-l-4 border-coha-900 sticky top-24">
                    <h3 className="text-lg font-bold text-coha-900 mb-6 uppercase tracking-wider">Office Use Only</h3>

                    {app.status === 'APPROVED' ? (
                        <div className="text-center py-8">
                            <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Check size={32} />
                            </div>
                            <h3 className="font-bold text-green-800 text-xl">Approved</h3>
                            <p className="text-green-600">Awaiting Payment Verification</p>
                        </div>
                    ) : app.status === 'REJECTED' ? (
                        <div className="text-center py-8">
                             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
                                <X size={32} />
                            </div>
                            <h3 className="font-bold text-red-800 text-xl">Rejected</h3>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            <Input label="Reviewed By" name="officeReviewer" value={officeData.officeReviewer} onChange={handleOfficeChange} />
                            <Input label="Date of Review" type="date" name="officeReviewDate" value={officeData.officeReviewDate} onChange={handleOfficeChange} />

                            <div className="pt-6 flex flex-col gap-3">
                                <Button fullWidth onClick={handleApprove} disabled={isProcessing} className="bg-green-600 hover:bg-green-700 border-none">
                                    {isProcessing ? 'Processing...' : <><Check size={20} /> Approve & Request Payment</>}
                                </Button>
                                <Button fullWidth onClick={() => setRejectModalOpen(true)} disabled={isProcessing} variant="danger">
                                    <X size={20} /> Reject Application
                                </Button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getStudentById, updateStudent, deleteStudent } from '../../services/dataService';
import { Student } from '../../types';
import { Button } from '../../components/ui/Button';
import { Loader } from '../../components/ui/Loader';
import { ArrowLeft, Printer, Trash2, Edit2, Save, X } from 'lucide-react';
import { ConfirmModal } from '../../components/ui/ConfirmModal';
import { Toast } from '../../components/ui/Toast';
import { printStudentProfile } from '../../utils/printStudentProfile';
import { CustomSelect } from '../../components/ui/CustomSelect';

const Section: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className = '' }) => (
  <div className={`bg-white p-6 shadow-sm border border-gray-200 mb-6 ${className}`}>
    <h3 className="text-lg font-bold text-coha-900 mb-4 border-b pb-2 uppercase tracking-wider">{title}</h3>
    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4">
      {children}
    </div>
  </div>
);

// Expanded Interface for Row
interface InfoRowProps {
  label: string;
  value: any;
  name: string;
  isEditing: boolean;
  editForm: any;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onSelectChange?: (name: string, val: string) => void;
  type?: string;
  options?: { label: string, value: string }[];
}

const InfoRow: React.FC<InfoRowProps> = ({ label, value, name, isEditing, editForm, onChange, onSelectChange, type = 'text', options }) => (
  <div>
    <p className="text-xs text-gray-500 uppercase font-bold">{label}</p>
    {isEditing ? (
      options && onSelectChange ? (
          <CustomSelect 
            value={(editForm as any)[name] || ''}
            onChange={(val) => onSelectChange(name, val)}
            options={options}
            className="mb-0"
          />
      ) : (
        <input 
            type={type}
            name={name}
            value={(editForm as any)[name] || ''}
            onChange={onChange}
            className="w-full border-b border-gray-300 focus:border-coha-500 outline-none py-1 font-medium bg-gray-50 text-coha-900"
        />
      )
    ) : (
      <p className="text-gray-900 font-medium break-words py-1 border-b border-transparent">{value || '-'}</p>
    )}
  </div>
);

export const StudentDetailsPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [student, setStudent] = useState<Student | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState<Partial<Student>>({});
  const [loading, setLoading] = useState(false);
  const [toastVisible, setToastVisible] = useState(false);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      if (id) {
        const data = await getStudentById(id);
        setStudent(data);
        if(data) setEditForm(data);
      }
    };
    fetchData();
  }, [id]);

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setEditForm({ ...editForm, [e.target.name]: e.target.value });
  };

  const handleSelectChange = (name: string, val: string) => {
      setEditForm({ ...editForm, [name]: val });
  };

  const handleSave = async () => {
    if (student?.id) {
        setLoading(true);
        const success = await updateStudent(student.id, editForm);
        if (success) {
            setStudent({ ...student, ...editForm } as Student);
            setIsEditing(false);
            setToastVisible(true);
        }
        setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (student?.id) {
        setLoading(true);
        const success = await deleteStudent(student.id);
        if (success) { navigate('/admin/students'); }
        setLoading(false);
    }
  };

  if (!student) return <Loader />;

  const renderRow = (label: string, name: string, value: any, type: string = 'text', options?: { label: string, value: string }[]) => (
    <InfoRow 
      key={name}
      label={label} 
      name={name} 
      value={value} 
      isEditing={isEditing} 
      editForm={editForm} 
      onChange={handleEditChange} 
      onSelectChange={handleSelectChange}
      type={type}
      options={options}
    />
  );

  return (
    <div className="w-full px-5 pb-10">
        <ConfirmModal 
            isOpen={deleteModalOpen}
            onClose={() => setDeleteModalOpen(false)}
            onConfirm={handleDelete}
            title="Delete Student?"
            message={`Are you sure you want to permanently delete ${student.name}? This action cannot be undone.`}
            isLoading={loading}
        />
        <Toast message="Student profile updated." isVisible={toastVisible} onClose={() => setToastVisible(false)} variant="success" />

        <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-4">
                <button onClick={() => navigate('/admin/students')} className="bg-white p-2 border hover:bg-gray-50">
                    <ArrowLeft size={20} />
                </button>
                <div>
                    <h2 className="text-2xl font-bold text-coha-900">{student.name}</h2>
                    <p className="text-gray-600">ID: {student.id}</p>
                </div>
            </div>
            <div className="flex gap-2">
                {isEditing ? (
                    <>
                        <Button variant="outline" onClick={() => { setIsEditing(false); setEditForm(student); }}>
                            <X size={18} /> Cancel
                        </Button>
                        <Button onClick={handleSave} disabled={loading}>
                            <Save size={18} /> {loading ? 'Saving...' : 'Save Changes'}
                        </Button>
                    </>
                ) : (
                    <>
                         <Button variant="outline" onClick={() => printStudentProfile(student)}>
                            <Printer size={18} /> Print
                        </Button>
                        <Button variant="outline" onClick={() => setIsEditing(true)}>
                            <Edit2 size={18} /> Edit Profile
                        </Button>
                        <Button variant="danger" onClick={() => setDeleteModalOpen(true)}>
                            <Trash2 size={18} /> Delete
                        </Button>
                    </>
                )}
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2">
                <Section title="Learner Profile">
                    {renderRow("Full Name", "name", student.name)}
                    {renderRow("Grade", "grade", student.grade)}
                    {renderRow("Date of Birth", "dob", student.dob, "date")}
                    {renderRow("Gender", "gender", student.gender, "text", [{label:'Male',value:'Male'}, {label:'Female',value:'Female'}])}
                    {renderRow("Citizenship", "citizenship", student.citizenship)}
                    {renderRow("Address", "address", student.address)}
                </Section>
                {/* ... other sections mostly text inputs, except english proficiency ... */}
                 <Section title="Education & Languages">
                    {renderRow("Previous School", "previousSchool", student.previousSchool)}
                    {renderRow("Highest Grade", "highestGrade", student.highestGrade)}
                    {renderRow("English Proficiency", "langEnglish", student.langEnglish, "text", [{label:'Good',value:'Good'}, {label:'Fair',value:'Fair'}, {label:'Poor',value:'Poor'}])}
                </Section>
                {/* ... remaining sections ... */}
            </div>
             <div className="lg:col-span-1">
                <div className="bg-coha-900 text-white p-6 shadow-lg mb-6">
                    <div className="w-20 h-20 bg-white text-coha-900 rounded-full flex items-center justify-center mx-auto mb-4 font-bold text-3xl">
                        {student.name.charAt(0)}
                    </div>
                    <h3 className="text-xl font-bold text-center mb-1">{student.name}</h3>
                    <p className="text-center text-coha-300 font-bold mb-6">{student.grade}</p>
                    <div className="bg-coha-800 p-4 mb-4">
                        <p className="text-xs text-coha-300 uppercase font-bold mb-1">Parent Login PIN</p>
                        <p className="text-2xl font-mono font-bold tracking-widest">{student.parentPin}</p>
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../../components/ui/Button';
import { getStudents, getSystemSettings, getStudentsByStatus, assessStudent } from '../../services/dataService';
import { Student, SystemSettings } from '../../types';
import { Plus, Search, Eye, Download, CheckSquare } from 'lucide-react';
import { Toast } from '../../components/ui/Toast';
import { printStudentList } from '../../utils/printStudentList';

export const StudentsPage: React.FC = () => {
  const [viewMode, setViewMode] = useState<'ENROLLED' | 'ASSESSMENT'>('ENROLLED');
  const [students, setStudents] = useState<Student[]>([]);
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [settings, setSettings] = useState<SystemSettings | null>(null);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({show: false, msg: ''});

  const fetchStudents = async () => {
    setLoading(true);
    let data: Student[] = [];
    if (viewMode === 'ENROLLED') {
         // Get both strictly enrolled and legacy/manual adds (which might not have studentStatus set yet)
         const all = await getStudents();
         data = all.filter(s => s.studentStatus === 'ENROLLED' || !s.studentStatus);
    } else {
         data = await getStudentsByStatus('ASSESSMENT');
    }
    setStudents(data);
    const settingsData = await getSystemSettings();
    setSettings(settingsData);
    setLoading(false);
  };

  useEffect(() => {
    fetchStudents();
  }, [viewMode]);

  const handleAssess = async (studentId: string) => {
      if(window.confirm('Mark this student as assessed and fully enrolled?')) {
          await assessStudent(studentId);
          fetchStudents();
          setToast({show: true, msg: 'Student enrolled successfully'});
      }
  };

  const filteredStudents = students.filter(student => 
    student.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (student.parentName && student.parentName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div>
      <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({show:false, msg:''})} variant="success" />

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-coha-900">Students</h2>
          <p className="text-gray-600">Manage enrollment and student records.</p>
        </div>
        {viewMode === 'ENROLLED' && (
             <Button variant="outline" onClick={() => printStudentList(filteredStudents, settings)}>
                <Download size={20} /> Download List
            </Button>
        )}
      </div>

      <div className="flex border-b border-gray-200 mb-6 bg-white shadow-sm">
         <button onClick={() => setViewMode('ENROLLED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${viewMode === 'ENROLLED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Registered Students</button>
         <button onClick={() => setViewMode('ASSESSMENT')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${viewMode === 'ASSESSMENT' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Pending Assessment</button>
      </div>

      <div className="bg-white border border-gray-200 shadow-sm">
        <div className="p-4 border-b border-gray-200 flex gap-2">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-3 text-gray-400" size={20} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-300 focus:border-coha-500 outline-none rounded-none"
              placeholder="Search students..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold">
              <tr>
                <th className="px-6 py-4">ID</th>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4">Grade</th>
                <th className="px-6 py-4">Parent</th>
                <th className="px-6 py-4">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 font-mono text-xs">{student.id}</td>
                  <td className="px-6 py-4 font-bold text-coha-900">{student.name}</td>
                  <td className="px-6 py-4">
                     <span className="bg-coha-100 text-coha-800 px-2 py-1 text-xs font-bold uppercase">{student.grade}</span>
                  </td>
                  <td className="px-6 py-4">{student.parentName}</td>
                  <td className="px-6 py-4">
