export const updateApplication = async (id: string, data: Partial<Application>) => {
  try {
    const docRef = doc(db, APPLICATIONS_COLLECTION, id);
    await updateDoc(docRef, data);
    return true;
  } catch (error) {
    console.error("Error updating application:", error);
    return false;
  }
};

// New function to get counts for sidebar badges
export const getPendingActionCounts = async () => {
    try {
        const appsQuery = query(collection(db, APPLICATIONS_COLLECTION), where("status", "==", "PENDING"));
        const appsSnap = await getDocs(appsQuery);

        const verifyQuery = query(collection(db, STUDENTS_COLLECTION), where("studentStatus", "==", "PAYMENT_VERIFICATION"));
        const verifySnap = await getDocs(verifyQuery);

        return {
            pendingApps: appsSnap.size,
            pendingVerifications: verifySnap.size,
            total: appsSnap.size + verifySnap.size
        };
    } catch (e) {
        console.error("Error fetching counts", e);
        return { pendingApps: 0, pendingVerifications: 0, total: 0 };
    }
};

export const getDashboardStats = async () => {
  try {
    const studentsSnap = await getDocs(collection(db, STUDENTS_COLLECTION));
    const teachersSnap = await getDocs(collection(db, TEACHERS_COLLECTION));
    const applicationsSnap = await getDocs(collection(db, APPLICATIONS_COLLECTION));
    const settings = await getSystemSettings();

    const totalStudents = studentsSnap.size;
    const totalTeachers = teachersSnap.size;

    let expectedRevenue = 0;

    if (settings && settings.fees) {
      settings.fees.forEach(fee => {
        const amount = parseFloat(fee.amount) || 0;
        let multiplier = 1;
        if (fee.frequency === 'Monthly') multiplier = 12; 
        else if (fee.frequency === 'Termly') multiplier = 3; 
        else if (fee.frequency === 'Once-off') multiplier = 1;
        expectedRevenue += (amount * multiplier * totalStudents);
      });
    }

    const defaulters = studentsSnap.docs.map(doc => {
        const d = doc.data();
        return {
            id: doc.id,
            name: d.name,
            grade: d.grade,
            parentName: d.parentName,
            parentPhone: d.fatherPhone || d.motherPhone || 'N/A'
        };
    });

    const monthCounts = new Array(12).fill(0);
    studentsSnap.forEach(doc => {
      const data = doc.data();
      if (data.enrolledAt) {
        const date = data.enrolledAt.toDate();
        monthCounts[date.getMonth()]++;
      }
    });

    const graphData = [
      { name: 'Jan', students: monthCounts[0] },
      { name: 'Feb', students: monthCounts[1] },
      { name: 'Mar', students: monthCounts[2] },
      { name: 'Apr', students: monthCounts[3] },
      { name: 'May', students: monthCounts[4] },
      { name: 'Jun', students: monthCounts[5] },
      { name: 'Jul', students: monthCounts[6] },
      { name: 'Aug', students: monthCounts[7] },
      { name: 'Sep', students: monthCounts[8] },
      { name: 'Oct', students: monthCounts[9] },
      { name: 'Nov', students: monthCounts[10] },
      { name: 'Dec', students: monthCounts[11] },
    ];

    const recentActivities = applicationsSnap.docs
      .sort((a, b) => b.data().submissionDate - a.data().submissionDate)
      .slice(0, 5)
      .map(doc => {
        const d = doc.data();
        return {
          id: doc.id,
          title: 'New Application',
          desc: `${d.firstName} ${d.surname} applied for ${d.grade}`,
          time: d.submissionDate?.toDate().toLocaleDateString()
        };
      });

    return {
      totalStudents,
      totalTeachers,
      totalApps: applicationsSnap.size,
      expectedRevenue,
      collectedRevenue: 0, 
      outstandingRevenue: expectedRevenue,
      defaulters,
      graphData,
      recentActivities
    };
  } catch (error) {
    console.error("Error fetching stats:", error);
    return null;
  }
};

export const getSystemSettings = async (): Promise<SystemSettings | null> => {
  const docRef = doc(db, SETTINGS_COLLECTION, 'general');
  const docSnap = await getDoc(docRef);
  if (docSnap.exists()) {
    return docSnap.data() as SystemSettings;
  }
  return null;
};

export const saveSystemSettings = async (settings: Partial<SystemSettings>) => {
  try {
    await setDoc(doc(db, SETTINGS_COLLECTION, 'general'), settings, { merge: true });
    return true;
  } catch (error) {
    console.error("Error saving settings:", error);
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { Student } from '../../types';
import { submitPaymentReceipt, getStudentById } from '../../services/dataService';
import { Loader } from '../../components/ui/Loader';
import { Input } from '../../components/ui/Input';
import { Button } from '../../components/ui/Button';
import { AlertCircle, CheckCircle, Clock, FileText } from 'lucide-react';

interface ParentDashboardProps {
  user: any; // Logged in user (Student record)
}

export const ParentDashboard: React.FC<ParentDashboardProps> = ({ user }) => {
  const [student, setStudent] = useState<Student | null>(null);
  const [receiptNumber, setReceiptNumber] = useState('');
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    // Refresh student data to get latest status
    if (user?.id) {
        getStudentById(user.id).then(setStudent);
    }
  }, [user]);

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!receiptNumber || !student) return;

      setLoading(true);
      const success = await submitPaymentReceipt(student.id, receiptNumber);
      if (success) {
          setSubmitted(true);
          // Optimistically update local state
          setStudent({...student, studentStatus: 'PAYMENT_VERIFICATION', paymentRejected: false});
      }
      setLoading(false);
  };

  if (!student) return <Loader />;

  // STATUS: WAITING_PAYMENT
  if (student.studentStatus === 'WAITING_PAYMENT') {
      return (
          <div className="max-w-md mx-auto mt-10 animate-fade-in">
              {/* Rejection Notice */}
              {student.paymentRejected && (
                  <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 shadow-sm">
                      <div className="flex items-start gap-3">
                          <AlertCircle className="text-red-600 shrink-0" size={24} />
                          <div>
                              <h3 className="text-red-800 font-bold">Payment Verification Failed</h3>
                              <p className="text-red-700 text-sm mt-1">The receipt number you provided was invalid or already used. Please check your receipt and try again.</p>
                          </div>
                      </div>
                  </div>
              )}

              <div className="p-6 bg-white shadow-lg border-t-8 border-coha-900">
                <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center mx-auto mb-4">
                        <AlertCircle size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-2">Complete Enrollment</h2>
                    <p className="text-gray-600">Your application has been conditionally approved. Please confirm your application fee payment to proceed.</p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <Input 
                        label="Enter Receipt Number" 
                        placeholder="e.g. R-99382" 
                        value={receiptNumber} 
                        onChange={(e) => setReceiptNumber(e.target.value)} 
                        required
                    />
                    <Button fullWidth disabled={loading}>
                        {loading ? 'Submitting...' : 'Verify Payment'}
                    </Button>
                </form>
              </div>
          </div>
      );
  }

  // STATUS: PAYMENT_VERIFICATION
  if (student.studentStatus === 'PAYMENT_VERIFICATION') {
      return (
          <div className="max-w-md mx-auto mt-10 p-8 bg-white shadow-lg text-center animate-fade-in">
               <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4 animate-pulse">
                  <Clock size={32} />
               </div>
               <h2 className="text-2xl font-bold text-gray-900 mb-2">Verifying Payment</h2>
               <p className="text-gray-600">We have received your receipt number. The administration is currently verifying the payment. This usually takes 24 hours.</p>
          </div>
      );
  }

  // STATUS: ASSESSMENT
  if (student.studentStatus === 'ASSESSMENT') {
      return (
          <div className="max-w-md mx-auto mt-10 p-8 bg-white shadow-lg text-center animate-fade-in">
               <div className="w-16 h-16 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mx-auto mb-4">
                  <FileText size={32} />
               </div>
               <h2 className="text-2xl font-bold text-gray-900 mb-2">Pending Assessment</h2>
               <p className="text-gray-600">Payment verified! The student is now awaiting academic assessment. You will be contacted shortly.</p>
          </div>
      );
  }

  // STATUS: ENROLLED (Standard View)
  return (
      <div className="max-w-4xl mx-auto">
          <div className="bg-white p-6 shadow-sm border-l-4 border-green-500 mb-6">
              <h2 className="text-2xl font-bold text-gray-900">Welcome, {student.parentName}</h2>
              <p className="text-gray-600">Student: {student.name} ({student.grade})</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-white p-6 shadow-sm">
                  <h3 className="font-bold text-lg mb-4 border-b pb-2">Student Profile</h3>
                  <div className="space-y-2">
                      <p><span className="text-gray-500 font-bold text-xs uppercase">Full Name:</span> <br/>{student.name}</p>
                      <p><span className="text-gray-500 font-bold text-xs uppercase">Student ID:</span> <br/>{student.id}</p>
                      <p><span className="text-gray-500 font-bold text-xs uppercase">Grade:</span> <br/>{student.grade}</p>
                  </div>
              </div>

              <div className="bg-white p-6 shadow-sm">
                  <h3 className="font-bold text-lg mb-4 border-b pb-2">Financial Status</h3>
                  <div className="flex items-center gap-3 text-green-700 bg-green-50 p-4 rounded">
                      <CheckCircle size={24} />
                      <div>
                          <p className="font-bold">Enrolled</p>
                          <p className="text-sm">Account is active.</p>
                      </div>
                  </div>
              </div>
          </div>
      </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getApplications, getStudentsByStatus, verifyPayment, rejectPayment, getReceipts, addReceipt, deleteReceipt, deleteStudent, getPendingActionCounts } from '../../services/dataService';
import { Application, Student, Receipt } from '../../types';
import { Eye, Clock, Search, Filter, Check, X, Plus, Trash2, Key, Mail } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Toast } from '../../components/ui/Toast';
import { ConfirmModal } from '../../components/ui/ConfirmModal';

type ViewMode = 'APPLICATIONS' | 'PENDING_PAYMENT' | 'VERIFICATION' | 'RECEIPTS';

export const ApplicationsPage: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('APPLICATIONS');
  const [applications, setApplications] = useState<Application[]>([]);
  const [pendingPaymentList, setPendingPaymentList] = useState<Student[]>([]);
  const [verificationList, setVerificationList] = useState<Student[]>([]);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'PENDING' | 'REJECTED'>('PENDING');
  const navigate = useNavigate();

  // Counts for Badges
  const [counts, setCounts] = useState({ pendingApps: 0, pendingVerifications: 0, total: 0 });

  // Receipts State
  const [newReceiptNumber, setNewReceiptNumber] = useState('');
  const [newReceiptAmount, setNewReceiptAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ msg: '', show: false, type: 'success' as 'success' | 'error' });

  // Delete State
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Email/Verify Modal State
  const [emailModalOpen, setEmailModalOpen] = useState(false);
  const [verifyResult, setVerifyResult] = useState<{success: boolean, student: Student | null, message: string}>({success: false, student: null, message: ''});

  useEffect(() => {
    loadData();
    getPendingActionCounts().then(setCounts);
  }, [viewMode]);

  const loadData = async () => {
    if (viewMode === 'APPLICATIONS') {
        const data = await getApplications();
        // Only show Pending and Rejected here. Approved are in Pending Payment.
        setApplications(data);
    } else if (viewMode === 'PENDING_PAYMENT') {
        const data = await getStudentsByStatus('WAITING_PAYMENT');
        setPendingPaymentList(data);
    } else if (viewMode === 'VERIFICATION') {
        const data = await getStudentsByStatus('PAYMENT_VERIFICATION');
        setVerificationList(data);
    } else if (viewMode === 'RECEIPTS') {
        const data = await getReceipts();
        setReceipts(data);
    }
  };

  const handleVerifyClick = async (student: Student) => {
    if (!student.receiptNumber) return;
    setLoading(true);
    // Check validity ONLY
    const result = await verifyPayment(student.id, student.receiptNumber);
    setLoading(false);

    // Open Modal to decide on Email
    setVerifyResult({
        success: result.success,
        student: student,
        message: result.success ? 'Payment Verified Successfully.' : 'Invalid Receipt Number.'
    });
    setEmailModalOpen(true);
  };

  const finalizeVerification = async (sendEmail: boolean) => {
     if (!verifyResult.student) return;
     const student = verifyResult.student;

     if (verifyResult.success) {
         // Success Logic handled by verifyPayment in dataService (it updates status)
         // We just need to handle email if requested
         if (sendEmail) {
             const subject = "Enrollment Update: Payment Verified";
             const body = `Dear ${student.parentName},\n\nWe have successfully verified your payment receipt (${student.receiptNumber}).\n\nThe student ${student.name} is now queued for assessment.\n\nRegards,\nCircle of Hope Academy`;
             window.location.href = `mailto:${student.fatherEmail || student.motherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
         }
         setToast({ msg: 'Student moved to Assessment.', show: true, type: 'success' });
     } else {
         // Failure Logic: Must mark as rejected
         await rejectPayment(student.id);
         if (sendEmail) {
             const subject = "Enrollment Update: Payment Verification Failed";
             const body = `Dear ${student.parentName},\n\nThe receipt number (${student.receiptNumber}) provided for ${student.name} could not be verified.\n\nPlease check the number and try again on the parent portal.\n\nRegards,\nCircle of Hope Academy`;
             window.location.href = `mailto:${student.fatherEmail || student.motherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
         }
         setToast({ msg: 'Payment Rejected. Parent notified on dashboard.', show: true, type: 'error' });
     }

     setEmailModalOpen(false);
     loadData();
     getPendingActionCounts().then(setCounts);
  };

  const confirmDelete = (student: Student) => {
      setStudentToDelete(student);
      setDeleteModalOpen(true);
  };

  const handleDeleteStudent = async () => {
      if (studentToDelete) {
          await deleteStudent(studentToDelete.id);
          setDeleteModalOpen(false);
          setStudentToDelete(null);
          loadData();
          setToast({ msg: 'Record deleted successfully', show: true, type: 'success' });
      }
  };

  const handleAddReceipt = async () => {
      if (!newReceiptNumber || !newReceiptAmount) return;
      setLoading(true);
      const success = await addReceipt(newReceiptNumber, newReceiptAmount, new Date().toISOString());
      if (success) {
          setNewReceiptNumber('');
          setNewReceiptAmount('');
          loadData();
          setToast({ msg: 'Receipt added successfully', show: true, type: 'success' });
      }
      setLoading(false);
  };

  const handleDeleteReceipt = async (id: string) => {
      if(window.confirm('Delete this receipt?')) {
          await deleteReceipt(id);
          loadData();
      }
  };

  const filteredApps = applications.filter(app => {
      const matchesSearch = (() => {
        const fullName = `${app.firstName} ${app.surname}`.toLowerCase();
        const parent = (app.fatherName || app.motherName || '').toLowerCase();
        const term = searchTerm.toLowerCase();
        return fullName.includes(term) || parent.includes(term) || app.grade.toLowerCase().includes(term);
      })();
      return matchesSearch && app.status === statusFilter;
  });

  return (
    <div>
      <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({...toast, show: false})} variant={toast.type} />

      {/* Delete Confirmation Modal */}
      <ConfirmModal 
        isOpen={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        onConfirm={handleDeleteStudent}
        title="Delete Record?"
        message={`Are you sure you want to delete ${studentToDelete?.name}? This will permanently remove them from the admission process.`}
      />

      {/* Email / Finalize Modal */}
      {emailModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
            <div className={`bg-white w-full max-w-md shadow-2xl border-t-8 ${verifyResult.success ? 'border-green-500' : 'border-red-500'} animate-fade-in`}>
                <div className="p-6">
                    <h3 className={`text-xl font-bold mb-2 ${verifyResult.success ? 'text-green-700' : 'text-red-700'}`}>
                        {verifyResult.success ? 'Verification Successful' : 'Verification Failed'}
                    </h3>
                    <p className="text-gray-600 mb-6">{verifyResult.message} Would you like to send an email notification to the parent?</p>
                    <div className="flex flex-col gap-3">
                        <Button fullWidth onClick={() => finalizeVerification(true)}>
                            <Mail size={18} /> Update & Send Email
                        </Button>
                        <Button fullWidth variant="outline" onClick={() => finalizeVerification(false)}>
                            Update Only (Skip Email)
                        </Button>
                        <button onClick={() => setEmailModalOpen(false)} className="text-sm text-gray-500 hover:text-gray-900 mt-2">Cancel</button>
                    </div>
                </div>
            </div>
          </div>
      )}

      <div className="mb-6 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-coha-900">Admissions Management</h2>
            <p className="text-gray-600">Manage applications, verify payments, and issue receipts.</p>
        </div>
        <div className="flex flex-wrap bg-white shadow-sm border border-gray-200">
            <button 
                onClick={() => setViewMode('APPLICATIONS')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'APPLICATIONS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Applications
                {counts.pendingApps > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{counts.pendingApps}</span>}
            </button>
            <button 
                onClick={() => setViewMode('PENDING_PAYMENT')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'PENDING_PAYMENT' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Pending Payment
            </button>
            <button 
                onClick={() => setViewMode('VERIFICATION')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'VERIFICATION' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Payment Verification
                {counts.pendingVerifications > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{counts.pendingVerifications}</span>}
            </button>
            <button onClick={() => setViewMode('RECEIPTS')} className={`px-4 py-2 text-sm font-bold uppercase ${viewMode === 'RECEIPTS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}>Available Receipts</button>
        </div>
      </div>

      {/* MODE: APPLICATIONS (New / Rejected) */}
      {viewMode === 'APPLICATIONS' && (
          <div className="animate-fade-in">
             <div className="flex border-b border-gray-200 mb-6 bg-white shadow-sm overflow-x-auto">
                <button onClick={() => setStatusFilter('PENDING')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 flex items-center gap-2 ${statusFilter === 'PENDING' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>
                    Pending
                    {counts.pendingApps > 0 && <span className="bg-red-100 text-red-600 text-[10px] px-1.5 py-0.5 rounded-full">{counts.pendingApps}</span>}
                </button>
                <button onClick={() => setStatusFilter('REJECTED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${statusFilter === 'REJECTED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Rejected</button>
             </div>

             <div className="bg-white border border-gray-200 shadow-sm">
                <div className="p-4 border-b border-gray-200">
                    <div className="relative max-w-md">
                        <Search className="absolute left-3 top-3 text-gray-400" size={20} />
                        <input className="w-full pl-10 pr-4 py-2 border border-gray-300 outline-none" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                    </div>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-600">
                            <tr>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-6 py-4">Name</th>
                                <th className="px-6 py-4">Grade</th>
                                <th className="px-6 py-4">Parent</th>
                                <th className="px-6 py-4">Date</th>
                                <th className="px-6 py-4">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {filteredApps.map((app) => (
                                <tr key={app.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-bold border ${app.status === 'REJECTED' ? 'bg-red-100 text-red-800 border-red-200' : 'bg-yellow-100 text-yellow-800 border-yellow-200'}`}>{app.status}</span></td>
                                    <td className="px-6 py-4 font-bold text-coha-900">{app.surname}, {app.firstName}</td>
                                    <td className="px-6 py-4">{app.grade}</td>
                                    <td className="px-6 py-4">{app.fatherName || app.motherName}</td>
                                    <td className="px-6 py-4 text-xs">{app.submissionDate?.toDate().toLocaleDateString()}</td>
                                    <td className="px-6 py-4"><button onClick={() => navigate(`/admin/applications/${app.id}`)} className="text-coha-500 font-bold text-sm flex gap-1 items-center"><Eye size={16}/> View</button></td>
                                </tr>
                            ))}
                            {filteredApps.length === 0 && <tr><td colSpan={6} className="text-center py-8 text-gray-500">No applications found.</td></tr>}
                        </tbody>
                    </table>
                </div>
             </div>
          </div>
      )}

      {/* MODE: PENDING PAYMENT (Waiting Payment) */}
      {viewMode === 'PENDING_PAYMENT' && (
          <div className="animate-fade-in bg-white border border-gray-200 shadow-sm">
             <div className="p-4 border-b border-gray-200 bg-blue-50">
                 <h3 className="text-blue-800 font-bold flex items-center gap-2"><Clock size={20}/> Conditional Admissions</h3>
                 <p className="text-blue-700 text-sm">Students approved but waiting for parents to submit payment receipt.</p>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-600">
                        <tr>
                            <th className="px-6 py-4">Student</th>
                            <th className="px-6 py-4">Parent</th>
                            <th className="px-6 py-4">Login Details</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {pendingPaymentList.map((student) => (
                            <tr key={student.id} className="hover:bg-gray-50">
                                <td className="px-6 py-4">
                                    <p className="font-bold text-coha-900">{student.name}</p>
                                    <p className="text-xs text-gray-500">Grade: {student.grade}</p>
                                </td>
                                <td className="px-6 py-4">
                                    <p>{student.parentName}</p>
                                    <p className="text-xs text-gray-500">{student.fatherPhone || student.motherPhone}</p>
                                </td>
                                <td className="px-6 py-4 bg-gray-50">
                                    <div className="flex items-center gap-2 text-xs">
                                        <Key size={14} className="text-gray-400" />
                                        <span className="text-gray-500">PIN:</span> 
                                        <span className="font-mono font-bold text-coha-700 text-lg">{student.parentPin}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                     {student.paymentRejected ? (
                                        <span className="bg-red-100 text-red-800 border border-red-200 px-2 py-1 text-xs font-bold uppercase">Rejected - Retrying</span>
                                     ) : (
                                        <span className="bg-blue-100 text-blue-800 border border-blue-200 px-2 py-1 text-xs font-bold uppercase">Waiting Entry</span>
                                     )}
                                </td>
                                <td className="px-6 py-4">
                                    <button onClick={() => confirmDelete(student)} className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded">
                                        <Trash2 size={18} />
                                    </button>
                                </td>
                            </tr>
                        ))}
                        {pendingPaymentList.length === 0 && <tr><td colSpan={5} className="text-center py-8 text-gray-500">No students waiting for payment.</td></tr>}
                    </tbody>
                </table>
             </div>
          </div>
      )}

      {/* MODE: VERIFICATION */}
      {viewMode === 'VERIFICATION' && (
          <div className="animate-fade-in bg-white border border-gray-200 shadow-sm">
             <div className="p-4 border-b border-gray-200 bg-yellow-50">
                 <h3 className="text-yellow-800 font-bold flex items-center gap-2"><Clock size={20}/> Payment Verification</h3>
                 <p className="text-yellow-700 text-sm">Review receipts and approve for assessment.</p>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-600">
                        <tr>
                            <th className="px-6 py-4">Student</th>
                            <th className="px-6 py-4">Submitted Receipt #</th>
                            <th className="px-6 py-4">Date Submitted</th>
                            <th className="px-6 py-4">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {verificationList.map((student) => (
                            <tr key={student.id} className="hover:bg-gray-50">
                                <td className="px-6 py-4">
                                    <p className="font-bold text-coha-900">{student.name}</p>
                                    <p className="text-xs text-gray-500">ID: {student.id}</p>
                                </td>
                                <td className="px-6 py-4 font-mono font-bold text-lg text-coha-900">{student.receiptNumber}</td>
                                <td className="px-6 py-4 text-xs text-gray-500">{student.receiptSubmissionDate?.toDate().toLocaleString()}</td>
                                <td className="px-6 py-4">
                                    <Button onClick={() => handleVerifyClick(student)} disabled={loading} className="py-1 px-3 text-sm">
                                        Verify Payment
                                    </Button>
                                </td>
                            </tr>
                        ))}
                        {verificationList.length === 0 && <tr><td colSpan={4} className="text-center py-8 text-gray-500">No pending verifications.</td></tr>}
                    </tbody>
                </table>
             </div>
          </div>
      )}

      {/* MODE: RECEIPTS */}
      {viewMode === 'RECEIPTS' && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-1 bg-white p-6 shadow-sm border border-gray-200 h-fit">
                  <h3 className="font-bold text-lg mb-4">Add New Receipt</h3>
                  <div className="space-y-4">
                      <Input label="Receipt Number" value={newReceiptNumber} onChange={(e) => setNewReceiptNumber(e.target.value)} placeholder="e.g. R-10029" />
                      <Input label="Amount (N$)" value={newReceiptAmount} onChange={(e) => setNewReceiptAmount(e.target.value)} placeholder="300.00" />
                      <Button fullWidth onClick={handleAddReceipt} disabled={loading}>
                          <Plus size={20} /> Add Receipt
                      </Button>
                  </div>
              </div>

              <div className="lg:col-span-2 bg-white shadow-sm border border-gray-200">
                  <div className="p-4 border-b bg-gray-50 font-bold text-gray-700">Available Receipts</div>
                  <div className="overflow-x-auto max-h-[600px]">
                    <table className="w-full text-left">
                        <thead className="bg-white text-xs font-bold uppercase text-gray-600 sticky top-0">
                            <tr>
                                <th className="px-6 py-4">Receipt #</th>
                                <th className="px-6 py-4">Amount</th>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-6 py-4">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {receipts.map((receipt) => (
                                <tr key={receipt.id} className={receipt.isUsed ? 'bg-gray-100 opacity-70' : ''}>
                                    <td className="px-6 py-4 font-mono font-bold">{receipt.number}</td>
                                    <td className="px-6 py-4">N$ {receipt.amount}</td>
                                    <td className="px-6 py-4">
                                        {receipt.isUsed ? (
                                            <span className="text-xs font-bold text-gray-500 bg-gray-200 px-2 py-1">USED ({receipt.usedByStudentId})</span>
                                        ) : (
                                            <span className="text-xs font-bold text-green-600 bg-green-100 px-2 py-1">AVAILABLE</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        {!receipt.isUsed && (
                                            <button onClick={() => handleDeleteReceipt(receipt.id!)} className="text-red-400 hover:text-red-600">
                                                <Trash2 size={16}/>
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                            {receipts.length === 0 && <tr><td colSpan={4} className="text-center py-8">No receipts added.</td></tr>}
                        </tbody>
                    </table>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React from 'react';

export enum UserRole {
  ADMIN = 'ADMIN',
  TEACHER = 'TEACHER',
  PARENT = 'PARENT'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  pin: string;
}

export interface Teacher extends User {
  subject?: string;
  email?: string;
}

export interface MenuItem {
  label: string;
  path: string;
  icon: React.ReactNode;
}

export interface FeeItem {
  id: string;
  category: string;
  amount: string; // Stored as string to handle decimals, but input is number
  frequency: string;
  notes?: string;
}

export interface SupplyItem {
  id: string;
  name: string;
  isRequired: boolean;
}

export interface SystemSettings {
  id?: string;
  adminName: string;
  adminPin: string;

  // Structured Data
  fees: FeeItem[];
  uniforms: SupplyItem[];
  stationery: SupplyItem[];
  grades: string[];

  termStartDate: string;
  termStartTime: string;

  // Counters
  lastStudentId?: number; 
}

export interface Application {
  id?: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  submissionDate: any; // Firestore Timestamp

  // Learner Details
  surname: string;
  firstName: string;
  dob: string;
  citizenship: string;
  gender: 'Male' | 'Female';
  address: string;
  region: string;
  grade: string;
  isSpecialNeeds: boolean;
  specialNeedsType?: string; // Slow learner, Down Syndrome, Autism, etc.

  // Parent Details
  fatherName: string;
  fatherPhone: string;
  fatherEmail: string;
  motherName: string;
  motherPhone: string;
  motherEmail?: string;

  // Emergency Contact
  emergencyName: string;
  emergencyRelationship: string;
  emergencyWork: string;
  emergencyCell: string;
  emergencyEmail: string;

  // Medical & History
  hasPreviousSchool: boolean;
  previousSchool: string;
  highestGrade: string;
  medicalConditions: string;

  // Professionals
  doctorName?: string;
  doctorContact?: string;
  audiologistName?: string;
  audiologistContact?: string;
  therapistName?: string;
  therapistContact?: string;

  // Medical Aid
  hasMedicalAid: boolean;
  medicalAidName?: string;
  medicalAidMemberName?: string;
  medicalAidMemberID?: string;
  medicalAidOption?: string;

  // Languages
  langEnglish: 'Good' | 'Fair' | 'Poor';
  langOther1Name?: string;
  langOther1Rating?: 'Good' | 'Fair' | 'Poor';
  langOther2Name?: string;
  langOther2Rating?: 'Good' | 'Fair' | 'Poor';

  // Consents
  medicalConsent: boolean;
  agreed: boolean;

  // Office Use
  officeReviewDate?: string;
  officeReviewer?: string;
  officeStatus?: string;
  officeResponseDate?: string;
  officeResponseMethod?: string;
}

export type StudentStatus = 'WAITING_PAYMENT' | 'PAYMENT_VERIFICATION' | 'ASSESSMENT' | 'ENROLLED';

// Student extends Application to allow full profile view
export interface Student extends Partial<Application> {
  id: string;
  name: string; // Display Name (First + Surname)
  grade: string;
  parentPin: string;
  parentName: string;
  enrolledAt?: any;
  studentStatus: StudentStatus;

  // Payment Verification
  receiptNumber?: string;
  receiptSubmissionDate?: any;
  paymentRejected?: boolean; // New flag for parent dashboard
}

export interface Receipt {
  id?: string;
  number: string;
  amount: string;
  date: string;
  isUsed: boolean;
  usedByStudentId?: string;
  createdAt?: any;
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { submitApplication, getSystemSettings } from '../services/dataService';
import { ArrowLeft, CheckCircle, ArrowRight, Check, AlertCircle } from 'lucide-react';
import { Button } from '../components/ui/Button';
import { CustomSelect } from '../components/ui/CustomSelect';

const STEPS = [
  "Learner",
  "Parents", 
  "History",
  "Medical",
  "Consent"
];

// Simple Input for Google Forms Style
const FormInput: React.FC<React.InputHTMLAttributes<HTMLInputElement> & { label: string }> = ({ label, className = '', required, ...props }) => (
  <div className="w-full mb-6">
    <label className="block text-gray-800 text-sm font-medium mb-2">
      {label} {required && <span className="text-red-500">*</span>}
    </label>
    <input
      className={`w-full p-3 border-b-2 border-gray-300 focus:border-coha-500 outline-none transition-colors bg-gray-50 focus:bg-white text-gray-900 ${className}`}
      {...props}
    />
  </div>
);

export const ApplyPage: React.FC = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [gradesList, setGradesList] = useState<string[]>([]);

  // Validation State
  const [shakeError, setShakeError] = useState(false);
  const [errorField, setErrorField] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    surname: '', firstName: '', dob: '', citizenship: '', gender: 'Male', 
    address: '', region: '', grade: '', isSpecialNeeds: false, specialNeedsType: '',
    fatherName: '', fatherPhone: '', fatherEmail: '',
    motherName: '', motherPhone: '', motherEmail: '',
    emergencyName: '', emergencyRelationship: '', emergencyWork: '', emergencyCell: '', emergencyEmail: '',
    hasPreviousSchool: true, previousSchool: '', highestGrade: '',
    langEnglish: 'Good', 
    langOther1Name: '', langOther1Rating: 'Fair',
    langOther2Name: '', langOther2Rating: 'Fair',
    medicalConditions: '',
    doctorName: '', doctorContact: '',
    audiologistName: '', audiologistContact: '',
    therapistName: '', therapistContact: '',
    hasMedicalAid: false,
    medicalAidName: '', medicalAidMemberName: '', medicalAidMemberID: '', medicalAidOption: '',
    medicalConsent: false,
    agreed: false
  });

  useEffect(() => {
    const fetchGrades = async () => {
        const settings = await getSystemSettings();
        if (settings && settings.grades) {
            setGradesList(settings.grades);
        } else {
            setGradesList(['Grade 1', 'Grade 2', 'Grade 3']);
        }
    };
    fetchGrades();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
      const checked = (e.target as HTMLInputElement).checked;
      setFormData(prev => ({ ...prev, [name]: checked }));
      if (name === 'agreed' || name === 'medicalConsent') setErrorField(null); // Clear error on interaction
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleCustomSelect = (name: string, value: string) => {
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNext = () => {
    if (currentStep < STEPS.length - 1) {
      setCurrentStep(prev => prev + 1);
      scrollToTop();
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep(prev => prev - 1);
      scrollToTop();
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validation Check for Consent & Agreement
    if (!formData.medicalConsent || !formData.agreed) {
      setShakeError(true);
      setErrorField('consent');
      setTimeout(() => setShakeError(false), 600); // Remove animation class after plays

      // Highlight the error section (Pulse effect via css class below)
      return;
    }

    setLoading(true);
    const success = await submitApplication(formData as any);
    if (success) {
      setSubmitted(true);
      scrollToTop();
    }
    setLoading(false);
  };

  if (submitted) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4 animate-fade-in">
        <div className="bg-white p-8 rounded-lg max-w-sm w-full text-center shadow-2xl">
          <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
            <CheckCircle className="text-green-600" size={32} />
          </div>
          <h2 className="text-xl font-bold text-gray-900 mb-2">Application Sent!</h2>
          <p className="text-sm text-gray-600 mb-6">
            We have received your details. Our admissions team will be in touch shortly.
          </p>
          <Button fullWidth onClick={() => navigate('/')}>Done</Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 pb-20">
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          20% { transform: translateX(-10px); }
          40% { transform: translateX(10px); }
          60% { transform: translateX(-10px); }
          80% { transform: translateX(10px); }
        }
        .animate-shake {
          animation: shake 0.5s ease-in-out;
        }
        .error-pulse {
          animation: pulse-red 1s infinite;
        }
        @keyframes pulse-red {
          0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4); }
          70% { box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
          100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
        }
      `}</style>

      {/* Header */}
      <div className="sticky top-0 bg-white z-40 border-b border-gray-100 shadow-sm">
        <div className="px-5 py-3 flex items-center gap-4">
          <button onClick={() => navigate('/')} className="text-gray-500 hover:text-coha-900">
            <ArrowLeft size={20} />
          </button>
          <h1 className="text-sm font-bold text-gray-600">Online Application</h1>
        </div>

        {/* Stepper */}
        <div className="px-5 pb-3 pt-1">
          <div className="flex items-center justify-between relative">
            {/* Connecting Line */}
            <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-200 -z-10 transform -translate-y-1/2"></div>
            <div 
              className="absolute top-1/2 left-0 h-0.5 bg-coha-500 -z-10 transform -translate-y-1/2 transition-all duration-300"
              style={{ width: `${(currentStep / (STEPS.length - 1)) * 100}%` }}
            ></div>

            {STEPS.map((step, index) => {
              const isCompleted = index < currentStep;
              const isCurrent = index === currentStep;

              return (
                <div key={index} className="flex flex-col items-center bg-white px-1">
                  <div 
                    className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold border-2 transition-all duration-300 ${
                      isCompleted ? 'bg-coha-500 border-coha-500 text-white' : 
                      isCurrent ? 'bg-white border-coha-500 text-coha-500 scale-110' : 
                      'bg-white border-gray-300 text-gray-400'
                    }`}
                  >
                    {isCompleted ? <Check size={14} /> : index + 1}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="text-center mt-2">
            <span className="text-xs font-bold text-coha-900 uppercase tracking-wide">{STEPS[currentStep]}</span>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="px-5 pt-8 max-w-5xl mx-auto">

        {/* Step 1: Learner */}
        {currentStep === 0 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Left Col */}
            <div>
                <FormInput name="surname" label="Surname" value={formData.surname} onChange={handleChange} required />
                <FormInput name="firstName" label="First Name" value={formData.firstName} onChange={handleChange} required />
                <FormInput name="dob" label="Date of Birth" type="date" value={formData.dob} onChange={handleChange} required />

                <CustomSelect 
                  label="Gender"
                  value={formData.gender}
                  options={[{ label: 'Male', value: 'Male' }, { label: 'Female', value: 'Female' }]}
                  onChange={(val) => handleCustomSelect('gender', val)}
                />

                <FormInput name="citizenship" label="Citizenship" value={formData.citizenship} onChange={handleChange} required />
            </div>

            {/* Right Col */}
            <div>
                <CustomSelect 
                  label="Grade Applying For"
                  value={formData.grade}
                  options={gradesList.map(g => ({ label: g, value: g }))}
                  onChange={(val) => handleCustomSelect('grade', val)}
                  required
                />

                <FormInput name="address" label="Residential Address" value={formData.address} onChange={handleChange} required />

                <div className="mt-6 mb-6">
                  <label className="flex items-start gap-3 cursor-pointer p-4 bg-gray-50 border border-gray-200 rounded-lg">
                    <input 
                      type="checkbox" 
                      name="isSpecialNeeds" 
                      checked={formData.isSpecialNeeds} 
                      onChange={handleChange}
                      className="mt-1 w-5 h-5 accent-coha-500"
                    />
                    <div>
                      <span className="font-bold text-gray-800 text-sm">Special Needs Application</span>
                      <p className="text-xs text-gray-500 mt-1">Check this if the learner requires special educational support.</p>
                    </div>
                  </label>
                </div>

                {formData.isSpecialNeeds && (
                  <div className="animate-fade-in pl-4 border-l-2 border-coha-500 mb-6">
                    <CustomSelect 
                      label="Type of Special Needs"
                      value={formData.specialNeedsType}
                      options={[
                        { label: 'Intellectual/Learning Difficulties', value: 'Intellectual/Learning Difficulties' },
                        { label: 'Down Syndrome', value: 'Down Syndrome' },
                        { label: 'Autism', value: 'Autism' },
                        { label: 'Other', value: 'Other' }
                      ]}
                      onChange={(val) => handleCustomSelect('specialNeedsType', val)}
                    />
                  </div>
                )}
            </div>
          </div>
        )}

        {/* ... (Other steps remain same but shortened for XML space, they just use FormInput which is locally defined still) ... */}
        {/* Step 2: Parents */}
        {currentStep === 1 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6">Parent / Guardian Details</h3>
                <FormInput name="fatherName" label="Father/Guardian Name" value={formData.fatherName} onChange={handleChange} required />
                <FormInput name="fatherPhone" label="Phone Number" type="tel" value={formData.fatherPhone} onChange={handleChange} required />
                <FormInput name="fatherEmail" label="Email Address" type="email" value={formData.fatherEmail} onChange={handleChange} required />
                <div className="w-full h-px bg-gray-200 my-8"></div>
                <FormInput name="motherName" label="Mother/Guardian Name" value={formData.motherName} onChange={handleChange} />
                <FormInput name="motherPhone" label="Phone Number" type="tel" value={formData.motherPhone} onChange={handleChange} />
                <FormInput name="motherEmail" label="Email Address" type="email" value={formData.motherEmail} onChange={handleChange} />
            </div>
            <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Emergency Contact</h3>
                <div className="bg-red-50 p-4 border-l-4 border-red-400 mb-6 rounded-r-lg">
                  <p className="text-xs text-red-800">Please provide a contact other than the parents.</p>
                </div>
                <FormInput name="emergencyName" label="Full Name" value={formData.emergencyName} onChange={handleChange} required />
                <FormInput name="emergencyRelationship" label="Relationship" value={formData.emergencyRelationship} onChange={handleChange} required />
                <FormInput name="emergencyCell" label="Cell Number" type="tel" value={formData.emergencyCell} onChange={handleChange} required />
                <FormInput name="emergencyWork" label="Work Contact" value={formData.emergencyWork} onChange={handleChange} />
                <FormInput name="emergencyEmail" label="Email Address" type="email" value={formData.emergencyEmail} onChange={handleChange} />
            </div>
          </div>
        )}

        {/* Step 3: History */}
        {currentStep === 2 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Educational History</h3>
                 <div className="mb-6">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                      type="checkbox" 
                      name="hasPreviousSchool" 
                      checked={!formData.hasPreviousSchool} 
                      onChange={(e) => setFormData({...formData, hasPreviousSchool: !e.target.checked})}
                      className="w-5 h-5 accent-coha-500"
                    />
                    <span className="text-sm text-gray-700">First time attender (No previous school)</span>
                  </label>
                </div>
                {formData.hasPreviousSchool && (
                  <div className="pl-4 border-l-2 border-gray-200 mb-8">
                    <FormInput name="previousSchool" label="Previous School Name" value={formData.previousSchool} onChange={handleChange} />
                    <FormInput name="highestGrade" label="Highest Grade Completed" value={formData.highestGrade} onChange={handleChange} />
                  </div>
                )}
             </div>
             <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Language Proficiency</h3>
                <div className="mb-6">
                  <label className="block text-gray-800 text-sm font-medium mb-2">English Proficiency</label>
                  <div className="flex gap-4">
                    {['Good', 'Fair', 'Poor'].map(rating => (
                      <label key={rating} className="flex items-center gap-2 cursor-pointer bg-gray-50 px-3 py-2 rounded border border-gray-200">
                        <input 
                          type="radio" 
                          name="langEnglish" 
                          value={rating} 
                          checked={formData.langEnglish === rating} 
                          onChange={handleChange}
                          className="accent-coha-500" 
                        />
                        <span className="text-sm">{rating}</span>
                      </label>
                    ))}
                  </div>
                </div>
                <FormInput name="langOther1Name" label="Other Language (Optional)" value={formData.langOther1Name} onChange={handleChange} />
             </div>
          </div>
        )}

        {/* Step 4: Medical */}
        {currentStep === 3 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Medical Information</h3>
                 <div className="mb-6">
