// Helper: Calculate Age from DOB
const calculateAge = (dobString: string): number => {
  const today = new Date();
  const birthDate = new Date(dobString);
  let age = today.getFullYear() - birthDate.getFullYear();
  const m = today.getMonth() - birthDate.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
    age--;
  }
  return age;
};

// Helper: Determine Special Needs Level
export const determineSpecialNeedsLevel = (dob: string): string => {
  const age = calculateAge(dob);
  if (age >= 11) return 'Level 3'; // 11+
  if (age >= 9) return 'Level 2';  // 9-10
  if (age >= 7) return 'Level 1B'; // 7-8
  return 'Level 1A'; // 5-6 (Default for younger too)
};

