export const saveTeacherAssessmentDay = async (studentId: string, day: number, dayData: any) => {
    const student = await getStudentById(studentId);
    if (!student || !student.assessment) return false;

    const updatedAssessment = {
        ...student.assessment,
        teacherAssessments: {
            ...student.assessment.teacherAssessments,
            [day]: dayData
        }
    };

    await updateStudent(studentId, { assessment: updatedAssessment });
    return true;
};

export const calculateFinalStage = async (studentId: string) => {
    const student = await getStudentById(studentId);
    if (!student || !student.assessment) return false;

    const assessment = student.assessment;
    let teacherTotal = 0;
    let daysCount = 0;

    // Sum daily averages (Each day has 3 scores: Main, Thinking, ABC. Daily Avg = (M+T+A)/3)
    // Prompt says: "It adds up the parent's and teacher's scores. It gives one overall average score out of 5."
    // Let's Average all teacher components then average with parent.

    let totalDailyScores = 0;

    Object.values(assessment.teacherAssessments).forEach((day: any) => {
        if (day.completed) {
            // Main score is avg of 5 areas
            const mainAvg = (day.scores.numbers + day.scores.reading + day.scores.selfCare + day.scores.behaviour + day.scores.senses) / 5;
            // Daily Total Average
            const dailyAvg = (mainAvg + day.thinkingScore + day.abcScore) / 3;

            totalDailyScores += dailyAvg;
            daysCount++;
        }
    });

    if (daysCount === 0) return false;

    const teacherOverallAvg = totalDailyScores / daysCount;
    const parentScore = assessment.parentSelfCareScore || 0;

    // Overall Average
    const finalAverage = (teacherOverallAvg + parentScore) / 2;

    // Determine Stage
    let stage: 1 | 2 | 3 = 1;
    if (finalAverage >= 3.8) stage = 3;
    else if (finalAverage >= 2.4) stage = 2;
    else stage = 1;

    // Update Student
    const assignedClass = `${student.level} - Stage ${stage}`;

    await updateStudent(studentId, {
        assessment: { ...assessment, finalAverage, stage, isComplete: true },
        stage,
        assignedClass,
        studentStatus: 'ENROLLED' // Move to enrolled after assessment
    });

    return assignedClass;
};


