const XIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
);

import React, { useState, useEffect } from 'react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { CustomSelect } from '../../components/ui/CustomSelect';
import { addTeacher, getTeachers, deleteTeacher, updateTeacher, getSystemSettings } from '../../services/dataService';
import { Teacher, SystemSettings } from '../../types';
import { Plus, Search, Trash2, Edit2 } from 'lucide-react';
import { ConfirmModal } from '../../components/ui/ConfirmModal';

export const TeachersPage: React.FC = () => {
  const [teachers, setTeachers] = useState<Teacher[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [settings, setSettings] = useState<SystemSettings | null>(null);

  // Form State
  const [name, setName] = useState('');
  const [subject, setSubject] = useState('');
  const [assignedClass, setAssignedClass] = useState('');
  const [loading, setLoading] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Delete State
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [teacherToDelete, setTeacherToDelete] = useState<Teacher | null>(null);

  const fetchData = async () => {
    const data = await getTeachers();
    const settingsData = await getSystemSettings();
    setTeachers(data);
    setSettings(settingsData);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleEdit = (teacher: Teacher) => {
    setName(teacher.name);
    setSubject(teacher.subject || '');
    setAssignedClass(teacher.assignedClass || '');
    setEditingId(teacher.id);
    setShowForm(true);
  };

  const handleFormClose = () => {
    setShowForm(false);
    setName('');
    setSubject('');
    setAssignedClass('');
    setEditingId(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    let success = false;
    if (editingId) {
        success = await updateTeacher(editingId, { name, subject, assignedClass });
    } else {
        success = await addTeacher(name, subject, assignedClass);
    }

    if (success) {
      handleFormClose();
      fetchData();
    }
    setLoading(false);
  };

  const confirmDelete = (teacher: Teacher) => {
    setTeacherToDelete(teacher);
    setDeleteModalOpen(true);
  };

  const handleDelete = async () => {
    if (teacherToDelete) {
        setLoading(true);
        const success = await deleteTeacher(teacherToDelete.id);
        if (success) {
            setDeleteModalOpen(false);
            setTeacherToDelete(null);
            fetchData();
        }
        setLoading(false);
    }
  };

  const filteredTeachers = teachers.filter(t => 
      t.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (t.subject && t.subject.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // Build Class Options from Settings
  const getClassOptions = () => {
      if (!settings) return [];
      const grades = settings.grades.map(g => ({ label: g, value: g }));

      // For Special Needs, teachers might be assigned to a Level or a Stage
      // Let's create general Level buckets for now, since stages are dynamic
      const levels = settings.specialNeedsLevels.map(l => ({ label: `${l} (Special Needs)`, value: l }));

      return [...grades, ...levels];
  };

  return (
    <div>
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-coha-900">Teachers</h2>
          <p className="text-gray-600">Manage faculty members.</p>
        </div>
        <Button onClick={() => setShowForm(!showForm)}>
          <Plus size={20} /> {editingId ? 'Edit Teacher' : 'Add Teacher'}
        </Button>
      </div>

      <ConfirmModal 
        isOpen={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        onConfirm={handleDelete}
        title="Delete Teacher?"
        message={`Are you sure you want to delete ${teacherToDelete?.name}? This action cannot be undone.`}
        isLoading={loading}
      />

      {showForm && (
        <div className="bg-white p-6 mb-8 border-t-4 border-coha-500 shadow-lg animate-fade-in">
          <h3 className="text-lg font-bold mb-4">{editingId ? 'Edit Teacher Details' : 'Add New Teacher'}</h3>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input 
              label="Full Name" 
              placeholder="e.g. Mrs. Sarah Smith" 
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
            <Input 
              label="Subject / Role" 
              placeholder="e.g. Mathematics" 
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              required
            />
            <div className="md:col-span-2">
                <CustomSelect 
                    label="Assigned Class / Division"
                    value={assignedClass}
                    options={getClassOptions()}
                    onChange={setAssignedClass}
                    placeholder="Select class..."
                />
            </div>

            <div className="md:col-span-2 flex justify-end gap-2 mt-2">
              <Button type="button" variant="outline" onClick={handleFormClose}>Cancel</Button>
              <Button type="submit" disabled={loading}>{loading ? 'Saving...' : (editingId ? 'Update Teacher' : 'Save Teacher')}</Button>
            </div>
          </form>
        </div>
      )}

      <div className="bg-white border border-gray-200 shadow-sm">
        <div className="p-4 border-b border-gray-200 flex gap-2">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-3 text-gray-400" size={20} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-300 focus:border-coha-500 outline-none rounded-none"
              placeholder="Search teachers..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">Subject</th>
                <th className="px-6 py-4">Assigned Class</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredTeachers.map((teacher) => (
                <tr key={teacher.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 font-bold text-coha-900">{teacher.name}</td>
                  <td className="px-6 py-4">{teacher.subject}</td>
                  <td className="px-6 py-4">
                      {teacher.assignedClass ? <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 font-bold rounded">{teacher.assignedClass}</span> : <span className="text-gray-400 italic">Unassigned</span>}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2">
                        <button onClick={() => handleEdit(teacher)} className="text-coha-500 hover:text-coha-700 p-1">
                            <Edit2 size={18} />
                        </button>
                        <button onClick={() => confirmDelete(teacher)} className="text-red-400 hover:text-red-600 p-1">
                            <Trash2 size={18} />
                        </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredTeachers.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-6 py-8 text-center text-gray-500">No teachers found.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Student, Division } from '../../types';
import { submitPaymentReceipt, getStudentById, saveParentAssessment } from '../../services/dataService';
import { Loader } from '../../components/ui/Loader';
import { Input } from '../../components/ui/Input';
import { Button } from '../../components/ui/Button';
import { AlertCircle, CheckCircle, Clock, FileText, Heart, Star } from 'lucide-react';
import { CustomSelect } from '../../components/ui/CustomSelect';

interface ParentDashboardProps {
  user: any; 
}

export const ParentDashboard: React.FC<ParentDashboardProps> = ({ user }) => {
  const [student, setStudent] = useState<Student | null>(null);
  const [receiptNumber, setReceiptNumber] = useState('');
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  // Assessment State
  const [selfCareScore, setSelfCareScore] = useState(0);
  const [assessmentDone, setAssessmentDone] = useState(false);

  useEffect(() => {
    if (user?.id) {
        getStudentById(user.id).then((s) => {
            setStudent(s);
            if (s?.assessment?.parentSelfCareScore) {
                setAssessmentDone(true);
            }
        });
    }
  }, [user]);

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!receiptNumber || !student) return;

      setLoading(true);
      const success = await submitPaymentReceipt(student.id, receiptNumber);
      if (success) {
          setSubmitted(true);
          setStudent({...student, studentStatus: 'PAYMENT_VERIFICATION', paymentRejected: false});
      }
      setLoading(false);
  };

  const handleAssessmentSubmit = async () => {
      if(!student) return;
      setLoading(true);
      const success = await saveParentAssessment(student.id, selfCareScore);
      if(success) {
          setAssessmentDone(true);
          setStudent(await getStudentById(student.id)); // refresh
      }
      setLoading(false);
  };

  if (!student) return <Loader />;

  // STATUS: WAITING_PAYMENT
  if (student.studentStatus === 'WAITING_PAYMENT') {
      return (
          <div className="max-w-md mx-auto mt-10 animate-fade-in">
              {student.paymentRejected && (
                  <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 shadow-sm">
                      <div className="flex items-start gap-3">
                          <AlertCircle className="text-red-600 shrink-0" size={24} />
                          <div>
                              <h3 className="text-red-800 font-bold">Payment Verification Failed</h3>
                              <p className="text-red-700 text-sm mt-1">The receipt number you provided was invalid or already used. Please check your receipt and try again.</p>
                          </div>
                      </div>
                  </div>
              )}

              <div className="p-6 bg-white shadow-lg border-t-8 border-coha-900">
                <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center mx-auto mb-4">
                        <AlertCircle size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-2">Complete Enrollment</h2>
                    <p className="text-gray-600">Your application has been conditionally approved. Please confirm your application fee payment to proceed.</p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <Input 
                        label="Enter Receipt Number" 
                        placeholder="e.g. R-99382" 
                        value={receiptNumber} 
                        onChange={(e) => setReceiptNumber(e.target.value)} 
                        required
                    />
                    <Button fullWidth disabled={loading}>
                        {loading ? 'Submitting...' : 'Verify Payment'}
                    </Button>
                </form>
              </div>
          </div>
      );
  }

  // STATUS: PAYMENT_VERIFICATION
  if (student.studentStatus === 'PAYMENT_VERIFICATION') {
      return (
          <div className="max-w-md mx-auto mt-10 p-8 bg-white shadow-lg text-center animate-fade-in">
               <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4 animate-pulse">
                  <Clock size={32} />
               </div>
               <h2 className="text-2xl font-bold text-gray-900 mb-2">Verifying Payment</h2>
               <p className="text-gray-600">We have received your receipt number. The administration is currently verifying the payment. This usually takes 24 hours.</p>
          </div>
      );
  }

  // STATUS: ASSESSMENT (Special Needs Only)
  if (student.studentStatus === 'ASSESSMENT') {
      return (
          <div className="max-w-2xl mx-auto mt-10 animate-fade-in">
               <div className="bg-white p-8 shadow-lg border-t-8 border-purple-600 mb-6">
                    <div className="text-center mb-8">
                        <div className="w-16 h-16 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mx-auto mb-4">
                            <FileText size={32} />
                        </div>
                        <h2 className="text-2xl font-bold text-gray-900 mb-2">Observation Period Active</h2>
                        <p className="text-gray-600">
                            Your child is currently in the 14-day "Watch and Learn" observation period. 
                            Teachers are assessing daily progress to determine the best class placement.
                        </p>
                    </div>

                    {!assessmentDone ? (
                        <div className="bg-purple-50 p-6 border border-purple-100 rounded-lg">
                            <h3 className="font-bold text-purple-900 mb-4 flex items-center gap-2">
                                <Heart size={20}/> Parent Task: Self-care Skills Assessment
                            </h3>
                            <p className="text-sm text-purple-800 mb-6">
                                Please rate your child's ability to perform daily self-care tasks (dressing, eating, toileting, washing) on a scale of 1 to 5.
                                <br/><span className="text-xs italic mt-1 block">1 = Needs full help, 5 = Independent</span>
                            </p>

                            <div className="mb-6">
                                <label className="block text-gray-700 font-bold mb-2">Self-care Rating (1-5)</label>
                                <div className="flex justify-between gap-2">
                                    {[1, 2, 3, 4, 5].map((score) => (
                                        <button
                                            key={score}
                                            onClick={() => setSelfCareScore(score)}
                                            className={`flex-1 py-3 border font-bold transition-all ${
                                                selfCareScore === score 
                                                ? 'bg-purple-600 text-white border-purple-600 shadow-md scale-105' 
                                                : 'bg-white text-gray-600 hover:bg-gray-50 border-gray-300'
                                            }`}
                                        >
                                            {score}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <Button fullWidth onClick={handleAssessmentSubmit} disabled={loading || selfCareScore === 0}>
                                {loading ? 'Saving...' : 'Submit Assessment'}
                            </Button>
                        </div>
                    ) : (
                        <div className="bg-green-50 p-6 border border-green-200 text-center">
                            <CheckCircle className="text-green-600 mx-auto mb-2" size={32} />
                            <h3 className="font-bold text-green-800">Parent Assessment Submitted</h3>
                            <p className="text-green-700 text-sm">Thank you! Your input has been recorded. Please wait for the teacher's observation to complete.</p>
                        </div>
                    )}
               </div>
          </div>
      );
  }

  // STATUS: ENROLLED
  return (
      <div className="max-w-4xl mx-auto">
          <div className="bg-white p-6 shadow-sm border-l-4 border-green-500 mb-6">
              <h2 className="text-2xl font-bold text-gray-900">Welcome, {student.parentName}</h2>
              <div className="flex items-center gap-2 mt-2">
                  <div className={`text-sm px-2 py-1 rounded font-bold ${student.division === Division.SPECIAL_NEEDS ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 text-gray-800'}`}>
                      {student.division}
                  </div>
                  {student.stage && (
                      <div className="text-sm px-2 py-1 rounded font-bold bg-purple-100 text-purple-800 flex items-center gap-1">
                          <Star size={12}/> Stage {student.stage}
                      </div>
                  )}
              </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-white p-6 shadow-sm">
                  <h3 className="font-bold text-lg mb-4 border-b pb-2">Student Profile</h3>
                  <div className="space-y-3">
                      <p><span className="text-gray-500 font-bold text-xs uppercase">Full Name:</span> <br/>{student.name}</p>
                      <p><span className="text-gray-500 font-bold text-xs uppercase">Student ID:</span> <br/>{student.id}</p>
                      <div className="bg-gray-50 p-3 border border-gray-200">
                          <span className="text-gray-500 font-bold text-xs uppercase block mb-1">Assigned Class</span>
                          <span className="text-xl font-bold text-coha-900">{student.assignedClass || student.grade}</span>
                          {student.division === Division.SPECIAL_NEEDS && (
                              <p className="text-xs text-gray-500 mt-1">Based on Age & Assessment</p>
                          )}
                      </div>
                  </div>
              </div>

              <div className="bg-white p-6 shadow-sm">
                  <h3 className="font-bold text-lg mb-4 border-b pb-2">Financial Status</h3>
                  <div className="flex items-center gap-3 text-green-700 bg-green-50 p-4 rounded">
                      <CheckCircle size={24} />
                      <div>
                          <p className="font-bold">Enrolled</p>
                          <p className="text-sm">Account is active.</p>
                      </div>
                  </div>
              </div>
          </div>
      </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../../components/ui/Button';
import { getStudents, getSystemSettings, getStudentsByStatus, assessStudent, calculateFinalStage } from '../../services/dataService';
import { Student, SystemSettings, Division } from '../../types';
import { Plus, Search, Eye, Download, CheckSquare, Activity } from 'lucide-react';
import { Toast } from '../../components/ui/Toast';
import { printStudentList } from '../../utils/printStudentList';

export const StudentsPage: React.FC = () => {
  const [viewMode, setViewMode] = useState<'ENROLLED' | 'ASSESSMENT'>('ENROLLED');
  const [students, setStudents] = useState<Student[]>([]);
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [settings, setSettings] = useState<SystemSettings | null>(null);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({show: false, msg: ''});

  const fetchStudents = async () => {
    setLoading(true);
    let data: Student[] = [];
    if (viewMode === 'ENROLLED') {
         // Get both strictly enrolled and legacy/manual adds (which might not have studentStatus set yet)
         const all = await getStudents();
         data = all.filter(s => s.studentStatus === 'ENROLLED' || !s.studentStatus);
    } else {
         data = await getStudentsByStatus('ASSESSMENT');
    }
    setStudents(data);
    const settingsData = await getSystemSettings();
    setSettings(settingsData);
    setLoading(false);
  };

  useEffect(() => {
    fetchStudents();
  }, [viewMode]);

  const handleFinalizeAssessment = async (studentId: string) => {
      // This is for Admin override or check
      if(window.confirm('Calculate final stage and enroll student?')) {
          setLoading(true);
          const result = await calculateFinalStage(studentId);
          setLoading(false);
          if (result) {
              setToast({show: true, msg: `Student enrolled in ${result}`});
              fetchStudents();
          } else {
              setToast({show: true, msg: 'Could not calculate. Ensure assessments are present.'});
          }
      }
  };

  const filteredStudents = students.filter(student => 
    student.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (student.parentName && student.parentName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div>
      <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({show:false, msg:''})} variant="success" />

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-coha-900">Students</h2>
          <p className="text-gray-600">Manage enrollment and student records.</p>
        </div>
        {viewMode === 'ENROLLED' && (
             <Button variant="outline" onClick={() => printStudentList(filteredStudents, settings)}>
                <Download size={20} /> Download List
            </Button>
        )}
      </div>

      <div className="flex border-b border-gray-200 mb-6 bg-white shadow-sm">
         <button onClick={() => setViewMode('ENROLLED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${viewMode === 'ENROLLED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Registered Students</button>
         <button onClick={() => setViewMode('ASSESSMENT')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${viewMode === 'ASSESSMENT' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Observation Period</button>
      </div>

      <div className="bg-white border border-gray-200 shadow-sm">
        <div className="p-4 border-b border-gray-200 flex gap-2">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-3 text-gray-400" size={20} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-300 focus:border-coha-500 outline-none rounded-none"
              placeholder="Search students..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold">
              <tr>
                <th className="px-6 py-4">ID</th>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4">Division</th>
                <th className="px-6 py-4">Class/Level</th>
                <th className="px-6 py-4">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 font-mono text-xs">{student.id}</td>
                  <td className="px-6 py-4 font-bold text-coha-900">{student.name}</td>
                  <td className="px-6 py-4">
                     <span className={`px-2 py-1 text-xs font-bold uppercase rounded ${student.division === Division.SPECIAL_NEEDS ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 text-gray-800'}`}>
                         {student.division || 'Mainstream'}
                     </span>
                  </td>
                  <td className="px-6 py-4 font-medium">
                      {student.assignedClass || student.grade || student.level}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex gap-2">
                        {viewMode === 'ASSESSMENT' ? (
                            <Button onClick={() => handleFinalizeAssessment(student.id)} className="py-1 px-3 text-xs">
                                <Activity size={14} /> View Progress
                            </Button>
                        ) : (
                            <button 
                            onClick={() => navigate(`/admin/students/${student.id}`)}
                            className="text-coha-500 hover:text-coha-700 font-bold text-sm flex items-center gap-1"
                            >
                            <Eye size={16} /> View Profile
                            </button>
                        )}
                    </div>
                  </td>
                </tr>
              ))}
               {filteredStudents.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-gray-500">No students found.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

