export const calculateFinalStage = async (studentId: string) => {
    const student = await getStudentById(studentId);
    if (!student || !student.assessment) return false;

    const assessment = student.assessment;
    let daysCount = 0;
    let totalDailyScores = 0;

    Object.values(assessment.teacherAssessments).forEach((day: any) => {
        if (day.completed) {
            // Main score is avg of 5 areas
            const mainAvg = (day.scores.numbers + day.scores.reading + day.scores.selfCare + day.scores.behaviour + day.scores.senses) / 5;

            // Average of (Main + Thinking + ABC)
            // Ensure values exist or default to 0
            const thinking = day.thinkingScore || 0;
            const abc = day.abcScore || 0;

            const dailyAvg = (mainAvg + thinking + abc) / 3;

            totalDailyScores += dailyAvg;
            daysCount++;
        }
    });

    if (daysCount === 0) return false;

    const teacherOverallAvg = totalDailyScores / daysCount;
    const parentScore = assessment.parentSelfCare?.calculatedScore || 0;

    // Final Average = (Teacher Avg + Parent Avg) / 2
    // If parent hasn't done it, we might want to just use teacher score, but prompt says "adds up parent and teacher". 
    // Assuming parent score is 0 if not done might penalize. Let's assume parent score is required or handled. 
    // For now, if parent score is 0, we heavily rely on teacher.

    let finalAverage = 0;
    if (parentScore > 0) {
        finalAverage = (teacherOverallAvg + parentScore) / 2;
    } else {
        finalAverage = teacherOverallAvg; // Fallback
    }

    let stage: 1 | 2 | 3 = 1;
    if (finalAverage >= 3.8) stage = 3;
    else if (finalAverage >= 2.4) stage = 2;
    else stage = 1;

    // Logic: Class is "Level X - Stage Y"
    const assignedClass = `${student.level} - Stage ${stage}`;

    await updateStudent(studentId, {
        assessment: { ...assessment, finalAverage, stage, isComplete: true },
        stage,
        assignedClass,
        studentStatus: 'ENROLLED' 
    });

    return assignedClass;
};

