    });

    useEffect(() => {
        const fetchStudent = async () => {
            if (id) {
                const s = await getStudentById(id);
                setStudent(s);
                loadDayData(s, selectedDay);
            }
            setLoading(false);
        };
        fetchStudent();
    }, [id]);

    const loadDayData = (s: Student | null, day: number) => {
        if (!s || !s.assessment || !s.assessment.teacherAssessments[day]) {
            // Reset form for new day
            setFormState({
                numbers: 0, reading: 0, selfCare: 0, behaviour: 0, senses: 0,
                thinkingResponse: '',
                abcLogs: []
            });
            return;
        }

        const data = s.assessment.teacherAssessments[day];
        // Reconstruct form state from saved data
        // Note: Logic to extract ABC logs from score isn't perfect if we only store score, 
        // but for simplicity in types we stored 'abcScore'. ideally we stored the logs. 
        // *Correction*: To fully support the prompt "record behavior", we should ideally store the logs.
        // For now, we will handle the numeric scores mainly, but let's assume we persisted the logs in the 'dayData' object in Firestore even if strictly typed as AssessmentDay.

        setFormState({
            numbers: data.scores.numbers,
            reading: data.scores.reading,
            selfCare: data.scores.selfCare,
            behaviour: data.scores.behaviour,
            senses: data.scores.senses,
            thinkingResponse: data.thinkingTask?.response || '',
            abcLogs: (data as any).abcLogs || [] // accessing dynamic prop if saved
        });
    };

    const handleDaySelect = (day: number) => {
        setSelectedDay(day);
        loadDayData(student, day);
    };

    const handleMainScoreChange = (field: string, val: string) => {
        const num = parseInt(val) || 0;
        setFormState(prev => ({ ...prev, [field]: Math.min(5, Math.max(0, num)) }));
    };

    const addAbcLog = (isPositive: boolean) => {
        const desc = prompt("Enter behaviour description:");
        if (desc) {
            setFormState(prev => ({
                ...prev,
                abcLogs: [...prev.abcLogs, { desc, isPositive }]
            }));
        }
    };

    const removeAbcLog = (idx: number) => {
        setFormState(prev => ({
            ...prev,
            abcLogs: prev.abcLogs.filter((_, i) => i !== idx)
        }));
    };

    const handleSaveDay = async () => {
        if (!student || !id) return;
        setSaving(true);

        // Calculate Scores
        // Thinking Score: Yes=5, Help=2.5, No=0
        let thinkingScore = 0;
        if (formState.thinkingResponse === 'Yes') thinkingScore = 5;
        else if (formState.thinkingResponse === 'Yes with help') thinkingScore = 2.5;

        // ABC Score: Average of logs (Positive=5, Negative=0)
        let abcScore = 0;
        if (formState.abcLogs.length > 0) {
            const totalAbc = formState.abcLogs.reduce((acc, log) => acc + (log.isPositive ? 5 : 0), 0);
            abcScore = parseFloat((totalAbc / formState.abcLogs.length).toFixed(2));
        } else {
             abcScore = 3; // Default neutral if no logs? Or 0? Let's use 3 (Fair) to not tank score if empty.
        }

        const dayData: AssessmentDay = {
            completed: true,
            date: new Date().toISOString(),
            scores: {
                numbers: formState.numbers,
                reading: formState.reading,
                selfCare: formState.selfCare,
                behaviour: formState.behaviour,
                senses: formState.senses
            },
            thinkingTask: {
                taskId: THINKING_TASKS[selectedDay - 1].id,
                description: THINKING_TASKS[selectedDay - 1].desc,
                response: formState.thinkingResponse as any
            },
            thinkingScore,
            abcScore
        };

        // Save extended data (logs) as well
        await saveTeacherAssessmentDay(id, selectedDay, { ...dayData, abcLogs: formState.abcLogs });

        // Refresh local state
        const updatedStudent = await getStudentById(id);
        setStudent(updatedStudent);
        setSaving(false);
    };

    if (loading || !student) return <Loader />;

    const isReadOnly = userRole === UserRole.ADMIN; // Admin is viewing progress

    return (
        <div className="pb-20">
            <div className="flex items-center gap-4 mb-6">
                <button onClick={() => navigate(-1)} className="p-2 bg-white border hover:bg-gray-50">
                    <ArrowLeft size={20} />
                </button>
                <div>
                    <h2 className="text-2xl font-bold text-coha-900">{student.name}</h2>
                    <p className="text-gray-600">14-Day Observation Assessment</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {/* Sidebar: Days Grid */}
                <div className="lg:col-span-1">
                    <div className="bg-white p-4 shadow-sm border border-gray-200 sticky top-24">
                        <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2"><Calendar size={18}/> Assessment Days</h3>
                        <div className="grid grid-cols-4 gap-2">
                            {Array.from({ length: 14 }, (_, i) => i + 1).map((day) => {
                                const isCompleted = student.assessment?.teacherAssessments?.[day]?.completed;
                                const isSelected = day === selectedDay;

                                // Logic: Can only select if previous day done or it's day 1 (Strict enforcement optional, but recommended)
                                // For now, allow flexible selection for teachers.
                                const isLocked = false; 

                                return (
                                    <button
                                        key={day}
                                        onClick={() => !isLocked && handleDaySelect(day)}
                                        disabled={isLocked}
                                        className={`aspect-square flex items-center justify-center font-bold text-sm border-2 transition-all rounded-lg
                                            ${isSelected ? 'border-coha-900 bg-coha-900 text-white scale-105 shadow-md' : 
                                              isCompleted ? 'border-green-500 bg-green-50 text-green-700' : 
                                              'border-gray-200 bg-gray-50 text-gray-400 hover:border-coha-300 hover:text-coha-500'}
                                        `}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>
                        <div className="mt-6 border-t pt-4">
                            <h4 className="text-xs font-bold uppercase text-gray-500 mb-2">Total Progress</h4>
                            {student.assessment?.finalAverage ? (
                                <div className="text-center bg-green-100 text-green-800 p-3 rounded font-bold">
                                    Assessment Complete<br/>
                                    Stage {student.assessment.stage}
                                </div>
                            ) : (
                                <p className="text-sm text-gray-500 italic">In Progress...</p>
                            )}
                        </div>
                    </div>
                </div>

                {/* Main Content: Forms */}
                <div className="lg:col-span-3 space-y-6">
                    <div className="flex items-center justify-between">
                         <h3 className="text-xl font-bold text-coha-900 flex items-center gap-2">
                             <span className="bg-coha-100 text-coha-900 w-8 h-8 flex items-center justify-center rounded-full text-sm">{selectedDay}</span>
                             Day {selectedDay} Assessment
                         </h3>
                         {student.assessment?.teacherAssessments?.[selectedDay]?.completed && (
                             <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1">
                                 <CheckCircle size={14} /> Completed
                             </span>
                         )}
                    </div>

                    {/* Form 1: Main Observation */}
                    <div className="bg-white p-6 shadow-sm border border-gray-200">
                        <h4 className="font-bold text-gray-800 mb-4 flex items-center gap-2 border-b pb-2">
                            <Activity className="text-coha-500" size={20}/> Daily Observation (Score 0-5)
                        </h4>
                        <div className="grid grid-cols-1 sm:grid-cols-5 gap-4">
                             {['Numbers', 'Reading', 'SelfCare', 'Behaviour', 'Senses'].map((field) => (
                                 <div key={field}>
                                     <label className="block text-xs font-bold uppercase text-gray-500 mb-1">{field}</label>
                                     <input 
                                        type="number" 
                                        min="0" max="5" 
                                        value={(formState as any)[field.charAt(0).toLowerCase() + field.slice(1)]}
                                        onChange={(e) => !isReadOnly && handleMainScoreChange(field.charAt(0).toLowerCase() + field.slice(1), e.target.value)}
                                        className="w-full p-2 border-2 border-gray-200 focus:border-coha-500 font-bold text-center text-lg rounded"
                                        disabled={isReadOnly}
                                     />
                                 </div>
                             ))}
                        </div>
                    </div>

                    {/* Form 2: Learn To Think */}
                    <div className="bg-white p-6 shadow-sm border border-gray-200">
                        <h4 className="font-bold text-gray-800 mb-4 flex items-center gap-2 border-b pb-2">
                            <Brain className="text-purple-500" size={20}/> Learn to Think (Task {THINKING_TASKS[selectedDay - 1].id})
                        </h4>
                        <div className="bg-purple-50 p-4 border-l-4 border-purple-500 mb-6">
                            <p className="font-medium text-purple-900">{THINKING_TASKS[selectedDay - 1].desc}</p>
                        </div>
                        <div className="flex gap-4">
                            {['Yes', 'Yes with help', 'No'].map(opt => (
                                <button
                                    key={opt}
                                    onClick={() => !isReadOnly && setFormState(prev => ({...prev, thinkingResponse: opt}))}
                                    className={`flex-1 py-3 border-2 font-bold transition-colors ${
                                        formState.thinkingResponse === opt 
                                        ? 'border-purple-600 bg-purple-600 text-white' 
                                        : 'border-gray-200 text-gray-500 hover:border-purple-300'
                                    }`}
                                    disabled={isReadOnly}
                                >
                                    {opt}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Form 3: ABC Behaviour */}
                    <div className="bg-white p-6 shadow-sm border border-gray-200">
                        <h4 className="font-bold text-gray-800 mb-4 flex items-center gap-2 border-b pb-2">
                            <ClipboardList className="text-orange-500" size={20}/> ABC Behaviour Log
                        </h4>

                        {!isReadOnly && (
                            <div className="flex gap-3 mb-6">
                                <Button variant="secondary" onClick={() => addAbcLog(true)} className="flex-1 bg-green-600 hover:bg-green-700 border-none text-white">
                                    <Plus size={16} /> Log Positive
                                </Button>
                                <Button variant="secondary" onClick={() => addAbcLog(false)} className="flex-1 bg-red-600 hover:bg-red-700 border-none text-white">
                                    <Plus size={16} /> Log Negative
                                </Button>
                            </div>
                        )}

                        <div className="space-y-2">
                            {formState.abcLogs.length === 0 && <p className="text-gray-400 italic text-sm text-center py-4">No behaviour logs for today.</p>}
                            {formState.abcLogs.map((log, idx) => (
                                <div key={idx} className={`flex items-center justify-between p-3 border-l-4 ${log.isPositive ? 'bg-green-50 border-green-500' : 'bg-red-50 border-red-500'}`}>
                                    <div>
                                        <span className={`text-xs font-bold uppercase ${log.isPositive ? 'text-green-700' : 'text-red-700'}`}>
                                            {log.isPositive ? 'Positive (+1)' : 'Negative (0)'}
                                        </span>
                                        <p className="text-gray-800 font-medium">{log.desc}</p>
                                    </div>
                                    {!isReadOnly && (
                                        <button onClick={() => removeAbcLog(idx)} className="text-gray-400 hover:text-red-500">
                                            <Trash2 size={16} />
                                        </button>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Action */}
                    {!isReadOnly && (
                        <div className="flex justify-end pt-4">
                            <Button onClick={handleSaveDay} disabled={saving} className="w-full md:w-auto px-8 py-4 text-lg">
                                {saving ? 'Saving...' : `Complete Day ${selectedDay}`}
                            </Button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../../components/ui/Button';
import { getStudents, getSystemSettings, getStudentsByStatus, calculateFinalStage } from '../../services/dataService';
import { Student, SystemSettings, Division } from '../../types';
import { Plus, Search, Eye, Download, CheckSquare, Activity } from 'lucide-react';
import { Toast } from '../../components/ui/Toast';
import { printStudentList } from '../../utils/printStudentList';

export const StudentsPage: React.FC = () => {
  const [viewMode, setViewMode] = useState<'ENROLLED' | 'ASSESSMENT'>('ENROLLED');
  const [students, setStudents] = useState<Student[]>([]);
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [settings, setSettings] = useState<SystemSettings | null>(null);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({show: false, msg: ''});

  const fetchStudents = async () => {
    setLoading(true);
    let data: Student[] = [];
    if (viewMode === 'ENROLLED') {
         // Get both strictly enrolled and legacy/manual adds (which might not have studentStatus set yet)
         const all = await getStudents();
         data = all.filter(s => s.studentStatus === 'ENROLLED' || !s.studentStatus);
    } else {
         data = await getStudentsByStatus('ASSESSMENT');
    }
    setStudents(data);
    const settingsData = await getSystemSettings();
    setSettings(settingsData);
    setLoading(false);
  };

  useEffect(() => {
    fetchStudents();
  }, [viewMode]);

  const handleFinalizeAssessment = async (studentId: string) => {
      // This is for Admin override or check
      if(window.confirm('Calculate final stage and enroll student?')) {
          setLoading(true);
          const result = await calculateFinalStage(studentId);
          setLoading(false);
          if (result) {
              setToast({show: true, msg: `Student enrolled in ${result}`});
              fetchStudents();
          } else {
              setToast({show: true, msg: 'Could not calculate. Ensure assessments are present.'});
          }
      }
  };

  const filteredStudents = students.filter(student => 
    student.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (student.parentName && student.parentName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div>
      <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({show:false, msg:''})} variant="success" />

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-coha-900">Students</h2>
          <p className="text-gray-600">Manage enrollment and student records.</p>
        </div>
        {viewMode === 'ENROLLED' && (
             <Button variant="outline" onClick={() => printStudentList(filteredStudents, settings)}>
                <Download size={20} /> Download List
            </Button>
        )}
      </div>

      <div className="flex border-b border-gray-200 mb-6 bg-white shadow-sm">
         <button onClick={() => setViewMode('ENROLLED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${viewMode === 'ENROLLED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Registered Students</button>
         <button onClick={() => setViewMode('ASSESSMENT')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${viewMode === 'ASSESSMENT' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Observation Period</button>
      </div>

      <div className="bg-white border border-gray-200 shadow-sm">
        <div className="p-4 border-b border-gray-200 flex gap-2">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-3 text-gray-400" size={20} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-300 focus:border-coha-500 outline-none rounded-none"
              placeholder="Search students..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold">
              <tr>
                <th className="px-6 py-4">ID</th>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4">Division</th>
                <th className="px-6 py-4">Class/Level</th>
                <th className="px-6 py-4">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 font-mono text-xs">{student.id}</td>
                  <td className="px-6 py-4 font-bold text-coha-900">{student.name}</td>
                  <td className="px-6 py-4">
                     <span className={`px-2 py-1 text-xs font-bold uppercase rounded ${student.division === Division.SPECIAL_NEEDS ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 text-gray-800'}`}>
                         {student.division || 'Mainstream'}
                     </span>
                  </td>
                  <td className="px-6 py-4 font-medium">
                      {student.assignedClass || student.grade || student.level}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex gap-2">
                        {viewMode === 'ASSESSMENT' ? (
                            <>
                                <Button onClick={() => navigate(`/admin/assessment/${student.id}`)} variant="outline" className="py-1 px-3 text-xs border-coha-500 text-coha-900">
                                    <Eye size={14} /> View Details
                                </Button>
                                <Button onClick={() => handleFinalizeAssessment(student.id)} className="py-1 px-3 text-xs">
                                    <Activity size={14} /> Finalize
                                </Button>
                            </>
                        ) : (
                            <button 
                            onClick={() => navigate(`/admin/students/${student.id}`)}
                            className="text-coha-500 hover:text-coha-700 font-bold text-sm flex items-center gap-1"
                            >
                            <Eye size={16} /> View Profile
                            </button>
                        )}
                    </div>
                  </td>
                </tr>
              ))}
               {filteredStudents.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-gray-500">No students found.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React from 'react';

export enum UserRole {
  ADMIN = 'ADMIN',
  TEACHER = 'TEACHER',
  PARENT = 'PARENT'
}

export enum Division {
  MAINSTREAM = 'Mainstream',
  SPECIAL_NEEDS = 'Special Needs'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  pin: string;
}

export interface Teacher extends User {
  subject?: string;
  email?: string;
  assignedClass?: string;
}

export interface MenuItem {
  label: string;
  path: string;
  icon: React.ReactNode;
}

export interface FeeItem {
  id: string;
  category: string;
  amount: string; 
  frequency: string;
  notes?: string;
}

export interface SupplyItem {
  id: string;
  name: string;
  isRequired: boolean;
}

export interface SystemSettings {
  id?: string;
  adminName: string;
  adminPin: string;

  fees: FeeItem[];
  uniforms: SupplyItem[];
  stationery: SupplyItem[];
  grades: string[];
  specialNeedsLevels: string[];

