                                                    <span className="text-xs font-bold text-gray-500 bg-white border border-gray-200 px-2 py-0.5 rounded">{log.time}</span>
                                                    <span className={`text-xs font-bold uppercase ${log.isPositive ? 'text-green-700' : 'text-red-700'}`}>
                                                        {log.isPositive ? 'Positive Behaviour' : 'Negative Behaviour'}
                                                    </span>
                                                </div>
                                                {!isReadOnly && (
                                                    <button onClick={() => removeAbcLog(log.id)} className="text-gray-400 hover:text-red-500">
                                                        <Trash2 size={16} />
                                                    </button>
                                                )}
                                            </div>
                                            <div className="grid grid-cols-1 md:grid-cols-3 divide-y md:divide-y-0 md:divide-x divide-gray-100 text-sm">
                                                <div className="p-3">
                                                    <span className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Antecedent</span>
                                                    <p className="text-gray-800">{log.antecedent}</p>
                                                </div>
                                                <div className="p-3 bg-gray-50">
                                                    <span className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Behaviour</span>
                                                    <p className="font-medium text-gray-900">{log.behaviour}</p>
                                                </div>
                                                <div className="p-3">
                                                    <span className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Consequence</span>
                                                    <p className="text-gray-800">{log.consequence}</p>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Action */}
                            {!isReadOnly && (
                                <div className="flex justify-end pt-4">
                                    <Button onClick={handleSaveDay} disabled={saving} className="w-full md:w-auto px-8 py-4 text-lg">
                                        {saving ? 'Saving...' : `Complete Day ${selectedDay}`}
                                    </Button>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { NavLink } from 'react-router-dom';
import { LayoutDashboard, Users, GraduationCap, LogOut, X, FileText, Settings, Activity } from 'lucide-react';
import { UserRole } from '../types';
import { getPendingActionCounts } from '../services/dataService';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  role: UserRole;
  onLogout: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, role, onLogout }) => {
  const [badgeCount, setBadgeCount] = useState(0);

  useEffect(() => {
    // Only fetch counts if Admin
    if (role === UserRole.ADMIN) {
      const fetchCounts = async () => {
        const counts = await getPendingActionCounts();
        setBadgeCount(counts.total);
      };
      fetchCounts();

      // Optional: Refresh counts every minute
      const interval = setInterval(fetchCounts, 60000);
      return () => clearInterval(interval);
    }
  }, [role]);

  const adminLinks = [
    { label: 'Dashboard', path: '/admin/dashboard', icon: <LayoutDashboard size={20} /> },
    { label: 'Applications', path: '/admin/applications', icon: <FileText size={20} />, badge: badgeCount },
    { label: 'Teachers', path: '/admin/teachers', icon: <Users size={20} /> },
    { label: 'Students', path: '/admin/students', icon: <GraduationCap size={20} /> },
    { label: 'Settings', path: '/admin/settings', icon: <Settings size={20} /> },
  ];

  const teacherLinks = [
    { label: 'Dashboard', path: '/teacher/dashboard', icon: <LayoutDashboard size={20} /> },
    { label: 'My Classes', path: '/teacher/classes', icon: <GraduationCap size={20} /> },
  ];

  const parentLinks = [
    { label: 'Student Info', path: '/parent/dashboard', icon: <Users size={20} /> },
    { label: 'Assessment Progress', path: '/parent/assessment', icon: <Activity size={20} /> },
  ];

  let links = parentLinks;
  if (role === UserRole.ADMIN) links = adminLinks;
  if (role === UserRole.TEACHER) links = teacherLinks;

  const sidebarClasses = `fixed inset-y-0 left-0 z-50 w-72 bg-coha-900 text-white transform transition-transform duration-300 ease-in-out flex flex-col h-full ${
    isOpen ? 'translate-x-0' : '-translate-x-full'
  } lg:translate-x-0 lg:static shadow-xl`;

  return (
    <>
      {/* Mobile Overlay */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden"
          onClick={onClose}
        />
      )}

      <div className={sidebarClasses}>
        <div className="flex flex-col items-center justify-center p-6 border-b border-coha-800 shrink-0 text-center relative">
            <button onClick={onClose} className="lg:hidden text-white absolute top-4 right-4">
                <X size={24} />
            </button>
            <div className="bg-white p-2 rounded-full mb-3">
                <img 
                    src="https://i.ibb.co/LzYXwYfX/logo.png" 
                    alt="COHA Logo" 
                    className="w-12 h-12 object-contain"
                />
            </div>
            <h1 className="text-lg font-bold tracking-tight leading-tight">Circle of Hope Academy</h1>
            <p className="text-[10px] uppercase tracking-widest text-coha-300 font-bold mt-1">Accessible Education for All</p>
        </div>

        <nav className="mt-4 px-4 flex-1 overflow-y-auto">
          <ul className="space-y-2">
            {links.map((link) => (
              <li key={link.path}>
                <NavLink
                  to={link.path}
                  onClick={() => window.innerWidth < 1024 && onClose()}
                  className={({ isActive }) =>
                    `flex items-center justify-between px-4 py-3 transition-colors ${
                      isActive 
                        ? 'bg-coha-500 text-white font-semibold border-l-4 border-white' 
                        : 'text-gray-300 hover:bg-coha-800 hover:text-white'
                    }`
                  }
                >
                  <div className="flex items-center gap-3">
                    {link.icon}
                    <span>{link.label}</span>
                  </div>
                  {/* Badge */}
                  {(link as any).badge > 0 && (
                     <span className="bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">
                        {(link as any).badge}
                     </span>
                  )}
                </NavLink>
              </li>
            ))}
          </ul>
        </nav>

        <div className="w-full p-4 border-t border-coha-800 shrink-0">
          <button 
            onClick={onLogout}
            className="flex items-center gap-3 px-4 py-3 text-red-300 hover:text-white hover:bg-coha-800 w-full transition-colors"
          >
            <LogOut size={20} />
            <span>Logout</span>
          </button>
        </div>
      </div>
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Sidebar } from './components/Sidebar';
import { Header } from './components/Header';
import { LandingPage } from './pages/LandingPage';
import { LoginPage } from './pages/LoginPage';
import { ApplyPage } from './pages/ApplyPage';
import { AdminDashboard } from './pages/admin/Dashboard';
import { TeachersPage } from './pages/admin/Teachers';
import { StudentsPage } from './pages/admin/Students';
import { StudentDetailsPage } from './pages/admin/StudentDetails';
import { ApplicationsPage } from './pages/admin/Applications';
import { ApplicationDetailsPage } from './pages/admin/ApplicationDetails';
import { SettingsPage } from './pages/admin/Settings';
import { ParentDashboard } from './pages/parent/Dashboard';
import { ParentAssessmentProgress } from './pages/parent/AssessmentProgress';
import { TeacherDashboard } from './pages/teacher/Dashboard';
import { AssessmentPage } from './pages/teacher/AssessmentPage';
import { UserRole } from './types';
import { seedAdminUser, getAdminProfile } from './services/dataService';
import { Toast } from './components/ui/Toast';

// Layout Component to wrap protected routes
const AppLayout: React.FC<{ 
  children: React.ReactNode; 
  role: UserRole; 
  user: any; 
  onLogout: () => void 
}> = ({ children, role, user, onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);

  return (
    <div className="h-screen bg-gray-50 flex font-sans overflow-hidden">
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)} 
        role={role}
        onLogout={onLogout}
      />
      <div className="flex-1 flex flex-col min-w-0 h-full relative">
        <Header 
          onMenuClick={() => setSidebarOpen(!sidebarOpen)} 
          role={role}
          userName={user?.name}
        />
        <main className="flex-1 p-4 lg:p-8 overflow-y-auto">
          {children}
        </main>
      </div>
    </div>
  );
};

const ProtectedRoute: React.FC<{
  isAuthenticated: boolean;
  userRole: UserRole | null;
  allowedRoles: UserRole[];
  children: React.ReactNode;
}> = ({ isAuthenticated, userRole, allowedRoles, children }) => {
  if (!isAuthenticated) return <Navigate to="/login" replace />;
  if (userRole && !allowedRoles.includes(userRole)) return <Navigate to="/" replace />;
  return <>{children}</>;
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [role, setRole] = useState<UserRole | null>(null);

  // Toast State
  const [toastMessage, setToastMessage] = useState('');
  const [toastVisible, setToastVisible] = useState(false);

  useEffect(() => {
    // Seed admin on app load
    seedAdminUser();

    // Check if admin is currently active to refresh profile name
    if (user && role === UserRole.ADMIN) {
        getAdminProfile().then(profile => {
            setUser((prev: any) => ({...prev, name: profile.name}));
        });
    }
  }, []);

  const handleLogin = (newRole: UserRole, newUser: any) => {
    setUser(newUser);
    setRole(newRole);
  };

  const handleLogout = () => {
    setUser(null);
    setRole(null);
  };

  const showToast = (message: string) => {
    setToastMessage(message);
    setToastVisible(true);
  };

  return (
    <>
      <Toast 
        message={toastMessage} 
        isVisible={toastVisible} 
        onClose={() => setToastVisible(false)} 
      />
      <HashRouter>
        <Routes>
          <Route path="/" element={<LandingPage />} />
          <Route path="/apply" element={<ApplyPage />} />
          <Route path="/login" element={<LoginPage onLogin={handleLogin} showToast={showToast} />} />

          {/* Admin Routes */}
          <Route path="/admin/*" element={
            <ProtectedRoute isAuthenticated={!!user} userRole={role} allowedRoles={[UserRole.ADMIN]}>
              <AppLayout role={UserRole.ADMIN} user={user} onLogout={handleLogout}>
                <Routes>
                  <Route path="dashboard" element={<AdminDashboard />} />
                  <Route path="applications" element={<ApplicationsPage />} />
                  <Route path="applications/:id" element={<ApplicationDetailsPage />} />
                  <Route path="teachers" element={<TeachersPage />} />
                  <Route path="students" element={<StudentsPage />} />
                  <Route path="students/:id" element={<StudentDetailsPage />} />
                  <Route path="assessment/:id" element={<AssessmentPage userRole={UserRole.ADMIN} />} />
                  <Route path="settings" element={<SettingsPage />} />
                  <Route path="*" element={<Navigate to="dashboard" />} />
                </Routes>
              </AppLayout>
