// --- ASSESSMENT LOGIC ---

/**
 * Calculates a normalized 0.0 - 5.0 score for a single day based on 7 data points:
 * 5 core areas, 1 thinking task score, 1 ABC behaviour average.
 */
const getNormalizedDailyScore = (dayData: AssessmentDay): number => {
    if (!dayData.scores) return 0;
    const s = dayData.scores;

    // Core areas (5)
    const cores = [
        Number(s.numbers) || 0,
        Number(s.reading) || 0,
        Number(s.selfCare) || 0,
        Number(s.behaviour) || 0,
        Number(s.senses) || 0
    ];

    // Thinking Task (1)
    const thinking = Number(dayData.thinkingScore) || 0;

    // ABC behaviour (1)
    const abc = Number(dayData.abcScore) || 3; // Default 3 if no logs

    const totalSum = cores.reduce((a, b) => a + b, 0) + thinking + abc;
    return parseFloat((totalSum / 7).toFixed(2));
};

export const calculateDayPercentage = (day: any) => {
    if (!day) return 0;
    // Use stored dailyTotalScore if available, else calc dynamically
    const score = Number(day.dailyTotalScore) || getNormalizedDailyScore(day);
    return Math.round((score / 5) * 100);
};

export const saveParentAssessment = async (studentId: string, assessmentData: Omit<SelfCareAssessment, 'calculatedScore' | 'completedDate'>) => {
    const student = await getStudentById(studentId);
    if (!student || !student.assessment) return false;

    let totalScore = 0;
    const items = ['s1', 's2', 's3', 's4', 's5', 's6', 's7', 's8', 's9'] as const;

    items.forEach(key => {
        const val = assessmentData[key];
        if (val === 'Yes') totalScore += 1;
        else if (val === 'Yes with help') totalScore += 0.5;
    });

    const calculatedScore = parseFloat(((totalScore / 9) * 5).toFixed(2));

    const finalAssessment: SelfCareAssessment = {
        ...assessmentData,
        completedDate: new Date().toISOString(),
        calculatedScore
    };

    const updatedAssessment = {
        ...student.assessment,
        parentSelfCare: finalAssessment,
        parentSelfCareScore: calculatedScore, 
        parentAssessmentDate: finalAssessment.completedDate
    };

    await updateStudent(studentId, { assessment: updatedAssessment });

    return true;
};

export const saveTeacherAssessmentDay = async (studentId: string, day: number, dayData: any) => {
    const student = await getStudentById(studentId);
    if (!student || !student.assessment) return false;

    // Calculate persistent daily score based on all tasks
    const dailyTotalScore = getNormalizedDailyScore(dayData);

    const updatedAssessment = {
        ...student.assessment,
        teacherAssessments: {
            ...student.assessment.teacherAssessments,
            [day]: {
                ...dayData,
                dailyTotalScore, // Update document field as requested
                completed: true,
                date: new Date().toISOString()
            }
        }
    };

    await updateStudent(studentId, { assessment: updatedAssessment });
    return true;
};

export const calculateFinalStage = async (studentId: string) => {
    try {
        const student = await getStudentById(studentId);
        if (!student || !student.assessment) return false;

        const assessment = student.assessment;
        let daysCount = 0;
        let teacherTotalAccumulated = 0;

        // Use normalized daily scores from all recorded days
        Object.values(assessment.teacherAssessments).forEach((day: any) => {
            if (day.completed) {
                const score = day.dailyTotalScore !== undefined 
                    ? Number(day.dailyTotalScore) 
                    : getNormalizedDailyScore(day);

                teacherTotalAccumulated += score;
                daysCount++;
            }
        });

        if (daysCount === 0) return false;

        const teacherOverallAvg = teacherTotalAccumulated / daysCount;
        const parentScore = Number(assessment.parentSelfCare?.calculatedScore) || 0;

        // Final Enrollment Aggregation: mixes parent and teacher scores (teacher counts for 60%, parent 40%)
        let finalAverage = (teacherOverallAvg * 0.6) + (parentScore * 0.4);
        if (isNaN(finalAverage)) finalAverage = 0;

        /**
         * Stage Logic:
         * 1.0 – 2.3 -> 1 (Needs help)
         * 2.4 – 3.7 -> 2 (Doing okay)
         * 3.8 – 5.0 -> 3 (Doing very well)
         */
        let stage: 1 | 2 | 3 = 1;
        if (finalAverage >= 3.8) stage = 3;
        else if (finalAverage >= 2.4) stage = 2;
        else stage = 1;

        // Class Naming: "Grade/Level - Stage X"
        const baseName = student.level || student.grade || 'Special Needs';
        const assignedClass = `${baseName} - Stage ${stage}`;

        await updateStudent(studentId, {
            assessment: { ...assessment, finalAverage, stage, isComplete: true },
            stage: stage,
            assignedClass: assignedClass,
            studentStatus: 'ENROLLED' 
        });

        return assignedClass;
    } catch (e) {
        console.error("Error in calculateFinalStage", e);
        return false;
    }
};

