// --- ASSESSMENT LOGIC ---

/**
 * Calculates a normalized 0.0 - 5.0 score for a single day based on 7 data points.
 * Every input counts equally in the daily average.
 */
const getNormalizedDailyScore = (dayData: any): number => {
    if (!dayData || !dayData.scores) return 0;
    const s = dayData.scores;

    // 5 Cores + 1 Thinking Task + 1 ABC Log Score = 7 inputs
    const inputs = [
        Number(s.numbers) || 0,
        Number(s.reading) || 0,
        Number(s.selfCare) || 0,
        Number(s.behaviour) || 0,
        Number(s.senses) || 0,
        Number(dayData.thinkingScore) || 0,
        Number(dayData.abcScore) || 3 // Use ABC score field, default neutral
    ];

    const sum = inputs.reduce((a, b) => a + b, 0);
    return parseFloat((sum / inputs.length).toFixed(2));
};

export const calculateDayPercentage = (day: any) => {
    if (!day) return 0;
    // Attempt to use the field if it exists, otherwise calculate it
    const score = (day.dailyTotalScore !== undefined) ? Number(day.dailyTotalScore) : getNormalizedDailyScore(day);
    return Math.round((score / 5) * 100);
};

export const saveParentAssessment = async (studentId: string, assessmentData: Omit<SelfCareAssessment, 'calculatedScore' | 'completedDate'>) => {
    const student = await getStudentById(studentId);
    if (!student || !student.assessment) return false;

    let totalScore = 0;
    const items = ['s1', 's2', 's3', 's4', 's5', 's6', 's7', 's8', 's9'] as const;

    items.forEach(key => {
        const val = assessmentData[key];
        if (val === 'Yes') totalScore += 1;
        else if (val === 'Yes with help') totalScore += 0.5;
    });

    const calculatedScore = parseFloat(((totalScore / 9) * 5).toFixed(2));

    const finalAssessment: SelfCareAssessment = {
        ...assessmentData,
        completedDate: new Date().toISOString(),
        calculatedScore
    };

    const updatedAssessment = {
        ...student.assessment,
        parentSelfCare: finalAssessment,
        parentSelfCareScore: calculatedScore, 
        parentAssessmentDate: finalAssessment.completedDate
    };

    await updateStudent(studentId, { assessment: updatedAssessment });

    return true;
};

export const saveTeacherAssessmentDay = async (studentId: string, day: number, dayData: any) => {
    try {
        const student = await getStudentById(studentId);
        if (!student || !student.assessment) return false;

        // Force a persistent field update in the teacherAssessments object
        const dailyTotalScore = getNormalizedDailyScore(dayData);

        const updatedAssessment = {
            ...student.assessment,
            teacherAssessments: {
                ...student.assessment.teacherAssessments,
                [day]: {
                    ...dayData,
                    dailyTotalScore: dailyTotalScore, // Explicit field creation
                    completed: true,
                    date: new Date().toISOString()
                }
            }
        };

        await updateStudent(studentId, { assessment: updatedAssessment });
        return true;
    } catch (err) {
        console.error("Save Day failed", err);
        return false;
    }
};

/**
 * Mixes Teacher Observation (60%) and Parent Self-Care (40%)
 * and maps the result to Stage 1, 2, or 3.
 */
export const calculateFinalStage = async (studentId: string): Promise<{ success: boolean; assignedClass?: string; error?: string }> => {
    try {
        const student = await getStudentById(studentId);
        if (!student || !student.assessment) {
            return { success: false, error: "Student or assessment data not found." };
        }

        const assessment = student.assessment;
        let daysCount = 0;
        let teacherAggregatePoints = 0;

        // Sum up all daily averages (1-14)
        Object.values(assessment.teacherAssessments).forEach((day: any) => {
            if (day.completed) {
                // Retroactively calculate if field is missing for some reason
                const score = (day.dailyTotalScore !== undefined) ? Number(day.dailyTotalScore) : getNormalizedDailyScore(day);
                teacherAggregatePoints += score;
                daysCount++;
            }
        });

        if (daysCount === 0) {
            return { success: false, error: "No teacher assessment days have been completed yet." };
        }

        const teacherAvg = teacherAggregatePoints / daysCount;
        const parentScore = Number(assessment.parentSelfCare?.calculatedScore) || 0;

        if (parentScore === 0 && !assessment.parentSelfCare) {
            return { success: false, error: "Parent report is missing. Please ensure the parent submits their self-care assessment first." };
        }

        // Weighted Mix: Teacher (60%), Parent (40%)
        let finalAverage = (teacherAvg * 0.6) + (parentScore * 0.4);
        if (isNaN(finalAverage)) finalAverage = 0;

        /**
         * Stage Logic per Requirement:
         * 1.0 – 2.3 -> Stage 1 (Needs most help)
         * 2.4 – 3.7 -> Stage 2 (Doing okay)
         * 3.8 – 5.0 -> Stage 3 (Highest level)
         */
        let stage: 1 | 2 | 3 = 1;
        if (finalAverage >= 3.8) stage = 3;
        else if (finalAverage >= 2.4) stage = 2;
        else stage = 1;

        // Automated Group Format: "Level X - Stage Y" (e.g. "Level 1A - Stage 2")
        const baseLevel = student.level || student.grade || 'Special Needs';
        const assignedClass = `${baseLevel} - Stage ${stage}`;

        await updateStudent(studentId, {
            assessment: { ...assessment, finalAverage, stage, isComplete: true },
            stage: stage,
            assignedClass: assignedClass,
            studentStatus: 'ENROLLED' 
        });

        return { success: true, assignedClass };
    } catch (e: any) {
        console.error("Aggregation failed", e);
        return { success: false, error: e.message || "An unknown system error occurred during finalization." };
    }
};

