                                                    <div className="bg-white/40 p-3 shadow-inner">
                                                        <span className="block text-[9px] font-black text-gray-500 uppercase tracking-widest mb-2 opacity-60">Behaviour (B)</span>
                                                        <p className="font-black text-sm leading-relaxed">{log.behaviour}</p>
                                                    </div>
