                                                    <button onClick={() => removeAbcLog(log.id)} className="mt-6 text-red-600 font-black uppercase text-[9px] tracking-widest hover:underline flex items-center gap-2 border-2 border-red-100 px-3 py-1 hover:bg-white transition-all">
                                                        <Trash2 size={12}/> Purge Log
