    { label: '2 - Emerging', value: '2' },
    { label: '3 - Satisfactory', value: '3' },
    { label: '4 - Good', value: '4' },
    { label: '5 - Excellent', value: '5' },
];

interface AssessmentPageProps {
    userRole: UserRole;
    user?: any;
}

export const AssessmentPage: React.FC<AssessmentPageProps> = ({ userRole, user }) => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [student, setStudent] = useState<Student | null>(null);
    const [selectedDay, setSelectedDay] = useState<number>(1);
    const [viewMode, setViewMode] = useState<'DAILY' | 'PARENT'>('DAILY');
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [finalizing, setFinalizing] = useState(false);
    const [toast, setToast] = useState({ show: false, msg: '', type: 'success' as 'success' | 'error' });

    const [transferModalOpen, setTransferModalOpen] = useState(false);
    const [transferClass, setTransferClass] = useState('');

    const [formState, setFormState] = useState({
        numbers: 0,
        reading: 0,
        selfCare: 0,
        behaviour: 0,
        senses: 0,
        thinkingResponse: '', 
        abcLogs: [] as ABCLog[]
    });

    const [isAbcModalOpen, setIsAbcModalOpen] = useState(false);
    const [newAbc, setNewAbc] = useState<Partial<ABCLog>>({
        antecedent: '',
        behaviour: '',
        consequence: '',
        isPositive: false
    });

    useEffect(() => {
        const fetchStudent = async () => {
            if (id) {
                const s = await getStudentById(id);
                setStudent(s);
                loadDayData(s, selectedDay);
            }
            setLoading(false);
        };
        fetchStudent();
    }, [id]);

    const loadDayData = (s: Student | null, day: number) => {
        if (!s || !s.assessment || !s.assessment.teacherAssessments[day]) {
            setFormState({
                numbers: 0, reading: 0, selfCare: 0, behaviour: 0, senses: 0,
                thinkingResponse: '',
                abcLogs: []
            });
            return;
        }

        const data = s.assessment.teacherAssessments[day];
        setFormState({
            numbers: data.scores.numbers,
            reading: data.scores.reading,
            selfCare: data.scores.selfCare,
            behaviour: data.scores.behaviour,
            senses: data.scores.senses,
            thinkingResponse: data.thinkingTask?.response || '',
            abcLogs: data.abcLogs || [] 
        });
    };

    const handleDaySelect = (day: number) => {
        setSelectedDay(day);
        setViewMode('DAILY');
        loadDayData(student, day);
    };

    const handleMainScoreChange = (field: string, val: string) => {
        const num = parseInt(val) || 0;
        setFormState(prev => ({ ...prev, [field]: num }));
    };

    const handleAddAbcLog = () => {
        if (!newAbc.behaviour) return; 

        const log: ABCLog = {
            id: uuidv4(),
            antecedent: newAbc.antecedent || 'N/A',
            behaviour: newAbc.behaviour || '',
            consequence: newAbc.consequence || 'N/A',
            isPositive: newAbc.isPositive || false,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setFormState(prev => ({
            ...prev,
            abcLogs: [...prev.abcLogs, log]
        }));

        setNewAbc({ antecedent: '', behaviour: '', consequence: '', isPositive: false });
        setIsAbcModalOpen(false);
    };

    const removeAbcLog = (logId: string) => {
        setFormState(prev => ({
            ...prev,
            abcLogs: prev.abcLogs.filter(log => log.id !== logId)
        }));
    };

    const handleSaveDay = async () => {
        if (!student || !id) return;
        console.log(`[Save Day] Starting persistent save for Day ${selectedDay}...`);
        setSaving(true);

        let thinkingScore = 0;
        if (formState.thinkingResponse === 'Yes') thinkingScore = 5;
        else if (formState.thinkingResponse === 'Yes with help') thinkingScore = 2.5;

        let abcScore = 0;
        if (formState.abcLogs.length > 0) {
            const totalAbc = formState.abcLogs.reduce((acc, log) => acc + (log.isPositive ? 5 : 0), 0);
            abcScore = parseFloat((totalAbc / formState.abcLogs.length).toFixed(2));
        } else {
             abcScore = 3; 
        }

        const dayData: AssessmentDay = {
            completed: true,
            date: new Date().toISOString(),
            scores: {
                numbers: formState.numbers,
                reading: formState.reading,
                selfCare: formState.selfCare,
                behaviour: formState.behaviour,
                senses: formState.senses
            },
            thinkingTask: {
                taskId: THINKING_TASKS[selectedDay - 1].id,
                description: THINKING_TASKS[selectedDay - 1].desc,
                response: formState.thinkingResponse as any
            },
            thinkingScore,
            abcScore,
            abcLogs: formState.abcLogs
        };

        console.log(`[Save Day] Calculated Daily Score field for persistence.`);
        const success = await saveTeacherAssessmentDay(id, selectedDay, dayData);

        if (success) {
            console.log(`[Save Day] Transaction successful.`);
            const updatedStudent = await getStudentById(id);
            setStudent(updatedStudent);
            setToast({ show: true, msg: `Day ${selectedDay} saved with updated total score.`, type: 'success' });
        } else {
            console.error(`[Save Day] FAILED to write to Firestore.`);
            setToast({ show: true, msg: "Failed to save daily assessment. Please check your connection.", type: 'error' });
        }
        setSaving(false);
    };

    const handleFinalize = async () => {
        // ABSOLUTE ENTRY POINT LOG
        console.log("[Finalize Button Clicked]");

        if (!student || !id) {
            console.error("Missing Student context for finalization");
            return;
        }

        if (window.confirm("Finalize enrollment? This will calculate the 60/40 weighted average and place the student in their Stage class.")) {
            console.log("[Finalize Stage 1/6] Aggregation Initializing...");
            setFinalizing(true);

            try {
                console.log("[Finalize Stage 2/6] Running backend aggregation engine...");
                const result = await calculateFinalStage(id);

                if (result.success && result.assignedClass) {
                    console.log(`[Finalize Stage 3/6] Success: ${result.assignedClass}`);

                    console.log("[Finalize Stage 4/6] Re-fetching fresh student state...");
                    const updatedStudent = await getStudentById(id);
                    setStudent(updatedStudent);

                    console.log("[Finalize Stage 5/6] Checking class transfer requirements...");
                    if (user && user.assignedClass && result.assignedClass !== user.assignedClass && userRole === UserRole.TEACHER) {
                        console.log("[Finalize Stage 6/6] Transfer UI Triggered.");
                        setTransferClass(result.assignedClass);
                        setTransferModalOpen(true);
                    } else {
                        console.log("[Finalize Stage 6/6] Complete. Enrollment Locked.");
                        setToast({ show: true, msg: `Assessment Finalized! Student enrolled in ${result.assignedClass}`, type: 'success' });
                    }
                } else {
                    // SHOW ACTUAL ERROR HAPPENING
                    console.error("[Finalize Engine Error]:", result.error);
                    setToast({ show: true, msg: result.error || "Aggregation failed. Check all 14 days and Parent Report.", type: 'error' });
                }
            } catch (e: any) {
                console.error("[Finalize System Crash]:", e);
                setToast({ show: true, msg: `System error: ${e.message || 'Unknown server error'}`, type: 'error' });
            } finally {
                setFinalizing(false);
            }
        } else {
            console.log("[Finalize Canceled by User]");
        }
    };

    if (loading || !student) return <Loader />;

    const isReadOnly = userRole === UserRole.ADMIN || student.assessment?.isComplete;
    const completedDaysCount = student.assessment?.teacherAssessments ? Object.values(student.assessment.teacherAssessments).filter((d:any) => d.completed).length : 0;
    const isReadyToFinalize = completedDaysCount === 14;
    const isCompleted = student.assessment?.isComplete;

    return (
        <div className="pb-20 relative font-sans text-black">
            <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({...toast, show: false})} variant={toast.type} />

            {transferModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4 animate-fade-in">
                    <div className="bg-white w-full max-w-md shadow-2xl border-t-8 border-orange-500 rounded-none overflow-hidden">
                        <div className="p-8 text-center text-black font-sans">
                            <div className="w-16 h-16 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-4 text-orange-600">
                                <ArrowRight size={32} />
                            </div>
                            <h3 className="text-xl font-bold mb-2">Student Transfer Required</h3>
                            <p className="text-gray-800 mb-4 font-medium">
                                Based on assessment results, {student.name} has been assigned to:
                            </p>
                            <div className="bg-orange-50 border border-orange-200 text-orange-900 font-bold text-lg py-2 px-4 rounded-none mb-6 inline-block">
                                {transferClass}
                            </div>
                            <p className="text-xs text-gray-700 mb-6 font-bold uppercase">
                                The student will now appear in the new class group register.
                            </p>
                            <Button fullWidth onClick={() => { setTransferModalOpen(false); navigate('/teacher/dashboard'); }}>
                                Return to Dashboard
                            </Button>
                        </div>
                    </div>
                </div>
            )}

            {isAbcModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
                    <div className="bg-white w-full max-w-lg shadow-2xl border-t-8 border-coha-900 animate-fade-in rounded-none">
                         <div className="flex justify-between items-center p-6 border-b border-gray-100">
                            <h3 className="text-xl font-bold text-coha-900 flex items-center gap-2">
                                <ClipboardList size={24}/> Add Behaviour Entry
                            </h3>
                            <button onClick={() => setIsAbcModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                                <X size={24} />
                            </button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-bold text-gray-900 mb-1">Antecedent (A)</label>
                                <textarea 
                                    className="w-full p-3 border-2 border-gray-300 outline-none rounded-none bg-gray-50 h-20 text-sm focus:border-coha-500 text-black placeholder-gray-500" 
                                    placeholder="What happened before?"
                                    value={newAbc.antecedent} 
                                    onChange={(e) => setNewAbc({...newAbc, antecedent: e.target.value})} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-900 mb-1">Behaviour (B)</label>
                                <div className="flex gap-2 mb-2">
                                    <button onClick={() => setNewAbc({...newAbc, isPositive: true})} className={`flex-1 py-2 text-xs font-black rounded-none border-2 transition-all ${newAbc.isPositive ? 'bg-green-600 border-green-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`}>Positive</button>
                                    <button onClick={() => setNewAbc({...newAbc, isPositive: false})} className={`flex-1 py-2 text-xs font-black rounded-none border-2 transition-all ${!newAbc.isPositive ? 'bg-red-600 border-red-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`}>Negative</button>
                                </div>
                                <textarea 
                                    className="w-full p-3 border-2 border-gray-300 outline-none rounded-none bg-gray-50 h-20 text-sm focus:border-coha-500 text-black placeholder-gray-500" 
                                    placeholder="What did the learner do?"
                                    value={newAbc.behaviour} 
                                    onChange={(e) => setNewAbc({...newAbc, behaviour: e.target.value})} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-900 mb-1">Consequence (C)</label>
                                <textarea 
                                    className="w-full p-3 border-2 border-gray-300 outline-none rounded-none bg-gray-50 h-20 text-sm focus:border-coha-500 text-black placeholder-gray-500" 
                                    placeholder="What happened after?"
                                    value={newAbc.consequence} 
                                    onChange={(e) => setNewAbc({...newAbc, consequence: e.target.value})} 
                                />
                            </div>
                            <Button fullWidth onClick={handleAddAbcLog} disabled={!newAbc.behaviour}><Plus size={20} /> Add ABC Entry</Button>
                        </div>
                    </div>
                </div>
            )}

            <div className="flex items-center gap-4 mb-8">
                <button onClick={() => navigate(-1)} className="p-3 bg-white border border-gray-200 hover:bg-gray-50 text-coha-900 transition-all shadow-sm">
                    <ArrowLeft size={24} />
                </button>
                <div>
                    <h2 className="text-3xl font-black text-coha-900 uppercase tracking-tight">{student.name}</h2>
                    <p className="text-gray-900 font-black uppercase text-xs tracking-widest opacity-60">14-Day Performance Tracking</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <div className="lg:col-span-1">
                    <div className="bg-white p-5 shadow-sm border border-gray-200 sticky top-24 rounded-none">
                        <h3 className="font-black text-gray-900 mb-5 flex items-center gap-2 border-b pb-2 uppercase text-xs tracking-[0.2em]"><Calendar size={18}/> Selection</h3>

                        <div className="grid grid-cols-4 gap-2">
                            {Array.from({ length: 14 }, (_, i) => i + 1).map((day) => {
                                const dayData = student.assessment?.teacherAssessments?.[day];
                                const isCompleted = dayData?.completed;
                                const isSelected = day === selectedDay && viewMode === 'DAILY';
                                const percentage = calculateDayPercentage(dayData);

                                return (
                                    <button
                                        key={day}
                                        onClick={() => handleDaySelect(day)}
                                        className={`aspect-square flex flex-col items-center justify-center border-2 transition-all rounded-none relative overflow-hidden
                                            ${isSelected ? 'border-coha-900 bg-coha-900 text-white scale-105 shadow-md' : 
                                              isCompleted ? 'border-green-600 bg-green-50 text-green-800' : 
                                              'border-gray-200 bg-gray-50 text-gray-400 hover:border-coha-300 hover:text-coha-500'}
                                        `}
                                    >
                                        <span className="font-black text-sm">{day}</span>
                                        {isCompleted && <span className="text-[9px] font-black uppercase tracking-tighter">{percentage}%</span>}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="mt-8 border-t pt-5 space-y-3">
                             <h4 className="text-[10px] font-black uppercase text-gray-400 tracking-[0.2em] mb-2">Reference Info</h4>
                            <button 
                                onClick={() => setViewMode('PARENT')}
                                className={`w-full text-left p-4 rounded-none flex items-center gap-3 transition-all border-2 ${viewMode === 'PARENT' ? 'bg-purple-50 border-purple-500 text-purple-900 font-bold' : 'bg-white border-gray-100 hover:bg-gray-50 text-gray-800 font-bold'}`}
                            >
                                <Heart size={20} className={viewMode === 'PARENT' ? 'text-purple-600' : 'text-gray-400'} />
                                <div className="flex-1">
                                    <span className="block text-sm">Parent Report</span>
                                    <span className="text-[10px] text-gray-500 uppercase font-black tracking-wider">Self Care Analysis</span>
                                </div>
                                {student.assessment?.parentSelfCare && <CheckCircle size={14} className="text-green-600" />}
                            </button>
                        </div>

                        <div className="mt-8 border-t pt-5">
                            <h4 className="text-[10px] font-black uppercase text-gray-400 tracking-[0.2em] mb-4">Enrollment</h4>
                            {isCompleted ? (
                                <div className="text-center bg-green-50 text-green-900 p-5 font-black border-2 border-green-600 shadow-sm">
                                    <CheckCircle className="mx-auto mb-3" size={40} />
                                    <span className="block uppercase text-[10px] tracking-widest mb-1 opacity-70">Assessment Finalized</span>
                                    <span className="block text-xl font-black mt-2 leading-tight uppercase">{student.assignedClass}</span>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex justify-between items-end">
                                        <span className="text-[10px] font-black uppercase text-gray-500 tracking-wider">Obs. Progress</span>
                                        <span className="text-lg font-black text-coha-900">{completedDaysCount} / 14</span>
                                    </div>
                                    <div className="w-full bg-gray-200 h-3">
                                        <div className="bg-coha-900 h-full transition-all duration-700" style={{ width: `${(completedDaysCount/14)*100}%` }}></div>
                                    </div>
                                    <Button 
                                        fullWidth 
                                        onClick={handleFinalize} 
                                        disabled={finalizing}
                                        className={isReadyToFinalize ? "bg-green-600 hover:bg-green-700 border-none shadow-xl py-4" : "bg-gray-300 opacity-60 cursor-not-allowed py-4"}
                                    >
                                        {finalizing ? (
                                            <Loader2 className="animate-spin" size={24} />
                                        ) : (
                                            <span className="flex items-center gap-3 font-black uppercase tracking-[0.1em] text-xs">
                                                <PlayCircle size={20} /> Finalize Enrollment
                                            </span>
                                        )}
                                    </Button>
                                    {!isReadyToFinalize && <p className="text-[10px] text-red-600 text-center font-black uppercase tracking-tight mt-2 italic">Finish all 14 observation days to unlock.</p>}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-3 space-y-8">
                    {viewMode === 'PARENT' ? (
                        <div className="bg-white p-8 shadow-sm border-l-8 border-purple-500 animate-fade-in relative text-black">
                             <h3 className="text-2xl font-black text-purple-900 mb-8 flex items-center gap-3 uppercase tracking-tight">
                                <User size={28} /> Detailed Parent Self-Care Report
                             </h3>
                            {!student.assessment?.parentSelfCare ? (
                                <div className="text-center py-20 bg-gray-50 border-2 border-dashed border-gray-300">
                                    <AlertTriangle className="mx-auto text-gray-300 mb-4" size={48} />
                                    <p className="text-gray-500 font-black uppercase tracking-widest text-sm">Awaiting parent submission</p>
                                </div>
                            ) : (
                                <div className="space-y-8">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="bg-purple-50 p-6 border-l-4 border-purple-400">
                                            <p className="text-[10px] font-black uppercase text-purple-600 tracking-widest mb-1">Submission Timeline</p>
                                            <p className="text-xl font-black text-purple-900">{new Date(student.assessment.parentSelfCare.completedDate).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                                        </div>
                                        <div className="bg-purple-900 p-6 text-white shadow-lg">
                                            <p className="text-[10px] font-black uppercase text-purple-300 tracking-widest mb-1">Self-Care Score</p>
                                            <p className="text-3xl font-black">{student.assessment.parentSelfCare.calculatedScore} / 5.0</p>
                                        </div>
                                    </div>

                                    <div className="bg-white border-2 border-gray-100 overflow-hidden">
                                        <div className="p-4 bg-gray-50 border-b-2 border-gray-100 font-black uppercase text-[10px] tracking-widest text-gray-600 flex justify-between">
                                            <span>Skill / Ability</span>
                                            <span>Parent Response</span>
                                        </div>
                                        <div className="divide-y-2 divide-gray-50">
                                            {PARENT_QUESTIONS.map(q => (
                                                <div key={q.id} className="flex justify-between items-center p-5 hover:bg-purple-50/30 transition-colors">
                                                    <span className="text-black font-bold uppercase text-xs tracking-tight">{q.text}</span>
                                                    <span className={`font-black uppercase text-[10px] tracking-widest px-4 py-2 border-2 ${
                                                        (student.assessment?.parentSelfCare as any)[q.id] === 'Yes' ? 'bg-green-100 text-green-700 border-green-200' :
                                                        (student.assessment?.parentSelfCare as any)[q.id] === 'No' ? 'bg-red-100 text-red-700 border-red-200' :
                                                        'bg-yellow-100 text-yellow-800 border-yellow-200'
                                                    }`}>
                                                        {(student.assessment?.parentSelfCare as any)[q.id]}
                                                    </span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>

                                    {student.assessment.parentSelfCare.comments && (
                                        <div className="bg-gray-50 p-6 border-l-8 border-gray-300 shadow-inner">
                                            <p className="text-[10px] font-black uppercase text-gray-500 tracking-widest mb-3">Additional Context Provided by Parent</p>
                                            <p className="italic text-black text-xl font-medium leading-relaxed">"{student.assessment.parentSelfCare.comments}"</p>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    ) : (
                        <>
                            <div className="flex items-center justify-between border-b-4 border-coha-900 pb-5">
                                <h3 className="text-3xl font-black text-coha-900 flex items-center gap-5 uppercase tracking-tighter">
                                    <span className="bg-coha-900 text-white w-14 h-14 flex items-center justify-center rounded-none text-2xl shadow-xl">{selectedDay}</span>
                                    Assessment Log
                                </h3>
                                {student.assessment?.teacherAssessments?.[selectedDay]?.completed && (
                                    <div className="flex items-center gap-6">
                                         <div className="text-right">
                                             <span className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-1">Daily Score</span>
                                             <span className="text-3xl font-black text-coha-900">{student.assessment.teacherAssessments[selectedDay].dailyTotalScore || '0'}<span className="text-lg opacity-40">/5.0</span></span>
                                         </div>
                                         <span className="bg-green-600 text-white px-5 py-3 font-black uppercase text-[10px] tracking-[0.2em] shadow-lg">Saved</span>
                                    </div>
                                )}
                            </div>

                            <div className="bg-white p-8 shadow-sm border border-gray-200 rounded-none text-black font-sans">
                                <h4 className="font-black text-gray-900 mb-8 flex items-center gap-3 uppercase tracking-[0.2em] text-xs">
                                    <Activity className="text-coha-500" size={20}/> 1. CORE PERFORMANCE DOMAINS (0.0 to 5.0)
                                </h4>
                                <div className="grid grid-cols-1 sm:grid-cols-5 gap-6">
                                    {['Numbers', 'Reading', 'SelfCare', 'Behaviour', 'Senses'].map((field) => (
                                        <div key={field}>
                                            <label className="block text-[10px] font-black text-gray-500 tracking-widest mb-2 uppercase">{field}</label>
                                            <CustomSelect 
                                                value={String((formState as any)[field.charAt(0).toLowerCase() + field.slice(1)])}
                                                onChange={(val) => !isReadOnly && handleMainScoreChange(field.charAt(0).toLowerCase() + field.slice(1), val)}
                                                options={SCORE_OPTIONS}
                                                placeholder="Score"
                                                className="mb-0"
                                            />
                                        </div>
                                    ))}
                                </div>
                            </div>

                             <div className="bg-white p-8 shadow-sm border border-gray-200 rounded-none text-black">
                                <h4 className="font-black text-gray-900 mb-6 flex items-center gap-3 uppercase tracking-[0.2em] text-xs">
                                    <Brain className="text-purple-600" size={20}/> 2. COGNITIVE: LEARN TO THINK
                                </h4>
                                <div className="p-8 bg-purple-50 border-l-8 border-purple-600 mb-8 shadow-inner">
                                    <p className="text-2xl font-black text-purple-900 leading-[1.1] uppercase tracking-tighter">{THINKING_TASKS[selectedDay - 1].desc}</p>
                                </div>
                                <div className="flex gap-4">
                                    {['Yes', 'Yes with help', 'No'].map(opt => (
                                        <button 
                                            key={opt} 
                                            onClick={() => !isReadOnly && setFormState(prev => ({...prev, thinkingResponse: opt}))} 
                                            className={`flex-1 py-6 border-4 font-black uppercase tracking-[0.1em] text-xs transition-all ${formState.thinkingResponse === opt ? 'bg-purple-600 border-purple-600 text-white shadow-2xl translate-y-[-4px]' : 'bg-white border-gray-200 text-gray-500 hover:border-purple-300 hover:text-purple-900'}`} 
                                            disabled={isReadOnly}
                                        >
                                            {opt}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="bg-white p-8 shadow-sm border border-gray-200 rounded-none text-black">
                                <div className="flex justify-between items-center mb-10 border-b-2 border-gray-100 pb-5">
                                    <h4 className="font-black text-gray-900 flex items-center gap-3 uppercase tracking-[0.2em] text-xs">
                                        <ClipboardList className="text-orange-600" size={20}/> 3. BEHAVIOURAL INCIDENTS (ABC)
