                                    value={newAbc.behaviour} 
                                    onChange={(e) => setNewAbc({...newAbc, behaviour: e.target.value})} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-900 mb-1">Consequence (C)</label>
