                                    className="w-full p-3 border-2 border-gray-300 outline-none rounded-none bg-gray-50 h-20 text-sm focus:border-coha-500 text-black placeholder-gray-500" 
                                    placeholder="Reaction/Outcome"
                                    value={newAbc.consequence} 
                                    onChange={(e) => setNewAbc({...newAbc, consequence: e.target.value})} 
                                />
                            </div>
                            <Button fullWidth onClick={handleAddAbcLog} disabled={!newAbc.behaviour}><Plus size={20} /> Add ABC Entry</Button>
                        </div>
                    </div>
                </div>
            )}

            <div className="flex items-center gap-4 mb-8">
                <button onClick={() => navigate(-1)} className="p-3 bg-white border border-gray-200 hover:bg-gray-50 text-coha-900 transition-all shadow-sm">
                    <ArrowLeft size={24} />
                </button>
                <div>
                    <h2 className="text-3xl font-black text-coha-900 uppercase tracking-tight">{student.name}</h2>
                    <p className="text-gray-900 font-black uppercase text-xs tracking-widest opacity-60">14-Day Performance Tracking</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <div className="lg:col-span-1">
                    <div className="bg-white p-5 shadow-sm border border-gray-200 sticky top-24 rounded-none">
