import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getStudentsByAssignedClass } from '../../services/dataService';
import { Student } from '../../types';
import { Loader } from '../../components/ui/Loader';
import { Users, BookOpen, Activity, CheckCircle, Clock, Search, Filter } from 'lucide-react';
import { Button } from '../../components/ui/Button';

interface TeacherDashboardProps {
  user: any; // The logged-in teacher object
}

export const TeacherDashboard: React.FC<TeacherDashboardProps> = ({ user }) => {
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    const fetchClassData = async () => {
      if (user?.assignedClass) {
        const data = await getStudentsByAssignedClass(user.assignedClass);
        setStudents(data);
      }
      setLoading(false);
    };
    fetchClassData();
  }, [user]);

  if (loading) return <Loader />;

  if (!user.assignedClass) {
      return (
          <div className="flex flex-col items-center justify-center h-full text-center p-8">
              <div className="bg-yellow-100 p-4 rounded-full mb-4">
                  <BookOpen size={48} className="text-yellow-600"/>
              </div>
              <h2 className="text-2xl font-bold text-gray-800">No Class Assigned</h2>
              <p className="text-gray-600 mt-2">You have not been assigned a class yet. Please contact the administrator.</p>
          </div>
      );
  }

  // Split students by status
  const assessmentStudents = students.filter(s => s.studentStatus === 'ASSESSMENT');
  const enrolledStudents = students.filter(s => s.studentStatus === 'ENROLLED');

  const filteredEnrolled = enrolledStudents.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="font-sans text-black">
      <div className="mb-10">
        <h2 className="text-3xl font-black text-coha-900 uppercase tracking-tighter leading-none mb-1">Class Cohort: {user.assignedClass}</h2>
        <p className="text-gray-500 font-black uppercase text-[10px] tracking-[0.2em]">Academic Management & Student Observations</p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
         <div className="bg-white p-6 shadow-sm border-l-8 border-coha-900 border-b border-r border-t border-gray-200">
             <div className="flex justify-between items-center mb-4">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Total Population</h3>
                 <Users className="text-coha-500" size={20}/>
             </div>
             <p className="text-4xl font-black text-coha-900 tracking-tighter">{students.length}</p>
         </div>
         <div className="bg-white p-6 shadow-sm border-l-8 border-purple-600 border-b border-r border-t border-gray-200">
             <div className="flex justify-between items-center mb-4">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Under Observation</h3>
                 <Activity className="text-purple-500" size={20}/>
             </div>
             <p className="text-4xl font-black text-purple-900 tracking-tighter">{assessmentStudents.length}</p>
         </div>
         <div className="bg-white p-6 shadow-sm border-l-8 border-green-600 border-b border-r border-t border-gray-200">
             <div className="flex justify-between items-center mb-4">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Permanent Register</h3>
                 <CheckCircle className="text-green-500" size={20}/>
             </div>
             <p className="text-4xl font-black text-green-900 tracking-tighter">{enrolledStudents.length}</p>
         </div>
      </div>

      {/* Observation List */}
      {assessmentStudents.length > 0 && (
          <div className="bg-white border-2 border-purple-200 shadow-xl mb-10 animate-fade-in">
             <div className="p-5 bg-purple-50 border-b-2 border-purple-100 flex justify-between items-center">
                 <h3 className="text-purple-900 font-black flex items-center gap-3 uppercase text-xs tracking-widest">
                     <Activity size={20} /> Active Observations (14-Day Cycle)
                 </h3>
                 <span className="bg-purple-600 text-white text-[10px] font-black px-3 py-1 rounded-none uppercase">{assessmentStudents.length} Pending</span>
             </div>
             <div className="overflow-x-auto">
                 <table className="w-full text-left">
                     <thead className="bg-gray-50 text-[10px] font-black uppercase text-gray-400 tracking-widest">
                         <tr>
                             <th className="px-6 py-4">Student Identification</th>
                             <th className="px-6 py-4">Placement Level</th>
                             <th className="px-6 py-4">Observation Progress</th>
                             <th className="px-6 py-4 text-right">Actions</th>
                         </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-100">
                         {assessmentStudents.map(student => {
                             const completedDays = student.assessment?.teacherAssessments ? Object.values(student.assessment.teacherAssessments).filter((d:any) => d.completed).length : 0;
                             const progress = (completedDays / 14) * 100;

                             return (
                                 <tr key={student.id} className="hover:bg-purple-50/50 transition-colors group">
                                     <td className="px-6 py-5">
                                         <p className="font-black text-coha-900 text-base uppercase tracking-tight">{student.name}</p>
                                         <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">ID: {student.id}</p>
                                     </td>
                                     <td className="px-6 py-5">
                                         <span className="px-3 py-1 bg-white border-2 border-gray-100 text-[10px] font-black text-gray-700 uppercase">{student.level}</span>
                                     </td>
                                     <td className="px-6 py-5">
                                         <div className="w-full bg-gray-100 rounded-none h-4 max-w-[200px] border border-gray-200 p-0.5 overflow-hidden">
                                             <div className="bg-purple-600 h-full transition-all duration-1000" style={{ width: `${progress}%` }}></div>
                                         </div>
                                         <span className="text-[9px] font-black text-purple-700 mt-2 block uppercase tracking-wider">{completedDays} / 14 Days Logged</span>
                                     </td>
                                     <td className="px-6 py-5 text-right">
                                         <Button onClick={() => navigate(`/teacher/assessment/${student.id}`)} className="py-2 px-6 text-[10px] font-black uppercase tracking-widest bg-purple-600 hover:bg-purple-700 shadow-lg group-hover:translate-y-[-2px] transition-all">
                                             Update Log
                                         </Button>
                                     </td>
                                 </tr>
                             );
                         })}
                     </tbody>
                 </table>
             </div>
          </div>
      )}

      {/* Enrolled List / Class Register */}
      <div className="bg-white border-2 border-gray-200 shadow-sm overflow-hidden">
          <div className="p-5 border-b-2 border-gray-100 bg-gray-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <h3 className="text-gray-900 font-black flex items-center gap-3 uppercase text-xs tracking-widest">
                  <BookOpen size={20} className="text-coha-900"/> Official Class Register
              </h3>
              <div className="relative w-full sm:w-64">
                  <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input 
                    type="text" 
                    placeholder="Search register..." 
                    className="w-full pl-10 pr-4 py-2 bg-white border-2 border-gray-200 text-xs font-bold uppercase tracking-widest outline-none focus:border-coha-900 transition-all"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
              </div>
          </div>
          <div className="overflow-x-auto">
             <table className="w-full text-left">
                 <thead className="bg-white text-[10px] font-black uppercase text-gray-400 tracking-widest">
                     <tr>
                         <th className="px-6 py-4">Student Name</th>
                         <th className="px-6 py-4">Enrollment Status</th>
                         <th className="px-6 py-4">Assigned Stage</th>
                         <th className="px-6 py-4">Guardian Contact</th>
                     </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-100">
                     {filteredEnrolled.map(student => (
                         <tr key={student.id} className="hover:bg-gray-50 transition-colors">
                             <td className="px-6 py-5 font-black text-gray-900 uppercase text-sm">{student.name}</td>
                             <td className="px-6 py-5">
                                 <span className="bg-green-600 text-white text-[9px] px-3 py-1 font-black uppercase tracking-widest shadow-sm">Enrolled</span>
                             </td>
                             <td className="px-6 py-5">
                                 <div className="flex items-center gap-2">
                                     <span className="font-bold text-xs text-gray-800 uppercase">{student.assignedClass || student.grade}</span>
                                     {student.stage && <span className="bg-coha-900 text-white px-2 py-0.5 text-[10px] font-black">S{student.stage}</span>}
                                 </div>
                             </td>
                             <td className="px-6 py-5 text-[11px] font-mono font-bold text-gray-600 tracking-tighter">
                                 {student.fatherPhone || student.motherPhone || 'N/A'}
                             </td>
                         </tr>
                     ))}
                     {filteredEnrolled.length === 0 && (
                         <tr><td colSpan={4} className="p-12 text-center text-gray-400 font-black uppercase tracking-widest text-xs italic">No enrolled learners found in this cohort register.</td></tr>
                     )}
                 </tbody>
             </table>
          </div>
      </div>

    </div>
  );
};

import React from 'react';

export enum UserRole {
  ADMIN = 'ADMIN',
  TEACHER = 'TEACHER',
  PARENT = 'PARENT'
}

export enum Division {
  MAINSTREAM = 'Mainstream',
  SPECIAL_NEEDS = 'Special Needs'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  pin: string;
}

export interface Teacher extends User {
  subject?: string;
  email?: string;
  assignedClass?: string;
}

export interface MenuItem {
  label: string;
  path: string;
  icon: React.ReactNode;
}

export interface FeeItem {
  id: string;
  category: string;
  amount: string; 
  frequency: string;
  notes?: string;
}

export interface SupplyItem {
  id: string;
  name: string;
  isRequired: boolean;
}

export interface SystemSettings {
  id?: string;
  adminName: string;
  adminPin: string;

  fees: FeeItem[];
  uniforms: SupplyItem[];
  stationery: SupplyItem[];
  grades: string[];
  specialNeedsLevels: string[];

  termStartDate: string;
  termStartTime: string;

  lastStudentId?: number; 
}

// Assessment Specific Types

export type AssessmentResponse = 'Yes' | 'No' | 'Yes with help';

export interface SelfCareAssessment {
  s1: AssessmentResponse; // drink from a cup
  s2: AssessmentResponse; // feed self with a spoon
  s3: AssessmentResponse; // wash hands
  s4: AssessmentResponse; // wash and dry him
  s5: AssessmentResponse; // dress and undress him
  s6: AssessmentResponse; // brush teeth and hair by him
  s7: AssessmentResponse; // go to the toilet by himself
  s8: AssessmentResponse; // assist with simple tasks around the home
  s9: AssessmentResponse; // can be send around with messages
  comments?: string;
  completedDate: string;
  calculatedScore: number; // Out of 5
}

export interface ABCLog {
  id: string;
  antecedent: string;
  behaviour: string;
  consequence: string;
  isPositive: boolean;
  time: string;
}

export interface AssessmentDay {
  date?: string;
  completed: boolean;
  // Form 1: Main Assessment (5 areas, score /5 each)
  scores: {
    numbers: number;
    reading: number;
    selfCare: number;
    behaviour: number;
    senses: number;
  };
  // Form 2: Learn To Think (Specific task for the day)
  thinkingTask?: {
    taskId: string; // T1, T2 etc
    description: string;
    response: AssessmentResponse;
  };
  thinkingScore: number; // Converted from response to /5
  // Form 3: ABC Behaviour (Positive/Negative -> /5)
  abcScore: number;
  abcLogs?: ABCLog[];
  dailyTotalScore?: number; // Normalized 0.0 - 5.0 score for the day
}

export interface AssessmentData {
  parentSelfCare?: SelfCareAssessment;
  teacherAssessments: { [day: number]: AssessmentDay }; // Days 1-14
  finalAverage?: number;
  stage?: 1 | 2 | 3;
  isComplete: boolean;
  parentSelfCareScore?: number; // Legacy/Quick access
}

export interface Application {
  id?: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  submissionDate: any; 

  // Learner Details
  surname: string;
  firstName: string;
  dob: string;
  citizenship: string;
  gender: 'Male' | 'Female';
  address: string;
  region: string;

  division: Division; 
  grade?: string; 
  level?: string; 

  isSpecialNeeds: boolean; 
  specialNeedsType?: string; 

  // Parent Details
  fatherName: string;
  fatherPhone: string;
  fatherEmail: string;
  motherName: string;
  motherPhone: string;
  motherEmail?: string;

  // Emergency Contact
  emergencyName: string;
  emergencyRelationship: string;
  emergencyWork: string;
  emergencyCell: string;
  emergencyEmail: string;

  // Medical & History
  hasPreviousSchool: boolean;
  previousSchool: string;
  highestGrade: string;
  medicalConditions: string;

  // Professionals
  doctorName?: string;
  doctorContact?: string;
  audiologistName?: string;
  audiologistContact?: string;
  therapistName?: string;
  therapistContact?: string;

  // Medical Aid
  hasMedicalAid: boolean;
  medicalAidName?: string;
  medicalAidMemberName?: string;
  medicalAidMemberID?: string;
  medicalAidOption?: string;

  // Languages
  langEnglish: 'Good' | 'Fair' | 'Poor';
  langOther1Name?: string;
  langOther1Rating?: 'Good' | 'Fair' | 'Poor';
  langOther2Name?: string;
  langOther2Rating?: 'Good' | 'Fair' | 'Poor';

  // Consents
  medicalConsent: boolean;
  agreed: boolean;

  // Office Use
  officeReviewDate?: string;
  officeReviewer?: string;
  officeStatus?: string;
  officeResponseDate?: string;
  officeResponseMethod?: string;
}

export type StudentStatus = 'WAITING_PAYMENT' | 'PAYMENT_VERIFICATION' | 'ASSESSMENT' | 'ENROLLED';

export interface Student extends Partial<Application> {
  id: string;
  name: string; 
  grade: string;
  level?: string;
  stage?: 1 | 2 | 3;
  assignedClass?: string;

  parentPin: string;
  parentName: string;
  enrolledAt?: any;
  studentStatus: StudentStatus;

  receiptNumber?: string;
  receiptSubmissionDate?: any;
  paymentRejected?: boolean;

  assessment?: AssessmentData;
}

export interface Receipt {
  id?: string;
  number: string;
  amount: string;
  date: string;
  isUsed: boolean;
  usedByStudentId?: string;
  createdAt?: any;
}

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getApplications, getStudentsByStatus, verifyPayment, rejectPayment, getReceipts, addReceipt, deleteReceipt, deleteStudent, getPendingActionCounts } from '../../services/dataService';
import { Application, Student, Receipt } from '../../types';
import { Eye, Clock, Search, Filter, Check, X, Plus, Trash2, Key, Mail } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Toast } from '../../components/ui/Toast';
import { ConfirmModal } from '../../components/ui/ConfirmModal';

type ViewMode = 'APPLICATIONS' | 'PENDING_PAYMENT' | 'VERIFICATION' | 'RECEIPTS';

export const ApplicationsPage: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('APPLICATIONS');
  const [applications, setApplications] = useState<Application[]>([]);
  const [pendingPaymentList, setPendingPaymentList] = useState<Student[]>([]);
  const [verificationList, setVerificationList] = useState<Student[]>([]);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'PENDING' | 'REJECTED'>('PENDING');
  const navigate = useNavigate();

  // Counts for Badges
  const [counts, setCounts] = useState({ pendingApps: 0, pendingVerifications: 0, total: 0 });

  // Receipts State
  const [newReceiptNumber, setNewReceiptNumber] = useState('');
  const [newReceiptAmount, setNewReceiptAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ msg: '', show: false, type: 'success' as 'success' | 'error' });

  // Delete State
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Email/Verify Modal State
  const [emailModalOpen, setEmailModalOpen] = useState(false);
  const [verifyResult, setVerifyResult] = useState<{success: boolean, student: Student | null, message: string}>({success: false, student: null, message: ''});

  useEffect(() => {
    loadData();
    getPendingActionCounts().then(setCounts);
  }, [viewMode]);

  const loadData = async () => {
    if (viewMode === 'APPLICATIONS') {
        const data = await getApplications();
        // Only show Pending and Rejected here. Approved are in Pending Payment.
        setApplications(data);
    } else if (viewMode === 'PENDING_PAYMENT') {
        const data = await getStudentsByStatus('WAITING_PAYMENT');
        setPendingPaymentList(data);
    } else if (viewMode === 'VERIFICATION') {
        const data = await getStudentsByStatus('PAYMENT_VERIFICATION');
        setVerificationList(data);
    } else if (viewMode === 'RECEIPTS') {
        const data = await getReceipts();
        setReceipts(data);
    }
  };

  const handleVerifyClick = async (student: Student) => {
    if (!student.receiptNumber) return;
    setLoading(true);
    // Check validity ONLY
    const result = await verifyPayment(student.id, student.receiptNumber);
    setLoading(false);

    // Open Modal to decide on Email
    setVerifyResult({
        success: result.success,
        student: student,
        message: result.success ? 'Payment Verified Successfully.' : 'Invalid Receipt Number.'
    });
    setEmailModalOpen(true);
  };

  const finalizeVerification = async (sendEmail: boolean) => {
     if (!verifyResult.student) return;
     const student = verifyResult.student;

     if (verifyResult.success) {
         // Success Logic handled by verifyPayment in dataService (it updates status)
         // We just need to handle email if requested
         if (sendEmail) {
             const subject = "Enrollment Update: Payment Verified";
             const body = `Dear ${student.parentName},\n\nWe have successfully verified your payment receipt (${student.receiptNumber}).\n\nThe student ${student.name} is now queued for assessment.\n\nRegards,\nCircle of Hope Academy`;
             window.location.href = `mailto:${student.fatherEmail || student.motherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
         }
         setToast({ msg: 'Student moved to Assessment.', show: true, type: 'success' });
     } else {
         // Failure Logic: Must mark as rejected
         await rejectPayment(student.id);
         if (sendEmail) {
             const subject = "Enrollment Update: Payment Verification Failed";
             const body = `Dear ${student.parentName},\n\nThe receipt number (${student.receiptNumber}) provided for ${student.name} could not be verified.\n\nPlease check the number and try again on the parent portal.\n\nRegards,\nCircle of Hope Academy`;
             window.location.href = `mailto:${student.fatherEmail || student.motherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
         }
         setToast({ msg: 'Payment Rejected. Parent notified on dashboard.', show: true, type: 'error' });
     }

     setEmailModalOpen(false);
     loadData();
     getPendingActionCounts().then(setCounts);
  };

  const confirmDelete = (student: Student) => {
      setStudentToDelete(student);
      setDeleteModalOpen(true);
  };

  const handleDeleteStudent = async () => {
      if (studentToDelete) {
          await deleteStudent(studentToDelete.id);
          setDeleteModalOpen(false);
          setStudentToDelete(null);
          loadData();
          setToast({ msg: 'Record deleted successfully', show: true, type: 'success' });
      }
  };

  const handleAddReceipt = async () => {
      if (!newReceiptNumber || !newReceiptAmount) return;
      setLoading(true);
      const success = await addReceipt(newReceiptNumber, newReceiptAmount, new Date().toISOString());
      if (success) {
          setNewReceiptNumber('');
          setNewReceiptAmount('');
          loadData();
          setToast({ msg: 'Receipt added successfully', show: true, type: 'success' });
      }
      setLoading(false);
  };

  const handleDeleteReceipt = async (id: string) => {
      if(window.confirm('Delete this receipt?')) {
          await deleteReceipt(id);
          loadData();
      }
  };

  const filteredApps = applications.filter(app => {
      const matchesSearch = (() => {
        const fullName = `${app.firstName} ${app.surname}`.toLowerCase();
        const parent = (app.fatherName || app.motherName || '').toLowerCase();
        const term = searchTerm.toLowerCase();
        return fullName.includes(term) || parent.includes(term) || (app.grade || '').toLowerCase().includes(term);
      })();
      return matchesSearch && app.status === statusFilter;
  });

  return (
    <div>
      <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({...toast, show: false})} variant={toast.type} />

      {/* Delete Confirmation Modal */}
      <ConfirmModal 
        isOpen={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        onConfirm={handleDeleteStudent}
        title="Delete Record?"
        message={`Are you sure you want to delete ${studentToDelete?.name}? This will permanently remove them from the admission process.`}
      />

      {/* Email / Finalize Modal */}
      {emailModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
            <div className={`bg-white w-full max-w-md shadow-2xl border-t-8 ${verifyResult.success ? 'border-green-500' : 'border-red-500'} animate-fade-in`}>
                <div className="p-6">
                    <h3 className={`text-xl font-bold mb-2 ${verifyResult.success ? 'text-green-700' : 'text-red-700'}`}>
                        {verifyResult.success ? 'Verification Successful' : 'Verification Failed'}
                    </h3>
                    <p className="text-gray-600 mb-6">{verifyResult.message} Would you like to send an email notification to the parent?</p>
                    <div className="flex flex-col gap-3">
                        <Button fullWidth onClick={() => finalizeVerification(true)}>
                            <Mail size={18} /> Update & Send Email
                        </Button>
                        <Button fullWidth variant="outline" onClick={() => finalizeVerification(false)}>
                            Update Only (Skip Email)
                        </Button>
                        <button onClick={() => setEmailModalOpen(false)} className="text-sm text-gray-500 hover:text-gray-900 mt-2">Cancel</button>
                    </div>
                </div>
            </div>
          </div>
      )}

      <div className="mb-6 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-coha-900">Admissions Management</h2>
            <p className="text-gray-600">Manage applications, verify payments, and issue receipts.</p>
        </div>
        <div className="flex flex-wrap bg-white shadow-sm border border-gray-200">
            <button 
                onClick={() => setViewMode('APPLICATIONS')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'APPLICATIONS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Applications
                {counts.pendingApps > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{counts.pendingApps}</span>}
            </button>
            <button 
                onClick={() => setViewMode('PENDING_PAYMENT')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'PENDING_PAYMENT' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Pending Payment
            </button>
            <button 
                onClick={() => setViewMode('VERIFICATION')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'VERIFICATION' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Payment Verification
                {counts.pendingVerifications > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{counts.pendingVerifications}</span>}
            </button>
            <button onClick={() => setViewMode('RECEIPTS')} className={`px-4 py-2 text-sm font-bold uppercase ${viewMode === 'RECEIPTS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}>Available Receipts</button>
        </div>
      </div>

      {/* MODE: APPLICATIONS (New / Rejected) */}
      {viewMode === 'APPLICATIONS' && (
          <div className="animate-fade-in">
             <div className="flex border-b border-gray-200 mb-6 bg-white shadow-sm overflow-x-auto">
                <button onClick={() => setStatusFilter('PENDING')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 flex items-center gap-2 ${statusFilter === 'PENDING' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>
                    Pending
                    {counts.pendingApps > 0 && <span className="bg-red-100 text-red-600 text-[10px] px-1.5 py-0.5 rounded-full">{counts.pendingApps}</span>}
                </button>
                <button onClick={() => setStatusFilter('REJECTED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${statusFilter === 'REJECTED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Rejected</button>
             </div>

             <div className="bg-white border border-gray-200 shadow-sm">
                <div className="p-4 border-b border-gray-200">
                    <div className="relative max-w-md">
                        <Search className="absolute left-3 top-3 text-gray-400" size={20} />
