                                    <td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-bold border ${app.status === 'REJECTED' ? 'bg-red-100 text-red-800 border-red-200' : 'bg-yellow-100 text-yellow-800 border-yellow-200'}`}>{app.status}</span></td>
