                )}

                <CustomSelect 
                  label="Region"
                  value={formData.region}
                  options={NAMIBIAN_REGIONS}
                  onChange={(val) => handleCustomSelect('region', val)}
                  required
                  error={errors.region}
                />

                <FormInput name="address" label="Residential Address" value={formData.address} onChange={handleChange} required error={errors.address} />
            </div>
          </div>
        )}

        {/* Step 2: Parents */}
        {currentStep === 1 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6">Parent / Guardian Details</h3>
                <FormInput name="fatherName" label="Father/Guardian Name" value={formData.fatherName} onChange={handleChange} required error={errors.fatherName} />
                <FormInput name="fatherPhone" label="Phone Number" type="tel" value={formData.fatherPhone} onChange={handleChange} required error={errors.fatherPhone} />
                <FormInput name="fatherEmail" label="Email Address" type="email" value={formData.fatherEmail} onChange={handleChange} required error={errors.fatherEmail} />
                <div className="w-full h-px bg-gray-200 my-8"></div>
                <FormInput name="motherName" label="Mother/Guardian Name" value={formData.motherName} onChange={handleChange} />
                <FormInput name="motherPhone" label="Phone Number" type="tel" value={formData.motherPhone} onChange={handleChange} />
                <FormInput name="motherEmail" label="Email Address" type="email" value={formData.motherEmail} onChange={handleChange} />
            </div>
            <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Emergency Contact</h3>
                <div className="bg-red-50 p-4 border-l-4 border-red-400 mb-6 rounded-r-lg">
                  <p className="text-xs text-red-800">Provide a contact other than the parents.</p>
                </div>
                <FormInput name="emergencyName" label="Full Name" value={formData.emergencyName} onChange={handleChange} required error={errors.emergencyName} />
                <FormInput name="emergencyRelationship" label="Relationship" value={formData.emergencyRelationship} onChange={handleChange} required error={errors.emergencyRelationship} />
                <FormInput name="emergencyCell" label="Cell Number" type="tel" value={formData.emergencyCell} onChange={handleChange} required error={errors.emergencyCell} />
                <FormInput name="emergencyWork" label="Work Contact" value={formData.emergencyWork} onChange={handleChange} />
                <FormInput name="emergencyEmail" label="Email Address" type="email" value={formData.emergencyEmail} onChange={handleChange} />
            </div>
          </div>
        )}

        {/* Step 3: History */}
        {currentStep === 2 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Educational History</h3>
                 <div className="mb-6">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                      type="checkbox" 
                      name="hasPreviousSchool" 
                      checked={!formData.hasPreviousSchool} 
                      onChange={(e) => setFormData({...formData, hasPreviousSchool: !e.target.checked})}
                      className="w-5 h-5 accent-coha-500"
                    />
                    <span className="text-sm text-gray-700">First time attender (No previous school)</span>
                  </label>
                </div>
                {formData.hasPreviousSchool && (
                  <div className="pl-4 border-l-2 border-gray-200 mb-8">
                    <FormInput name="previousSchool" label="Previous School Name" value={formData.previousSchool} onChange={handleChange} required error={errors.previousSchool} />
                    <FormInput name="highestGrade" label="Highest Grade Completed" value={formData.highestGrade} onChange={handleChange} required error={errors.highestGrade} />
                  </div>
                )}
             </div>
             <div>
                <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Language Proficiency</h3>
                <div className="mb-6">
                  <label className="block text-gray-800 text-sm font-medium mb-2">English Proficiency</label>
                  <div className="flex gap-4">
                    {['Good', 'Fair', 'Poor'].map(rating => (
                      <label key={rating} className="flex items-center gap-2 cursor-pointer bg-gray-50 px-3 py-2 rounded border border-gray-200">
                        <input 
                          type="radio" 
                          name="langEnglish" 
                          value={rating} 
                          checked={formData.langEnglish === rating} 
                          onChange={handleChange}
                          className="accent-coha-500" 
                        />
                        <span className="text-sm">{rating}</span>
                      </label>
                    ))}
                  </div>
                </div>
                <FormInput name="langOther1Name" label="Other Language (Optional)" value={formData.langOther1Name} onChange={handleChange} />
             </div>
          </div>
        )}

        {/* Step 4: Medical */}
        {currentStep === 3 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Medical Information</h3>
                 <div className="mb-6">
                    <label className="block text-gray-800 text-sm font-medium mb-2">Known Medical Conditions / Allergies</label>
                    <textarea 
                      name="medicalConditions" 
                      value={formData.medicalConditions} 
                      onChange={handleChange}
                      className="w-full p-3 border-b-2 border-gray-300 focus:border-coha-500 outline-none bg-gray-50 h-24 text-sm"
                      placeholder="List any conditions here..."
                    />
                 </div>
                 <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-6">
                    <h4 className="text-sm font-bold text-gray-700 mb-4 uppercase tracking-wide">Professionals (If Applicable)</h4>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4">
                        <FormInput name="doctorName" label="Family Doctor Name" value={formData.doctorName} onChange={handleChange} className="bg-white" />
                        <FormInput name="doctorContact" label="Doctor Contact" value={formData.doctorContact} onChange={handleChange} className="bg-white" />
                        <FormInput name="audiologistName" label="Audiologist Name" value={formData.audiologistName} onChange={handleChange} className="bg-white" />
                        <FormInput name="audiologistContact" label="Audiologist Contact" value={formData.audiologistContact} onChange={handleChange} className="bg-white" />
                        <FormInput name="therapistName" label="Occupational Therapist" value={formData.therapistName} onChange={handleChange} className="bg-white" />
                        <FormInput name="therapistContact" label="Therapist Contact" value={formData.therapistContact} onChange={handleChange} className="bg-white" />
                    </div>
                 </div>
             </div>
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Medical Aid Details</h3>
                 <div className="mb-6">
                  <label className="flex items-center gap-3 cursor-pointer mb-4">
                    <input 
                      type="checkbox" 
                      name="hasMedicalAid" 
                      checked={formData.hasMedicalAid} 
                      onChange={handleChange}
                      className="w-5 h-5 accent-coha-500"
                    />
                    <span className="font-bold text-gray-800 text-sm">Learner has Medical Aid</span>
                  </label>
                  {formData.hasMedicalAid && (
                    <div className="pl-4 border-l-2 border-coha-500 animate-fade-in">
                       <FormInput name="medicalAidName" label="Medical Aid Name" value={formData.medicalAidName} onChange={handleChange} required error={errors.medicalAidName} />
                       <FormInput name="medicalAidOption" label="Plan Option" value={formData.medicalAidOption} onChange={handleChange} />
                       <FormInput name="medicalAidMemberName" label="Main Member Name" value={formData.medicalAidMemberName} onChange={handleChange} required error={errors.medicalAidMemberName} />
                       <FormInput name="medicalAidMemberID" label="Member ID" value={formData.medicalAidMemberID} onChange={handleChange} required error={errors.medicalAidMemberID} />
                    </div>
                  )}
                 </div>
             </div>
          </div>
        )}

        {/* Step 5: Consent */}
        {currentStep === 4 && (
          <div className="animate-fade-in grid grid-cols-1 lg:grid-cols-2 gap-8">
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Consent & Declaration</h3>
                 <div className={`p-5 rounded-lg border-l-4 mb-6 transition-all duration-300 ${errors.medicalConsent ? 'bg-red-50 border-red-600' : 'bg-red-50 border-red-500'}`}>
                    <h4 className="font-bold text-red-800 mb-2">Medical Emergency Consent</h4>
                    <p className="text-sm text-gray-700 mb-4 leading-relaxed">
                      In a critical situation, the school reserves the right to utilise medical services if parents cannot be reached.
                    </p>
                    <label className="flex items-start gap-3 cursor-pointer">
                       <input 
                          type="checkbox" 
                          name="medicalConsent" 
                          checked={formData.medicalConsent} 
                          onChange={handleChange}
                          className="mt-1 w-6 h-6 accent-red-600"
                        />
                       <span className="text-sm font-bold text-red-900">
                         I agree that emergency treatment may be provided.
                       </span>
                    </label>
                    {errors.medicalConsent && <p className="text-red-700 text-xs mt-2 font-bold uppercase">{errors.medicalConsent}</p>}
                 </div>
             </div>
             <div>
                 <h3 className="text-lg font-bold text-gray-900 mb-6 lg:mt-0 mt-8">Terms & Conditions</h3>
                 <div className={`p-5 rounded-lg border-l-4 mb-8 transition-all duration-300 ${errors.agreed ? 'bg-red-50 border-red-600' : 'bg-gray-50 border-gray-400'}`}>
                    <h4 className="font-bold text-gray-900 mb-4">Declaration</h4>
                    <ul className="list-disc pl-5 space-y-2 text-sm text-gray-600 mb-6">
                      <li>I accept school fees and curriculum policies.</li>
                      <li>Fees are paid in advance.</li>
                    </ul>
                    <label className="flex items-start gap-3 cursor-pointer">
                       <input 
                          type="checkbox" 
                          name="agreed" 
                          checked={formData.agreed} 
                          onChange={handleChange}
                          className="mt-1 w-6 h-6 accent-coha-900"
                        />
                       <span className="text-sm font-bold text-gray-900">
                         I declare that information is true and accept terms.
                       </span>
                    </label>
                    {errors.agreed && <p className="text-red-700 text-xs mt-2 font-bold uppercase">{errors.agreed}</p>}
                 </div>
             </div>
          </div>
        )}

        {/* Action Buttons & Feedback */}
        <div className="mt-8 flex flex-col items-center gap-6 pt-6 border-t border-gray-100 w-full">
           {stepError && (
              <div className={`flex items-center gap-3 text-red-600 p-4 bg-red-50 border border-red-100 w-full justify-center transition-all ${shakeError ? 'animate-shake' : ''}`}>
                 <AlertCircle size={20} />
                 <span className="text-sm font-bold">{stepError}</span>
              </div>
           )}

           <div className="flex gap-4 w-full">
              <Button 
                type="button" 
                variant="outline"
                onClick={handleBack} 
                className={`flex-1 ${currentStep === 0 ? 'invisible' : ''}`}
              >
                Back
              </Button>

              {currentStep < STEPS.length - 1 ? (
                <Button type="button" onClick={handleNext} className="flex-1 bg-coha-500 hover:bg-coha-600 border-none rounded-lg">
                  Next <ArrowRight size={18} />
                </Button>
              ) : (
                <Button 
                  type="submit" 
                  disabled={loading}
                  className={`flex-1 rounded-lg border-none text-white ${shakeError ? 'animate-shake bg-red-600' : 'bg-coha-900'}`}
                >
                  {loading ? 'Sending...' : 'Submit Application'}
                </Button>
              )}
           </div>
        </div>

      </form>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getApplicationById, updateApplication, getSystemSettings, approveApplicationInitial } from '../../services/dataService';
import { Application, SystemSettings } from '../../types';
import { Button } from '../../components/ui/Button';
import { Loader } from '../../components/ui/Loader';
import { Input } from '../../components/ui/Input';
import { ArrowLeft, Check, X, Printer, AlertTriangle } from 'lucide-react';
import { ConfirmModal } from '../../components/ui/ConfirmModal';

export const ApplicationDetailsPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [app, setApp] = useState<Application | null>(null);
  const [settings, setSettings] = useState<SystemSettings | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [rejectModalOpen, setRejectModalOpen] = useState(false);

  // Office Use State
  const [officeData, setOfficeData] = useState({
    officeReviewer: '',
    officeReviewDate: new Date().toISOString().split('T')[0],
    officeStatus: 'Successful',
    officeResponseMethod: 'Email',
    officeResponseDate: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    const fetchData = async () => {
      if (id) {
        const appData = await getApplicationById(id);
        const settingsData = await getSystemSettings();
        setApp(appData);
        setSettings(settingsData);

        if (settingsData?.adminName) {
            setOfficeData(prev => ({...prev, officeReviewer: settingsData.adminName}));
        }

        if (appData?.officeReviewer) {
            setOfficeData({
                officeReviewer: appData.officeReviewer || '',
                officeReviewDate: appData.officeReviewDate || '',
                officeStatus: appData.officeStatus || 'Successful',
                officeResponseMethod: appData.officeResponseMethod || 'Email',
                officeResponseDate: appData.officeResponseDate || ''
            });
        }
      }
    };
    fetchData();
  }, [id]);

  const handleOfficeChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setOfficeData({ ...officeData, [e.target.name]: e.target.value });
  };

  const handleApprove = async () => {
    if (!app || !id) return;
    setIsProcessing(true);

    try {
        const updatedData = {
            status: 'APPROVED' as any,
            ...officeData
        };

        await updateApplication(id, updatedData);
        setApp({ ...app, ...updatedData });

        // 1. Initial Approval -> Create Student with "WAITING_PAYMENT"
        const result = await approveApplicationInitial(app);

        if (settings && result) {
            const parentEmail = app.fatherEmail || app.motherEmail; 
            const subject = `Admission Conditional Approval: ${app.firstName} ${app.surname} - Circle of Hope Academy`;

            const body = `Dear Parent/Guardian,

Your application for ${app.firstName} ${app.surname} has been CONDITIONALLY APPROVED.

PLEASE NOTE: A non-refundable Registration Fee of N$300.00 is payable immediately to secure enrolment.

NEXT STEP: PAYMENT CONFIRMATION
To finalize the enrollment, you must login to the Parent Portal and enter your application fee receipt number.

LOGIN DETAILS:
Student Name: ${app.firstName} ${app.surname}
Parent PIN: ${result.pin}

FEES STRUCTURE 2026:
-----------------------------------------------------------------------------------------
Fee Category                       | Amount        | Frequency / Notes
-----------------------------------------------------------------------------------------
Registration Fee                   | N$ 300.00     | Once-off (Non-refundable)
Tuition (Special Classes)          | N$ 2,300.00   | Monthly (Per learner)
Tuition (Mainstream - Termly)      | N$ 7,100.00   | Per Term (Paid in advance)
Kindergarten (Mainstream)          | N$ 550.00     | Monthly
Pre-Primary (Mainstream)           | N$ 650.00     | Monthly
Grades 1-3 (Mainstream)            | N$ 1,300.00   | Monthly
Grades 4-7 (Mainstream)            | N$ 1,700.00   | Monthly
Hostel Fees                        | N$ 1,400.00   | Per month (Boarders)
-----------------------------------------------------------------------------------------

BANKING DETAILS (TUITION, REGISTRATION & HOSTEL):
Bank Name: First National Bank
Account Name: COHA TUTORIAL ACADEMY
Account Number: 64283855814
Branch: Ongwediva
Reference: ${app.firstName} ${app.surname} (Learner's Full Name)

FOOD CONTRIBUTION (HOSTEL ONLY):
Hostel food: N$ 3,500.00 (Per Term)
Pay into Metro Bank Account:
Bank: First National Bank
Account Name: SEFLANA CASH AND CURRY
Account No: 62260164539 (Cheque)
Reference: 22229 + ${app.firstName} ${app.surname}

IMPORTANT:
Please email all proof of payment to acoha67@gmail.com within 48 hours of payment.

Please login at the school portal to verify your payment and proceed to the observation/assessment phase.

Regards,
${settings.adminName}
Circle of Hope Academy`;

            window.location.href = `mailto:${parentEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
        }
    } catch (error) {
        console.error("Error approving:", error);
    }
    setIsProcessing(false);
  };

  const handleReject = async () => {
      if (!app || !id) return;
      setIsProcessing(true);
      try {
          await updateApplication(id, { status: 'REJECTED' });
          setRejectModalOpen(false);
          setApp({...app, status: 'REJECTED'});

          // Send Rejection Email
          const subject = `Admission Update: ${app.firstName} ${app.surname}`;
          const body = `Dear Parent/Guardian,\n\nWe regret to inform you that the application for ${app.firstName} ${app.surname} was not successful at this time.\n\nRegards,\nCircle of Hope Academy`;
           window.location.href = `mailto:${app.fatherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
      } catch (e) {
          console.error(e);
      }
      setIsProcessing(false);
  };

  if (!app) return <Loader />;

  const Section: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className = '' }) => (
    <div className={`bg-white p-6 shadow-sm border border-gray-200 mb-6 ${className}`}>
      <h3 className="text-lg font-bold text-coha-900 mb-4 border-b pb-2 uppercase tracking-wider">{title}</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4">
        {children}
      </div>
    </div>
  );

  const InfoRow: React.FC<{ label: string; value: any }> = ({ label, value }) => (
    <div className="mb-2">
      <p className="text-xs text-gray-500 uppercase font-bold">{label}</p>
      <p className={`text-gray-900 font-medium break-words ${!value ? 'text-gray-400 italic' : ''}`}>{value || 'Not provided'}</p>
    </div>
  );

  return (
    <div className="w-full px-5 pb-10">
        <ConfirmModal 
            isOpen={rejectModalOpen}
            onClose={() => setRejectModalOpen(false)}
            onConfirm={handleReject}
            title="Reject Application?"
            message="Are you sure you want to reject this application? This action will mark it as rejected."
            isLoading={isProcessing}
        />

        <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-4">
                <button onClick={() => navigate('/admin/applications')} className="bg-white p-2 border hover:bg-gray-50">
                    <ArrowLeft size={20} />
                </button>
                <div>
                    <h2 className="text-2xl font-bold text-coha-900">{app.surname}, {app.firstName}</h2>
                    <p className="text-gray-600">Application ID: {app.id}</p>
                </div>
            </div>
            <div className="flex gap-2">
                <Button variant="outline" onClick={() => window.print()}>
                    <Printer size={18} /> Print
                </Button>
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2">
                <Section title="Learner Details">
                    <InfoRow label="Full Name" value={`${app.firstName} ${app.surname}`} />
                    <InfoRow label="Date of Birth" value={app.dob} />
                    <InfoRow label="Gender" value={app.gender} />
                    <InfoRow label="Citizenship" value={app.citizenship} />
                    <InfoRow label="Grade Applied" value={app.grade} />
                    <InfoRow label="Residential Address" value={app.address} />
                    <InfoRow label="Region" value={app.region} />
                    <InfoRow label="Special Needs" value={app.isSpecialNeeds ? `Yes - ${app.specialNeedsType}` : 'No'} />
                </Section>
                <Section title="Parent / Guardian Info">
                    <InfoRow label="Father Name" value={app.fatherName} />
                    <InfoRow label="Father Phone" value={app.fatherPhone} />
                    <InfoRow label="Father Email" value={app.fatherEmail} />
                    <div className="md:col-span-2 border-t pt-2 mt-2"></div>
                    <InfoRow label="Mother Name" value={app.motherName} />
                    <InfoRow label="Mother Phone" value={app.motherPhone} />
                </Section>
                <Section title="Emergency Contact">
                    <InfoRow label="Full Name" value={app.emergencyName} />
                    <InfoRow label="Relationship" value={app.emergencyRelationship} />
                    <InfoRow label="Cell Number" value={app.emergencyCell} />
                    <InfoRow label="Work Contact" value={app.emergencyWork} />
                    <InfoRow label="Email" value={app.emergencyEmail} />
                </Section>
                <Section title="Educational History">
                    <InfoRow label="First Time Attender" value={!app.hasPreviousSchool ? 'Yes' : 'No'} />
                    {app.hasPreviousSchool && (
                        <>
                            <InfoRow label="Previous School" value={app.previousSchool} />
                            <InfoRow label="Highest Grade Completed" value={app.highestGrade} />
                        </>
                    )}
                    <div className="md:col-span-2 border-t pt-2 mt-2"></div>
                    <InfoRow label="English Proficiency" value={app.langEnglish} />
                    <InfoRow label="Other Language 1" value={app.langOther1Name ? `${app.langOther1Name} (${app.langOther1Rating})` : null} />
                    <InfoRow label="Other Language 2" value={app.langOther2Name ? `${app.langOther2Name} (${app.langOther2Rating})` : null} />
                </Section>
                <Section title="Medical Information">
                     <InfoRow label="Medical Conditions / Allergies" value={app.medicalConditions} />
                     <div className="md:col-span-2 border-t pt-2 mt-2 grid md:grid-cols-2 gap-4">
                        <InfoRow label="Family Doctor" value={app.doctorName ? `${app.doctorName} (${app.doctorContact})` : null} />
                        <InfoRow label="Audiologist" value={app.audiologistName ? `${app.audiologistName} (${app.audiologistContact})` : null} />
                        <InfoRow label="Occupational Therapist" value={app.therapistName ? `${app.therapistName} (${app.therapistContact})` : null} />
                     </div>
                     <div className="md:col-span-2 border-t pt-2 mt-2"></div>
                     <InfoRow label="Medical Aid" value={app.hasMedicalAid ? 'Yes' : 'No'} />
                     {app.hasMedicalAid && (
                         <>
                            <InfoRow label="Medical Aid Name" value={app.medicalAidName} />
                            <InfoRow label="Plan Option" value={app.medicalAidOption} />
                            <InfoRow label="Member Name" value={app.medicalAidMemberName} />
                            <InfoRow label="Member ID" value={app.medicalAidMemberID} />
                         </>
                     )}
                </Section>
                 <Section title="Declarations">
                    <InfoRow label="Medical Consent Given" value={app.medicalConsent ? 'Yes' : 'No'} />
                    <InfoRow label="Terms & Conditions Accepted" value={app.agreed ? 'Yes' : 'No'} />
                    <InfoRow label="Submission Date" value={app.submissionDate?.toDate().toLocaleString()} />
                </Section>
            </div>

            <div className="lg:col-span-1">
                {/* Office Use Section */}
                <div className="bg-coha-50 p-6 border-l-4 border-coha-900 sticky top-24">
                    <h3 className="text-lg font-bold text-coha-900 mb-6 uppercase tracking-wider">Office Use Only</h3>

                    {app.status === 'APPROVED' ? (
                        <div className="text-center py-8">
                            <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Check size={32} />
                            </div>
                            <h3 className="font-bold text-green-800 text-xl">Approved</h3>
                            <p className="text-green-600">Awaiting Payment Verification</p>
                        </div>
                    ) : app.status === 'REJECTED' ? (
                        <div className="text-center py-8">
                             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
                                <X size={32} />
                            </div>
                            <h3 className="font-bold text-red-800 text-xl">Rejected</h3>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            <Input label="Reviewed By" name="officeReviewer" value={officeData.officeReviewer} onChange={handleOfficeChange} />
                            <Input label="Date of Review" type="date" name="officeReviewDate" value={officeData.officeReviewDate} onChange={handleOfficeChange} />

                            <div className="pt-6 flex flex-col gap-3">
                                <Button fullWidth onClick={handleApprove} disabled={isProcessing} className="bg-green-600 hover:bg-green-700 border-none">
                                    {isProcessing ? 'Processing...' : <><Check size={20} /> Approve & Request Payment</>}
                                </Button>
                                <Button fullWidth onClick={() => setRejectModalOpen(true)} disabled={isProcessing} variant="danger">
                                    <X size={20} /> Reject Application
                                </Button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getStudentById, getSystemSettings, getTeacherByClass, getReceipts } from '../../services/dataService';
import { Student, Teacher, SystemSettings } from '../../types';
import { Loader } from '../../components/ui/Loader';
import { User, BookOpen, Calendar, DollarSign, CheckCircle, Clock, AlertTriangle, ArrowRight } from 'lucide-react';
import { Button } from '../../components/ui/Button';

interface ParentDashboardProps {
  user: any;
}

export const ParentDashboard: React.FC<ParentDashboardProps> = ({ user }) => {
  const navigate = useNavigate();
  const [student, setStudent] = useState<Student | null>(null);
  const [teacher, setTeacher] = useState<Teacher | null>(null);
  const [settings, setSettings] = useState<SystemSettings | null>(null);
  const [financials, setFinancials] = useState({ totalFees: 0, paid: 0, balance: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      if (user?.id) {
        const stud = await getStudentById(user.id);
        const setts = await getSystemSettings();
        setStudent(stud);
        setSettings(setts);

        if (stud) {
           if (stud.assignedClass) {
               const t = await getTeacherByClass(stud.assignedClass);
               setTeacher(t);
           }

           if (setts && setts.fees) {
               let monthlyFee = 0;
               const feeItem = setts.fees.find(f => f.category.includes('Tuition'));
               if (feeItem) monthlyFee = parseFloat(feeItem.amount) || 0;

               const allReceipts = await getReceipts();
               const studentReceipts = allReceipts.filter(r => r.usedByStudentId === stud.id);
               const totalPaid = studentReceipts.reduce((acc, r) => acc + parseFloat(r.amount), 0);
               const totalYearly = monthlyFee * 12;

               setFinancials({
                   totalFees: totalYearly,
                   paid: totalPaid,
                   balance: totalYearly - totalPaid
               });
           }
        }
      }
      setLoading(false);
    };
    fetchData();
  }, [user]);

  if (loading) return <Loader />;
  if (!student) return <div className="p-8">Student not found.</div>;

  const isEnrolled = student.studentStatus === 'ENROLLED';
  const isAssessment = student.studentStatus === 'ASSESSMENT';
  const isWaitingPayment = student.studentStatus === 'WAITING_PAYMENT';

  return (
    <div className="max-w-6xl mx-auto space-y-6">

      {/* Header / Welcome */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 shadow-sm border-l-8 border-coha-900">
        <div>
           <h2 className="text-2xl font-bold text-gray-900">Welcome, {student.parentName}</h2>
           <p className="text-gray-600">Parent Dashboard for <span className="font-bold text-coha-900">{student.name}</span></p>
        </div>
        <div className="flex items-center gap-2">
            <span className={`px-4 py-2 rounded-full text-sm font-bold uppercase flex items-center gap-2 border
                ${isEnrolled ? 'bg-green-100 text-green-700 border-green-200' : 
                  isWaitingPayment ? 'bg-red-100 text-red-700 border-red-200' :
                  'bg-purple-100 text-purple-700 border-purple-200'}
            `}>
                {isEnrolled ? <CheckCircle size={18}/> : <Clock size={18}/>}
                {student.studentStatus.replace('_', ' ')}
            </span>
        </div>
      </div>

      {/* ACTION REQUIRED: Pending Payment */}
      {isWaitingPayment && (
          <div className="bg-red-50 border-2 border-red-200 p-6 shadow-lg animate-pulse hover:animate-none transition-all">
              <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                  <div className="flex items-start gap-4 text-center md:text-left">
                      <div className="bg-red-100 p-3 rounded-full text-red-600 shrink-0 mx-auto md:mx-0">
                          <AlertTriangle size={32} />
                      </div>
                      <div>
                          <h3 className="text-xl font-bold text-red-900 uppercase tracking-tighter">Action Required: Registration Payment</h3>
                          <p className="text-red-800 font-medium">
                              Your application has been conditionally approved. To secure your spot, please pay the <b>N$300</b> registration fee and enter the receipt number.
                          </p>
                      </div>
                  </div>
                  <Button 
                    onClick={() => navigate('/parent/assessment-form')}
                    className="bg-red-600 hover:bg-red-700 border-none px-8 py-4 text-lg animate-bounce"
                  >
                    Enter Receipt Number <ArrowRight size={20} />
                  </Button>
              </div>
          </div>
      )}

      {/* Notification for Completed Assessment */}
      {isEnrolled && student.assessment?.isComplete && (
          <div className="bg-green-50 border border-green-200 p-6 rounded-lg flex items-start gap-4 animate-fade-in">
              <div className="bg-green-100 p-3 rounded-full text-green-600 shrink-0">
                  <CheckCircle size={24} />
              </div>
              <div>
                  <h3 className="text-lg font-bold text-green-800">Assessment Complete!</h3>
                  <p className="text-green-700 mb-2">
                      Great news! The 14-day observation period has been successfully completed. 
                      Based on the assessment results, your child has been placed in:
                  </p>
                  <div className="text-2xl font-bold text-coha-900 bg-white inline-block px-4 py-2 border border-green-200 rounded shadow-sm">
                      {student.assignedClass}
                  </div>
              </div>
          </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Card 1: Class Info */}
          <div className="bg-white p-6 shadow-sm border-t-4 border-coha-500">
             <div className="flex items-center gap-3 mb-4 text-gray-700 border-b pb-2">
                 <BookOpen className="text-coha-500" size={20} />
                 <h3 className="font-bold text-xs uppercase tracking-widest">Class Details</h3>
             </div>
             <div className="space-y-3">
                 <div>
                     <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Assigned Class</p>
                     <p className="text-xl font-black text-gray-900">{student.assignedClass || 'Pending Placement'}</p>
                 </div>
                 <div>
                     <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Division</p>
                     <p className="text-gray-900 font-bold">{student.division}</p>
                 </div>
                 <div>
                     <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Academic Term</p>
                     <p className="text-gray-900 font-bold">Term 1, 2026</p>
                 </div>
             </div>
          </div>

          {/* Card 2: Teacher Info */}
          <div className="bg-white p-6 shadow-sm border-t-4 border-purple-500">
             <div className="flex items-center gap-3 mb-4 text-gray-700 border-b pb-2">
                 <User className="text-purple-500" size={20} />
                 <h3 className="font-bold text-xs uppercase tracking-widest">Class Teacher</h3>
             </div>
             {teacher ? (
                 <div className="space-y-3">
                    <div>
                        <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Name</p>
                        <p className="text-xl font-black text-gray-900">{teacher.name}</p>
                    </div>
                    <div>
                        <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Email Address</p>
                        <p className="text-gray-900 font-bold">{teacher.email || 'Not available'}</p>
                    </div>
                    <button className="text-xs text-purple-600 font-black uppercase tracking-widest hover:underline mt-2">Send Message</button>
                 </div>
             ) : (
                 <p className="text-gray-500 italic text-sm">Teacher assignment will be finalized after assessment.</p>
             )}
          </div>

          {/* Card 3: Financials */}
          <div className="bg-white p-6 shadow-sm border-t-4 border-green-500">
             <div className="flex items-center gap-3 mb-4 text-gray-700 border-b pb-2">
                 <DollarSign className="text-green-500" size={20} />
                 <h3 className="font-bold text-xs uppercase tracking-widest">Financial Summary</h3>
             </div>
             <div className="space-y-4">
                 <div className="flex justify-between items-center text-sm">
                     <span className="text-gray-500 font-bold uppercase">Expected (Annual)</span>
                     <span className="font-black text-gray-900">N$ {financials.totalFees.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-green-700 text-sm">
                     <span className="font-black uppercase">Verified Paid</span>
                     <span className="font-black">N$ {financials.paid.toLocaleString()}</span>
                 </div>
                 <div className="border-t pt-3 flex justify-between items-center">
                     <span className="text-red-600 font-black uppercase text-xs">Balance Outstanding</span>
                     <span className="font-black text-2xl text-red-600 tracking-tighter">N$ {financials.balance.toLocaleString()}</span>
                 </div>
                 <button className="w-full py-3 bg-coha-900 text-white text-[10px] font-black uppercase tracking-widest hover:bg-coha-800 transition-colors shadow-md">
                     View All Receipts
                 </button>
             </div>
          </div>
      </div>

    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getApplications, getStudentsByStatus, verifyPayment, rejectPayment, getReceipts, addReceipt, deleteReceipt, deleteStudent, getPendingActionCounts } from '../../services/dataService';
import { Application, Student, Receipt } from '../../types';
import { Eye, Clock, Search, Filter, Check, X, Plus, Trash2, Key, Mail, DollarSign, Brain, ArrowRight } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Toast } from '../../components/ui/Toast';
import { ConfirmModal } from '../../components/ui/ConfirmModal';

type ViewMode = 'APPLICATIONS' | 'PENDING_PAYMENT' | 'VERIFICATION' | 'RECEIPTS';

export const ApplicationsPage: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('APPLICATIONS');
  const [applications, setApplications] = useState<Application[]>([]);
  const [pendingPaymentList, setPendingPaymentList] = useState<Student[]>([]);
  const [verificationList, setVerificationList] = useState<Student[]>([]);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'PENDING' | 'REJECTED'>('PENDING');
  const navigate = useNavigate();

  // Counts for Badges
  const [counts, setCounts] = useState({ pendingApps: 0, pendingVerifications: 0, total: 0 });

  // Receipts State
  const [newReceiptNumber, setNewReceiptNumber] = useState('');
  const [newReceiptAmount, setNewReceiptAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ msg: '', show: false, type: 'success' as 'success' | 'error' });

  // Delete State
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Email/Verify Modal State
  const [emailModalOpen, setEmailModalOpen] = useState(false);
  const [verifyResult, setVerifyResult] = useState<{success: boolean, student: Student | null, message: string}>({success: false, student: null, message: ''});

  useEffect(() => {
    loadData();
    getPendingActionCounts().then(setCounts);
  }, [viewMode]);

  const loadData = async () => {
    if (viewMode === 'APPLICATIONS') {
        const data = await getApplications();
        setApplications(data);
    } else if (viewMode === 'PENDING_PAYMENT') {
        const data = await getStudentsByStatus('WAITING_PAYMENT');
        setPendingPaymentList(data);
    } else if (viewMode === 'VERIFICATION') {
        const data = await getStudentsByStatus('PAYMENT_VERIFICATION');
        setVerificationList(data);
    } else if (viewMode === 'RECEIPTS') {
        const data = await getReceipts();
        setReceipts(data);
    }
  };

  const handleVerifyClick = async (student: Student) => {
    if (!student.receiptNumber) return;
    setLoading(true);
    const result = await verifyPayment(student.id, student.receiptNumber);
    setLoading(false);

    setVerifyResult({
        success: result.success,
        student: student,
        message: result.success ? 'Payment Verified Successfully.' : 'Invalid Receipt Number.'
    });
    setEmailModalOpen(true);
  };

  const finalizeVerification = async (sendEmail: boolean) => {
     if (!verifyResult.student) return;
     const student = verifyResult.student;

     if (verifyResult.success) {
         if (sendEmail) {
             const subject = "Enrollment Update: Payment Verified";
             const body = `Dear ${student.parentName},

We have successfully verified your payment receipt (${student.receiptNumber}).

The student ${student.name} is now queued for assessment.

Regards,
Circle of Hope Academy`;
             window.location.href = `mailto:${student.fatherEmail || student.motherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
         }
         setToast({ msg: 'Student moved to Assessment.', show: true, type: 'success' });
     } else {
         await rejectPayment(student.id);
         if (sendEmail) {
             const subject = "Enrollment Update: Payment Verification Failed";
             const body = `Dear ${student.parentName},

The receipt number (${student.receiptNumber}) provided for ${student.name} could not be verified.

Please check the number and try again on the parent portal.

Regards,
Circle of Hope Academy`;
             window.location.href = `mailto:${student.fatherEmail || student.motherEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
         }
         setToast({ msg: 'Payment Rejected. Parent notified on dashboard.', show: true, type: 'error' });
     }

     setEmailModalOpen(false);
     loadData();
     getPendingActionCounts().then(setCounts);
  };

  const confirmDelete = (student: Student) => {
      setStudentToDelete(student);
      setDeleteModalOpen(true);
  };

  const handleDeleteStudent = async () => {
      if (studentToDelete) {
          await deleteStudent(studentToDelete.id);
          setDeleteModalOpen(false);
          setStudentToDelete(null);
          loadData();
          setToast({ msg: 'Record deleted successfully', show: true, type: 'success' });
      }
  };

  const handleAddReceipt = async () => {
      if (!newReceiptNumber || !newReceiptAmount) return;
      setLoading(true);
      const success = await addReceipt(newReceiptNumber, newReceiptAmount, new Date().toISOString());
      if (success) {
          setNewReceiptNumber('');
          setNewReceiptAmount('');
          loadData();
          setToast({ msg: 'Receipt added successfully', show: true, type: 'success' });
      }
      setLoading(false);
  };

  const handleDeleteReceipt = async (id: string) => {
      if(window.confirm('Delete this receipt?')) {
          await deleteReceipt(id);
          loadData();
      }
  };

  const filteredApps = applications.filter(app => {
      const matchesSearch = (() => {
        const fullName = `${app.firstName} ${app.surname}`.toLowerCase();
        const parent = (app.fatherName || app.motherName || '').toLowerCase();
        const term = searchTerm.toLowerCase();
        return fullName.includes(term) || parent.includes(term) || (app.grade || '').toLowerCase().includes(term);
      })();
      return matchesSearch && app.status === statusFilter;
  });

  return (
    <div>
      <Toast message={toast.msg} isVisible={toast.show} onClose={() => setToast({...toast, show: false})} variant={toast.type} />

      <ConfirmModal 
        isOpen={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        onConfirm={handleDeleteStudent}
        title="Delete Record?"
        message={`Are you sure you want to delete ${studentToDelete?.name}? This will permanently remove them from the admission process.`}
      />

      {/* ENHANCED VERIFICATION MODAL */}
      {emailModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
            <div className={`bg-white w-full max-w-2xl shadow-2xl border-t-8 ${verifyResult.success ? 'border-green-600' : 'border-red-600'} animate-fade-in max-h-[90vh] overflow-y-auto`}>
                <div className="p-8">
                    <div className="flex items-center gap-4 mb-6">
                        <div className={`p-4 rounded-full ${verifyResult.success ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                            {verifyResult.success ? <Check size={32} /> : <X size={32} />}
                        </div>
                        <div>
                            <h3 className={`text-2xl font-black uppercase tracking-tighter leading-none ${verifyResult.success ? 'text-green-800' : 'text-red-800'}`}>
                                {verifyResult.success ? 'Payment Verified' : 'Verification Failed'}
                            </h3>
                            <p className="text-gray-500 font-bold text-xs uppercase tracking-widest mt-1">Student: {verifyResult.student?.name}</p>
                        </div>
                    </div>

                    {verifyResult.success && (
                        <div className="space-y-6 mb-8">
                            {/* Fee Structure Information */}
                            <div className="bg-gray-50 p-4 border border-gray-200">
                                <h4 className="text-[10px] font-black uppercase text-gray-500 tracking-[0.2em] mb-4 flex items-center gap-2">
                                    <DollarSign size={14} /> Confirmed Fee Structure 2026
                                </h4>
                                <div className="text-xs space-y-2 font-medium">
                                    <div className="flex justify-between border-b border-gray-200 pb-1">
                                        <span className="text-gray-600">Registration Fee (Once-off)</span>
                                        <span className="font-bold">N$ 300.00</span>
                                    </div>
                                    <div className="flex justify-between border-b border-gray-200 pb-1">
                                        <span className="text-gray-600">Tuition (Special Classes)</span>
                                        <span className="font-bold">N$ 2,300.00 / month</span>
                                    </div>
                                    <div className="flex justify-between border-b border-gray-200 pb-1">
                                        <span className="text-gray-600">Tuition (Mainstream)</span>
                                        <span className="font-bold">N$ 7,100.00 / term</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-600">Hostel Fees</span>
                                        <span className="font-bold">N$ 1,400.00 / month</span>
                                    </div>
                                </div>
                            </div>

                            <div className="bg-green-50 p-5 border-l-4 border-green-500">
                                <p className="text-lg font-black text-green-900 leading-tight">
                                    <b>NEXT STEP:</b> The student is now officially in the 14-day observation phase. Please inform the teacher to begin tracking core domains.
                                </p>
                            </div>
                        </div>
                    )}

                    {!verifyResult.success && (
                        <div className="bg-red-50 p-6 border-l-4 border-red-500 mb-8">
                            <p className="font-bold text-red-900 leading-relaxed">
                                <b>NEXT STEP:</b> Notify the parent that the receipt provided could not be matched with any available school records. They must re-submit a valid receipt.
                            </p>
                        </div>
                    )}

                    <div className="flex flex-col gap-3">
                        {verifyResult.success && (
                            <Button fullWidth onClick={() => {
                                setEmailModalOpen(false);
                                navigate(`/admin/assessment/${verifyResult.student?.id}`);
                            }} className="bg-coha-900 hover:bg-coha-800 border-none py-4 text-xs font-black uppercase tracking-widest shadow-lg">
                                <Brain size={18} /> Open Assessment Form <ArrowRight size={18} />
                            </Button>
                        )}
                        <Button fullWidth variant="outline" onClick={() => finalizeVerification(true)} className="py-4 text-xs font-black uppercase tracking-widest">
                            <Mail size={18} /> Notify Parent via Email
                        </Button>
                        <Button fullWidth variant="outline" onClick={() => finalizeVerification(false)} className="py-4 text-xs font-black uppercase tracking-widest border-gray-200 text-gray-400">
                            Skip Notification & Close
                        </Button>
                    </div>
                </div>
            </div>
          </div>
      )}

      <div className="mb-6 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-coha-900">Admissions Management</h2>
            <p className="text-gray-600">Manage applications, verify payments, and issue receipts.</p>
        </div>
        <div className="flex flex-wrap bg-white shadow-sm border border-gray-200">
            <button 
                onClick={() => setViewMode('APPLICATIONS')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'APPLICATIONS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Applications
                {counts.pendingApps > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{counts.pendingApps}</span>}
            </button>
            <button 
                onClick={() => setViewMode('PENDING_PAYMENT')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'PENDING_PAYMENT' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Pending Payment
            </button>
            <button 
                onClick={() => setViewMode('VERIFICATION')} 
                className={`px-4 py-2 text-sm font-bold uppercase flex items-center gap-2 ${viewMode === 'VERIFICATION' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}
            >
                Payment Verification
                {counts.pendingVerifications > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{counts.pendingVerifications}</span>}
            </button>
            <button onClick={() => setViewMode('RECEIPTS')} className={`px-4 py-2 text-sm font-bold uppercase ${viewMode === 'RECEIPTS' ? 'bg-coha-900 text-white' : 'text-gray-600 hover:bg-gray-50'}`}>Available Receipts</button>
        </div>
      </div>

      {/* MODE: APPLICATIONS (New / Rejected) */}
      {viewMode === 'APPLICATIONS' && (
          <div className="animate-fade-in">
             <div className="flex border-b border-gray-200 mb-6 bg-white shadow-sm overflow-x-auto">
                <button onClick={() => setStatusFilter('PENDING')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 flex items-center gap-2 ${statusFilter === 'PENDING' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>
                    Pending
                    {counts.pendingApps > 0 && <span className="bg-red-100 text-red-600 text-[10px] px-1.5 py-0.5 rounded-full">{counts.pendingApps}</span>}
                </button>
                <button onClick={() => setStatusFilter('REJECTED')} className={`px-6 py-3 font-bold text-sm uppercase border-b-4 ${statusFilter === 'REJECTED' ? 'border-coha-900 text-coha-900' : 'border-transparent text-gray-500'}`}>Rejected</button>
             </div>

             <div className="bg-white border border-gray-200 shadow-sm">
                <div className="p-4 border-b border-gray-200">
                    <div className="relative max-w-md">
                        <Search className="absolute left-3 top-3 text-gray-400" size={20} />
                        <input className="w-full pl-10 pr-4 py-2 border border-gray-300 outline-none" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                    </div>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-600">
                            <tr>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-6 py-4">Name</th>
                                <th className="px-6 py-4">Grade</th>
                                <th className="px-6 py-4">Parent</th>
                                <th className="px-6 py-4">Date</th>
                                <th className="px-6 py-4">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {filteredApps.map((app) => (
                                <tr key={app.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-bold border ${app.status === 'REJECTED' ? 'bg-red-100 text-red-800 border-red-200' : 'bg-yellow-100 text-yellow-800 border-yellow-200'}`}>{app.status}</span></td>
                                    <td className="px-6 py-4 font-bold text-coha-900">{app.surname}, {app.firstName}</td>
                                    <td className="px-6 py-4">{app.grade}</td>
                                    <td className="px-6 py-4">{app.fatherName || app.motherName}</td>
                                    <td className="px-6 py-4 text-xs">{app.submissionDate?.toDate().toLocaleDateString()}</td>
                                    <td className="px-6 py-4"><button onClick={() => navigate(`/admin/applications/${app.id}`)} className="text-coha-500 font-bold text-sm flex gap-1 items-center"><Eye size={16}/> View</button></td>
                                </tr>
                            ))}
                            {filteredApps.length === 0 && <tr><td colSpan={6} className="text-center py-8 text-gray-500">No applications found.</td></tr>}
                        </tbody>
                    </table>
                </div>
             </div>
          </div>
      )}

