                                {student.studentStatus === 'ENROLLED' && <CheckCircle size={24} className="text-green-400" />}
                            </div>
                            <div className="flex flex-wrap items-center gap-x-6 gap-y-2 font-bold text-[11px] uppercase tracking-widest text-coha-300">
